window.SHAKESPEARE_ENGLISH["lll"] = {"id":"lll","title":"Love's Labours Lost","kind":"play","source":"MIT Shakespeare (Complete Moby Shakespeare)","sourceUrl":"https://shakespeare.mit.edu/lll/full.html","sourceRevision":"6b82db852c7322dd33e95db347f0ddfc812c6409","sections":[{"id":"1.1","label":"Act 1 · SCENE I. The king of Navarre's park.","act":1,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter FERDINAND king of Navarre, BIRON, LONGAVILLE and DUMAIN","id":"lll:1.1:1"},{"kind":"speech","text":"Let fame, that all hunt after in their lives,\nLive register'd upon our brazen tombs\nAnd then grace us in the disgrace of death;\nWhen, spite of cormorant devouring Time,\nThe endeavor of this present breath may buy\nThat honour which shall bate his scythe's keen edge\nAnd make us heirs of all eternity.\nTherefore, brave conquerors,--for so you are,\nThat war against your own affections\nAnd the huge army of the world's desires,--\nOur late edict shall strongly stand in force:\nNavarre shall be the wonder of the world;\nOur court shall be a little Academe,\nStill and contemplative in living art.\nYou three, Biron, Dumain, and Longaville,\nHave sworn for three years' term to live with me\nMy fellow-scholars, and to keep those statutes\nThat are recorded in this schedule here:\nYour oaths are pass'd; and now subscribe your names,\nThat his own hand may strike his honour down\nThat violates the smallest branch herein:\nIf you are arm'd to do as sworn to do,\nSubscribe to your deep oaths, and keep it too.","sourceLine":"1.1.1","speaker":"FERDINAND","id":"lll:1.1:2"},{"kind":"speech","text":"I am resolved; 'tis but a three years' fast:\nThe mind shall banquet, though the body pine:\nFat paunches have lean pates, and dainty bits\nMake rich the ribs, but bankrupt quite the wits.","sourceLine":"1.1.24","speaker":"LONGAVILLE","id":"lll:1.1:3"},{"kind":"speech","text":"My loving lord, Dumain is mortified:\nThe grosser manner of these world's delights\nHe throws upon the gross world's baser slaves:\nTo love, to wealth, to pomp, I pine and die;\nWith all these living in philosophy.","sourceLine":"1.1.28","speaker":"DUMAIN","id":"lll:1.1:4"},{"kind":"speech","text":"I can but say their protestation over;\nSo much, dear liege, I have already sworn,\nThat is, to live and study here three years.\nBut there are other strict observances;\nAs, not to see a woman in that term,\nWhich I hope well is not enrolled there;\nAnd one day in a week to touch no food\nAnd but one meal on every day beside,\nThe which I hope is not enrolled there;\nAnd then, to sleep but three hours in the night,\nAnd not be seen to wink of all the day--\nWhen I was wont to think no harm all night\nAnd make a dark night too of half the day--\nWhich I hope well is not enrolled there:\nO, these are barren tasks, too hard to keep,\nNot to see ladies, study, fast, not sleep!","sourceLine":"1.1.33","speaker":"BIRON","id":"lll:1.1:5"},{"kind":"speech","text":"Your oath is pass'd to pass away from these.","sourceLine":"1.1.49","speaker":"FERDINAND","id":"lll:1.1:6"},{"kind":"speech","text":"Let me say no, my liege, an if you please:\nI only swore to study with your grace\nAnd stay here in your court for three years' space.","sourceLine":"1.1.50","speaker":"BIRON","id":"lll:1.1:7"},{"kind":"speech","text":"You swore to that, Biron, and to the rest.","sourceLine":"1.1.53","speaker":"LONGAVILLE","id":"lll:1.1:8"},{"kind":"speech","text":"By yea and nay, sir, then I swore in jest.\nWhat is the end of study? let me know.","sourceLine":"1.1.54","speaker":"BIRON","id":"lll:1.1:9"},{"kind":"speech","text":"Why, that to know, which else we should not know.","sourceLine":"1.1.56","speaker":"FERDINAND","id":"lll:1.1:10"},{"kind":"speech","text":"Things hid and barr'd, you mean, from common sense?","sourceLine":"1.1.57","speaker":"BIRON","id":"lll:1.1:11"},{"kind":"speech","text":"Ay, that is study's godlike recompense.","sourceLine":"1.1.58","speaker":"FERDINAND","id":"lll:1.1:12"},{"kind":"speech","text":"Come on, then; I will swear to study so,\nTo know the thing I am forbid to know:\nAs thus,--to study where I well may dine,\nWhen I to feast expressly am forbid;\nOr study where to meet some mistress fine,\nWhen mistresses from common sense are hid;\nOr, having sworn too hard a keeping oath,\nStudy to break it and not break my troth.\nIf study's gain be thus and this be so,\nStudy knows that which yet it doth not know:\nSwear me to this, and I will ne'er say no.","sourceLine":"1.1.59","speaker":"BIRON","id":"lll:1.1:13"},{"kind":"speech","text":"These be the stops that hinder study quite\nAnd train our intellects to vain delight.","sourceLine":"1.1.70","speaker":"FERDINAND","id":"lll:1.1:14"},{"kind":"speech","text":"Why, all delights are vain; but that most vain,\nWhich with pain purchased doth inherit pain:\nAs, painfully to pore upon a book\nTo seek the light of truth; while truth the while\nDoth falsely blind the eyesight of his look:\nLight seeking light doth light of light beguile:\nSo, ere you find where light in darkness lies,\nYour light grows dark by losing of your eyes.\nStudy me how to please the eye indeed\nBy fixing it upon a fairer eye,\nWho dazzling so, that eye shall be his heed\nAnd give him light that it was blinded by.\nStudy is like the heaven's glorious sun\nThat will not be deep-search'd with saucy looks:\nSmall have continual plodders ever won\nSave base authority from others' books\nThese earthly godfathers of heaven's lights\nThat give a name to every fixed star\nHave no more profit of their shining nights\nThan those that walk and wot not what they are.\nToo much to know is to know nought but fame;\nAnd every godfather can give a name.","sourceLine":"1.1.72","speaker":"BIRON","id":"lll:1.1:15"},{"kind":"speech","text":"How well he's read, to reason against reading!","sourceLine":"1.1.94","speaker":"FERDINAND","id":"lll:1.1:16"},{"kind":"speech","text":"Proceeded well, to stop all good proceeding!","sourceLine":"1.1.95","speaker":"DUMAIN","id":"lll:1.1:17"},{"kind":"speech","text":"He weeds the corn and still lets grow the weeding.","sourceLine":"1.1.96","speaker":"LONGAVILLE","id":"lll:1.1:18"},{"kind":"speech","text":"The spring is near when green geese are a-breeding.","sourceLine":"1.1.97","speaker":"BIRON","id":"lll:1.1:19"},{"kind":"speech","text":"How follows that?","sourceLine":"1.1.98","speaker":"DUMAIN","id":"lll:1.1:20"},{"kind":"speech","text":"Fit in his place and time.","sourceLine":"1.1.99","speaker":"BIRON","id":"lll:1.1:21"},{"kind":"speech","text":"In reason nothing.","sourceLine":"1.1.100","speaker":"DUMAIN","id":"lll:1.1:22"},{"kind":"speech","text":"Something then in rhyme.","sourceLine":"1.1.101","speaker":"BIRON","id":"lll:1.1:23"},{"kind":"speech","text":"Biron is like an envious sneaping frost,\nThat bites the first-born infants of the spring.","sourceLine":"1.1.102","speaker":"FERDINAND","id":"lll:1.1:24"},{"kind":"speech","text":"Well, say I am; why should proud summer boast\nBefore the birds have any cause to sing?\nWhy should I joy in any abortive birth?\nAt Christmas I no more desire a rose\nThan wish a snow in May's new-fangled mirth;\nBut like of each thing that in season grows.\nSo you, to study now it is too late,\nClimb o'er the house to unlock the little gate.","sourceLine":"1.1.104","speaker":"BIRON","id":"lll:1.1:25"},{"kind":"speech","text":"Well, sit you out: go home, Biron: adieu.","sourceLine":"1.1.112","speaker":"FERDINAND","id":"lll:1.1:26"},{"kind":"speech","text":"No, my good lord; I have sworn to stay with you:\nAnd though I have for barbarism spoke more\nThan for that angel knowledge you can say,\nYet confident I'll keep what I have swore\nAnd bide the penance of each three years' day.\nGive me the paper; let me read the same;\nAnd to the strict'st decrees I'll write my name.","sourceLine":"1.1.113","speaker":"BIRON","id":"lll:1.1:27"},{"kind":"speech","text":"How well this yielding rescues thee from shame!","sourceLine":"1.1.120","speaker":"FERDINAND","id":"lll:1.1:28"},{"kind":"speech","text":"[Reads] 'Item, That no woman shall come within a\nmile of my court:' Hath this been proclaimed?","sourceLine":"1.1.121","speaker":"BIRON","id":"lll:1.1:29"},{"kind":"speech","text":"Four days ago.","sourceLine":"1.1.123","speaker":"LONGAVILLE","id":"lll:1.1:30"},{"kind":"speech","text":"Let's see the penalty.","sourceLine":"1.1.124","speaker":"BIRON","id":"lll:1.1:31"},{"kind":"stage","text":"Reads","id":"lll:1.1:32"},{"kind":"speech","text":"'On pain of losing her tongue.' Who devised this penalty?","sourceLine":"1.1.125","speaker":"BIRON","id":"lll:1.1:33"},{"kind":"speech","text":"Marry, that did I.","sourceLine":"1.1.126","speaker":"LONGAVILLE","id":"lll:1.1:34"},{"kind":"speech","text":"Sweet lord, and why?","sourceLine":"1.1.127","speaker":"BIRON","id":"lll:1.1:35"},{"kind":"speech","text":"To fright them hence with that dread penalty.","sourceLine":"1.1.128","speaker":"LONGAVILLE","id":"lll:1.1:36"},{"kind":"speech","text":"A dangerous law against gentility!","sourceLine":"1.1.129","speaker":"BIRON","id":"lll:1.1:37"},{"kind":"stage","text":"Reads","id":"lll:1.1:38"},{"kind":"speech","text":"'Item, If any man be seen to talk with a woman\nwithin the term of three years, he shall endure such\npublic shame as the rest of the court can possibly devise.'\nThis article, my liege, yourself must break;\nFor well you know here comes in embassy\nThe French king's daughter with yourself to speak--\nA maid of grace and complete majesty--\nAbout surrender up of Aquitaine\nTo her decrepit, sick and bedrid father:\nTherefore this article is made in vain,\nOr vainly comes the admired princess hither.","sourceLine":"1.1.130","speaker":"BIRON","id":"lll:1.1:39"},{"kind":"speech","text":"What say you, lords? Why, this was quite forgot.","sourceLine":"1.1.141","speaker":"FERDINAND","id":"lll:1.1:40"},{"kind":"speech","text":"So study evermore is overshot:\nWhile it doth study to have what it would\nIt doth forget to do the thing it should,\nAnd when it hath the thing it hunteth most,\n'Tis won as towns with fire, so won, so lost.","sourceLine":"1.1.142","speaker":"BIRON","id":"lll:1.1:41"},{"kind":"speech","text":"We must of force dispense with this decree;\nShe must lie here on mere necessity.","sourceLine":"1.1.147","speaker":"FERDINAND","id":"lll:1.1:42"},{"kind":"speech","text":"Necessity will make us all forsworn\nThree thousand times within this three years' space;\nFor every man with his affects is born,\nNot by might master'd but by special grace:\nIf I break faith, this word shall speak for me;\nI am forsworn on 'mere necessity.'\nSo to the laws at large I write my name:","sourceLine":"1.1.149","speaker":"BIRON","id":"lll:1.1:43"},{"kind":"stage","text":"Subscribes","id":"lll:1.1:44"},{"kind":"speech","text":"And he that breaks them in the least degree\nStands in attainder of eternal shame:\nSuggestions are to other as to me;\nBut I believe, although I seem so loath,\nI am the last that will last keep his oath.\nBut is there no quick recreation granted?","sourceLine":"1.1.156","speaker":"BIRON","id":"lll:1.1:45"},{"kind":"speech","text":"Ay, that there is. Our court, you know, is haunted\nWith a refined traveller of Spain;\nA man in all the world's new fashion planted,\nThat hath a mint of phrases in his brain;\nOne whom the music of his own vain tongue\nDoth ravish like enchanting harmony;\nA man of complements, whom right and wrong\nHave chose as umpire of their mutiny:\nThis child of fancy, that Armado hight,\nFor interim to our studies shall relate\nIn high-born words the worth of many a knight\nFrom tawny Spain lost in the world's debate.\nHow you delight, my lords, I know not, I;\nBut, I protest, I love to hear him lie\nAnd I will use him for my minstrelsy.","sourceLine":"1.1.162","speaker":"FERDINAND","id":"lll:1.1:46"},{"kind":"speech","text":"Armado is a most illustrious wight,\nA man of fire-new words, fashion's own knight.","sourceLine":"1.1.177","speaker":"BIRON","id":"lll:1.1:47"},{"kind":"speech","text":"Costard the swain and he shall be our sport;\nAnd so to study, three years is but short.","sourceLine":"1.1.179","speaker":"LONGAVILLE","id":"lll:1.1:48"},{"kind":"stage","text":"Enter DULL with a letter, and COSTARD","id":"lll:1.1:49"},{"kind":"speech","text":"Which is the duke's own person?","sourceLine":"1.1.181","speaker":"DULL","id":"lll:1.1:50"},{"kind":"speech","text":"This, fellow: what wouldst?","sourceLine":"1.1.182","speaker":"BIRON","id":"lll:1.1:51"},{"kind":"speech","text":"I myself reprehend his own person, for I am his\ngrace's tharborough: but I would see his own person\nin flesh and blood.","sourceLine":"1.1.183","speaker":"DULL","id":"lll:1.1:52"},{"kind":"speech","text":"This is he.","sourceLine":"1.1.186","speaker":"BIRON","id":"lll:1.1:53"},{"kind":"speech","text":"Signior Arme--Arme--commends you. There's villany\nabroad: this letter will tell you more.","sourceLine":"1.1.187","speaker":"DULL","id":"lll:1.1:54"},{"kind":"speech","text":"Sir, the contempts thereof are as touching me.","sourceLine":"1.1.189","speaker":"COSTARD","id":"lll:1.1:55"},{"kind":"speech","text":"A letter from the magnificent Armado.","sourceLine":"1.1.190","speaker":"FERDINAND","id":"lll:1.1:56"},{"kind":"speech","text":"How low soever the matter, I hope in God for high words.","sourceLine":"1.1.191","speaker":"BIRON","id":"lll:1.1:57"},{"kind":"speech","text":"A high hope for a low heaven: God grant us patience!","sourceLine":"1.1.192","speaker":"LONGAVILLE","id":"lll:1.1:58"},{"kind":"speech","text":"To hear? or forbear laughing?","sourceLine":"1.1.193","speaker":"BIRON","id":"lll:1.1:59"},{"kind":"speech","text":"To hear meekly, sir, and to laugh moderately; or to\nforbear both.","sourceLine":"1.1.194","speaker":"LONGAVILLE","id":"lll:1.1:60"},{"kind":"speech","text":"Well, sir, be it as the style shall give us cause to\nclimb in the merriness.","sourceLine":"1.1.196","speaker":"BIRON","id":"lll:1.1:61"},{"kind":"speech","text":"The matter is to me, sir, as concerning Jaquenetta.\nThe manner of it is, I was taken with the manner.","sourceLine":"1.1.198","speaker":"COSTARD","id":"lll:1.1:62"},{"kind":"speech","text":"In what manner?","sourceLine":"1.1.200","speaker":"BIRON","id":"lll:1.1:63"},{"kind":"speech","text":"In manner and form following, sir; all those three:\nI was seen with her in the manor-house, sitting with\nher upon the form, and taken following her into the\npark; which, put together, is in manner and form\nfollowing. Now, sir, for the manner,--it is the\nmanner of a man to speak to a woman: for the form,--\nin some form.","sourceLine":"1.1.201","speaker":"COSTARD","id":"lll:1.1:64"},{"kind":"speech","text":"For the following, sir?","sourceLine":"1.1.208","speaker":"BIRON","id":"lll:1.1:65"},{"kind":"speech","text":"As it shall follow in my correction: and God defend\nthe right!","sourceLine":"1.1.209","speaker":"COSTARD","id":"lll:1.1:66"},{"kind":"speech","text":"Will you hear this letter with attention?","sourceLine":"1.1.211","speaker":"FERDINAND","id":"lll:1.1:67"},{"kind":"speech","text":"As we would hear an oracle.","sourceLine":"1.1.212","speaker":"BIRON","id":"lll:1.1:68"},{"kind":"speech","text":"Such is the simplicity of man to hearken after the flesh.","sourceLine":"1.1.213","speaker":"COSTARD","id":"lll:1.1:69"},{"kind":"speech","text":"[Reads] 'Great deputy, the welkin's vicegerent and\nsole dominator of Navarre, my soul's earth's god,\nand body's fostering patron.'","sourceLine":"1.1.214","speaker":"FERDINAND","id":"lll:1.1:70"},{"kind":"speech","text":"Not a word of Costard yet.","sourceLine":"1.1.217","speaker":"COSTARD","id":"lll:1.1:71"},{"kind":"speech","text":"[Reads] 'So it is,'--","sourceLine":"1.1.218","speaker":"FERDINAND","id":"lll:1.1:72"},{"kind":"speech","text":"It may be so: but if he say it is so, he is, in\ntelling true, but so.","sourceLine":"1.1.219","speaker":"COSTARD","id":"lll:1.1:73"},{"kind":"speech","text":"Peace!","sourceLine":"1.1.221","speaker":"FERDINAND","id":"lll:1.1:74"},{"kind":"speech","text":"Be to me and every man that dares not fight!","sourceLine":"1.1.222","speaker":"COSTARD","id":"lll:1.1:75"},{"kind":"speech","text":"No words!","sourceLine":"1.1.223","speaker":"FERDINAND","id":"lll:1.1:76"},{"kind":"speech","text":"Of other men's secrets, I beseech you.","sourceLine":"1.1.224","speaker":"COSTARD","id":"lll:1.1:77"},{"kind":"speech","text":"[Reads] 'So it is, besieged with sable-coloured\nmelancholy, I did commend the black-oppressing humour\nto the most wholesome physic of thy health-giving\nair; and, as I am a gentleman, betook myself to\nwalk. The time when. About the sixth hour; when\nbeasts most graze, birds best peck, and men sit down\nto that nourishment which is called supper: so much\nfor the time when. Now for the ground which; which,\nI mean, I walked upon: it is y-cleped thy park. Then\nfor the place where; where, I mean, I did encounter\nthat obscene and preposterous event, that draweth\nfrom my snow-white pen the ebon-coloured ink, which\nhere thou viewest, beholdest, surveyest, or seest;\nbut to the place where; it standeth north-north-east\nand by east from the west corner of thy curious-\nknotted garden: there did I see that low-spirited\nswain, that base minnow of thy mirth,'--","sourceLine":"1.1.225","speaker":"FERDINAND","id":"lll:1.1:78"},{"kind":"speech","text":"Me?","sourceLine":"1.1.242","speaker":"COSTARD","id":"lll:1.1:79"},{"kind":"speech","text":"[Reads] 'that unlettered small-knowing soul,'--","sourceLine":"1.1.243","speaker":"FERDINAND","id":"lll:1.1:80"},{"kind":"speech","text":"Me?","sourceLine":"1.1.244","speaker":"COSTARD","id":"lll:1.1:81"},{"kind":"speech","text":"[Reads] 'that shallow vassal,'--","sourceLine":"1.1.245","speaker":"FERDINAND","id":"lll:1.1:82"},{"kind":"speech","text":"Still me?","sourceLine":"1.1.246","speaker":"COSTARD","id":"lll:1.1:83"},{"kind":"speech","text":"[Reads] 'which, as I remember, hight Costard,'--","sourceLine":"1.1.247","speaker":"FERDINAND","id":"lll:1.1:84"},{"kind":"speech","text":"O, me!","sourceLine":"1.1.248","speaker":"COSTARD","id":"lll:1.1:85"},{"kind":"speech","text":"[Reads] 'sorted and consorted, contrary to thy\nestablished proclaimed edict and continent canon,\nwhich with,--O, with--but with this I passion to say\nwherewith,--","sourceLine":"1.1.249","speaker":"FERDINAND","id":"lll:1.1:86"},{"kind":"speech","text":"With a wench.","sourceLine":"1.1.253","speaker":"COSTARD","id":"lll:1.1:87"},{"kind":"speech","text":"[Reads] 'with a child of our grandmother Eve, a\nfemale; or, for thy more sweet understanding, a\nwoman. Him I, as my ever-esteemed duty pricks me on,\nhave sent to thee, to receive the meed of\npunishment, by thy sweet grace's officer, Anthony\nDull; a man of good repute, carriage, bearing, and\nestimation.'","sourceLine":"1.1.254","speaker":"FERDINAND","id":"lll:1.1:88"},{"kind":"speech","text":"'Me, an't shall please you; I am Anthony Dull.","sourceLine":"1.1.261","speaker":"DULL","id":"lll:1.1:89"},{"kind":"speech","text":"[Reads] 'For Jaquenetta,--so is the weaker vessel\ncalled which I apprehended with the aforesaid\nswain,--I keep her as a vessel of the law's fury;\nand shall, at the least of thy sweet notice, bring\nher to trial. Thine, in all compliments of devoted\nand heart-burning heat of duty.\nDON ADRIANO DE ARMADO.'","sourceLine":"1.1.262","speaker":"FERDINAND","id":"lll:1.1:90"},{"kind":"speech","text":"This is not so well as I looked for, but the best\nthat ever I heard.","sourceLine":"1.1.269","speaker":"BIRON","id":"lll:1.1:91"},{"kind":"speech","text":"Ay, the best for the worst. But, sirrah, what say\nyou to this?","sourceLine":"1.1.271","speaker":"FERDINAND","id":"lll:1.1:92"},{"kind":"speech","text":"Sir, I confess the wench.","sourceLine":"1.1.273","speaker":"COSTARD","id":"lll:1.1:93"},{"kind":"speech","text":"Did you hear the proclamation?","sourceLine":"1.1.274","speaker":"FERDINAND","id":"lll:1.1:94"},{"kind":"speech","text":"I do confess much of the hearing it but little of\nthe marking of it.","sourceLine":"1.1.275","speaker":"COSTARD","id":"lll:1.1:95"},{"kind":"speech","text":"It was proclaimed a year's imprisonment, to be taken\nwith a wench.","sourceLine":"1.1.277","speaker":"FERDINAND","id":"lll:1.1:96"},{"kind":"speech","text":"I was taken with none, sir: I was taken with a damsel.","sourceLine":"1.1.279","speaker":"COSTARD","id":"lll:1.1:97"},{"kind":"speech","text":"Well, it was proclaimed 'damsel.'","sourceLine":"1.1.280","speaker":"FERDINAND","id":"lll:1.1:98"},{"kind":"speech","text":"This was no damsel, neither, sir; she was a virgin.","sourceLine":"1.1.281","speaker":"COSTARD","id":"lll:1.1:99"},{"kind":"speech","text":"It is so varied, too; for it was proclaimed 'virgin.'","sourceLine":"1.1.282","speaker":"FERDINAND","id":"lll:1.1:100"},{"kind":"speech","text":"If it were, I deny her virginity: I was taken with a maid.","sourceLine":"1.1.283","speaker":"COSTARD","id":"lll:1.1:101"},{"kind":"speech","text":"This maid will not serve your turn, sir.","sourceLine":"1.1.284","speaker":"FERDINAND","id":"lll:1.1:102"},{"kind":"speech","text":"This maid will serve my turn, sir.","sourceLine":"1.1.285","speaker":"COSTARD","id":"lll:1.1:103"},{"kind":"speech","text":"Sir, I will pronounce your sentence: you shall fast\na week with bran and water.","sourceLine":"1.1.286","speaker":"FERDINAND","id":"lll:1.1:104"},{"kind":"speech","text":"I had rather pray a month with mutton and porridge.","sourceLine":"1.1.288","speaker":"COSTARD","id":"lll:1.1:105"},{"kind":"speech","text":"And Don Armado shall be your keeper.\nMy Lord Biron, see him deliver'd o'er:\nAnd go we, lords, to put in practise that\nWhich each to other hath so strongly sworn.","sourceLine":"1.1.289","speaker":"FERDINAND","id":"lll:1.1:106"},{"kind":"stage","text":"Exeunt FERDINAND, LONGAVILLE, and DUMAIN","id":"lll:1.1:107"},{"kind":"speech","text":"I'll lay my head to any good man's hat,\nThese oaths and laws will prove an idle scorn.\nSirrah, come on.","sourceLine":"1.1.293","speaker":"BIRON","id":"lll:1.1:108"},{"kind":"speech","text":"I suffer for the truth, sir; for true it is, I was\ntaken with Jaquenetta, and Jaquenetta is a true\ngirl; and therefore welcome the sour cup of\nprosperity! Affliction may one day smile again; and\ntill then, sit thee down, sorrow!","sourceLine":"1.1.296","speaker":"COSTARD","id":"lll:1.1:109"},{"kind":"stage","text":"Exeunt","id":"lll:1.1:110"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"1.1.301","speaker":"COSTARD","id":"lll:1.1:111"}],"scene":1},{"id":"1.2","label":"Act 1 · SCENE II. The same.","act":1,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter DON ADRIANO DE ARMADO and MOTH","id":"lll:1.2:1"},{"kind":"speech","text":"Boy, what sign is it when a man of great spirit\ngrows melancholy?","sourceLine":"1.2.2","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.1","rawPrefix":"DON","followingSpeechAnchor":"speech1","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":738,"originalHtml":"<A NAME=1.2.1>DON</A><br>\n</blockquote>\n\n<A NAME=speech1><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:2"},{"kind":"speech","text":"A great sign, sir, that he will look sad.","sourceLine":"1.2.4","speaker":"MOTH","id":"lll:1.2:3"},{"kind":"speech","text":"Why, sadness is one and the self-same thing, dear imp.","sourceLine":"1.2.6","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.5","rawPrefix":"DON","followingSpeechAnchor":"speech3","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":750,"originalHtml":"<A NAME=1.2.5>DON</A><br>\n</blockquote>\n\n<A NAME=speech3><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:4"},{"kind":"speech","text":"No, no; O Lord, sir, no.","sourceLine":"1.2.7","speaker":"MOTH","id":"lll:1.2:5"},{"kind":"speech","text":"How canst thou part sadness and melancholy, my\ntender juvenal?","sourceLine":"1.2.9","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.8","rawPrefix":"DON","followingSpeechAnchor":"speech5","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":761,"originalHtml":"<A NAME=1.2.8>DON</A><br>\n</blockquote>\n\n<A NAME=speech5><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:6"},{"kind":"speech","text":"By a familiar demonstration of the working, my tough senior.","sourceLine":"1.2.11","speaker":"MOTH","id":"lll:1.2:7"},{"kind":"speech","text":"Why tough senior? why tough senior?","sourceLine":"1.2.13","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.12","rawPrefix":"DON","followingSpeechAnchor":"speech7","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":773,"originalHtml":"<A NAME=1.2.12>DON</A><br>\n</blockquote>\n\n<A NAME=speech7><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:8"},{"kind":"speech","text":"Why tender juvenal? why tender juvenal?","sourceLine":"1.2.14","speaker":"MOTH","id":"lll:1.2:9"},{"kind":"speech","text":"I spoke it, tender juvenal, as a congruent epitheton\nappertaining to thy young days, which we may\nnominate tender.","sourceLine":"1.2.16","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.15","rawPrefix":"DON","followingSpeechAnchor":"speech9","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":784,"originalHtml":"<A NAME=1.2.15>DON</A><br>\n</blockquote>\n\n<A NAME=speech9><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:10"},{"kind":"speech","text":"And I, tough senior, as an appertinent title to your\nold time, which we may name tough.\nDON ADRIANO DE","sourceLine":"1.2.19","speaker":"MOTH","id":"lll:1.2:11"},{"kind":"speech","text":"Pretty and apt.","sourceLine":"1.2.22","speaker":"ARMADO","id":"lll:1.2:12"},{"kind":"speech","text":"How mean you, sir? I pretty, and my saying apt? or\nI apt, and my saying pretty?","sourceLine":"1.2.23","speaker":"MOTH","id":"lll:1.2:13"},{"kind":"speech","text":"Thou pretty, because little.","sourceLine":"1.2.26","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.25","rawPrefix":"DON","followingSpeechAnchor":"speech13","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":810,"originalHtml":"<A NAME=1.2.25>DON</A><br>\n</blockquote>\n\n<A NAME=speech13><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:14"},{"kind":"speech","text":"Little pretty, because little. Wherefore apt?","sourceLine":"1.2.27","speaker":"MOTH","id":"lll:1.2:15"},{"kind":"speech","text":"And therefore apt, because quick.","sourceLine":"1.2.29","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.28","rawPrefix":"DON","followingSpeechAnchor":"speech15","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":821,"originalHtml":"<A NAME=1.2.28>DON</A><br>\n</blockquote>\n\n<A NAME=speech15><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:16"},{"kind":"speech","text":"Speak you this in my praise, master?","sourceLine":"1.2.30","speaker":"MOTH","id":"lll:1.2:17"},{"kind":"speech","text":"In thy condign praise.","sourceLine":"1.2.32","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.31","rawPrefix":"DON","followingSpeechAnchor":"speech17","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":832,"originalHtml":"<A NAME=1.2.31>DON</A><br>\n</blockquote>\n\n<A NAME=speech17><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:18"},{"kind":"speech","text":"I will praise an eel with the same praise.","sourceLine":"1.2.33","speaker":"MOTH","id":"lll:1.2:19"},{"kind":"speech","text":"What, that an eel is ingenious?","sourceLine":"1.2.35","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.34","rawPrefix":"DON","followingSpeechAnchor":"speech19","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":843,"originalHtml":"<A NAME=1.2.34>DON</A><br>\n</blockquote>\n\n<A NAME=speech19><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:20"},{"kind":"speech","text":"That an eel is quick.","sourceLine":"1.2.36","speaker":"MOTH","id":"lll:1.2:21"},{"kind":"speech","text":"I do say thou art quick in answers: thou heatest my blood.","sourceLine":"1.2.38","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.37","rawPrefix":"DON","followingSpeechAnchor":"speech21","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":854,"originalHtml":"<A NAME=1.2.37>DON</A><br>\n</blockquote>\n\n<A NAME=speech21><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:22"},{"kind":"speech","text":"I am answered, sir.","sourceLine":"1.2.39","speaker":"MOTH","id":"lll:1.2:23"},{"kind":"speech","text":"I love not to be crossed.","sourceLine":"1.2.41","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.40","rawPrefix":"DON","followingSpeechAnchor":"speech23","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":865,"originalHtml":"<A NAME=1.2.40>DON</A><br>\n</blockquote>\n\n<A NAME=speech23><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:24"},{"kind":"speech","text":"[Aside] He speaks the mere contrary; crosses love not him.","sourceLine":"1.2.42","speaker":"MOTH","id":"lll:1.2:25"},{"kind":"speech","text":"I have promised to study three years with the duke.","sourceLine":"1.2.44","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.43","rawPrefix":"DON","followingSpeechAnchor":"speech25","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":876,"originalHtml":"<A NAME=1.2.43>DON</A><br>\n</blockquote>\n\n<A NAME=speech25><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:26"},{"kind":"speech","text":"You may do it in an hour, sir.","sourceLine":"1.2.45","speaker":"MOTH","id":"lll:1.2:27"},{"kind":"speech","text":"Impossible.","sourceLine":"1.2.47","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.46","rawPrefix":"DON","followingSpeechAnchor":"speech27","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":887,"originalHtml":"<A NAME=1.2.46>DON</A><br>\n</blockquote>\n\n<A NAME=speech27><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:28"},{"kind":"speech","text":"How many is one thrice told?","sourceLine":"1.2.48","speaker":"MOTH","id":"lll:1.2:29"},{"kind":"speech","text":"I am ill at reckoning; it fitteth the spirit of a tapster.","sourceLine":"1.2.50","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.49","rawPrefix":"DON","followingSpeechAnchor":"speech29","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":898,"originalHtml":"<A NAME=1.2.49>DON</A><br>\n</blockquote>\n\n<A NAME=speech29><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:30"},{"kind":"speech","text":"You are a gentleman and a gamester, sir.","sourceLine":"1.2.51","speaker":"MOTH","id":"lll:1.2:31"},{"kind":"speech","text":"I confess both: they are both the varnish of a\ncomplete man.","sourceLine":"1.2.53","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.52","rawPrefix":"DON","followingSpeechAnchor":"speech31","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":909,"originalHtml":"<A NAME=1.2.52>DON</A><br>\n</blockquote>\n\n<A NAME=speech31><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:32"},{"kind":"speech","text":"Then, I am sure, you know how much the gross sum of\ndeuce-ace amounts to.","sourceLine":"1.2.55","speaker":"MOTH","id":"lll:1.2:33"},{"kind":"speech","text":"It doth amount to one more than two.","sourceLine":"1.2.58","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.57","rawPrefix":"DON","followingSpeechAnchor":"speech33","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":922,"originalHtml":"<A NAME=1.2.57>DON</A><br>\n</blockquote>\n\n<A NAME=speech33><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:34"},{"kind":"speech","text":"Which the base vulgar do call three.","sourceLine":"1.2.59","speaker":"MOTH","id":"lll:1.2:35"},{"kind":"speech","text":"True.","sourceLine":"1.2.61","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.60","rawPrefix":"DON","followingSpeechAnchor":"speech35","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":933,"originalHtml":"<A NAME=1.2.60>DON</A><br>\n</blockquote>\n\n<A NAME=speech35><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:36"},{"kind":"speech","text":"Why, sir, is this such a piece of study? Now here\nis three studied, ere ye'll thrice wink: and how\neasy it is to put 'years' to the word 'three,' and\nstudy three years in two words, the dancing horse\nwill tell you.","sourceLine":"1.2.62","speaker":"MOTH","id":"lll:1.2:37"},{"kind":"speech","text":"A most fine figure!","sourceLine":"1.2.68","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.67","rawPrefix":"DON","followingSpeechAnchor":"speech37","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":948,"originalHtml":"<A NAME=1.2.67>DON</A><br>\n</blockquote>\n\n<A NAME=speech37><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:38"},{"kind":"speech","text":"To prove you a cipher.","sourceLine":"1.2.69","speaker":"MOTH","id":"lll:1.2:39"},{"kind":"speech","text":"I will hereupon confess I am in love: and as it is\nbase for a soldier to love, so am I in love with a\nbase wench. If drawing my sword against the humour\nof affection would deliver me from the reprobate\nthought of it, I would take Desire prisoner, and\nransom him to any French courtier for a new-devised\ncourtesy. I think scorn to sigh: methinks I should\noutswear Cupid. Comfort, me, boy: what great men\nhave been in love?","sourceLine":"1.2.71","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.70","rawPrefix":"DON","followingSpeechAnchor":"speech39","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":959,"originalHtml":"<A NAME=1.2.70>DON</A><br>\n</blockquote>\n\n<A NAME=speech39><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:40"},{"kind":"speech","text":"Hercules, master.","sourceLine":"1.2.80","speaker":"MOTH","id":"lll:1.2:41"},{"kind":"speech","text":"Most sweet Hercules! More authority, dear boy, name\nmore; and, sweet my child, let them be men of good\nrepute and carriage.","sourceLine":"1.2.82","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.81","rawPrefix":"DON","followingSpeechAnchor":"speech41","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":978,"originalHtml":"<A NAME=1.2.81>DON</A><br>\n</blockquote>\n\n<A NAME=speech41><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:42"},{"kind":"speech","text":"Samson, master: he was a man of good carriage, great\ncarriage, for he carried the town-gates on his back\nlike a porter: and he was in love.","sourceLine":"1.2.85","speaker":"MOTH","id":"lll:1.2:43"},{"kind":"speech","text":"O well-knit Samson! strong-jointed Samson! I do\nexcel thee in my rapier as much as thou didst me in\ncarrying gates. I am in love too. Who was Samson's\nlove, my dear Moth?","sourceLine":"1.2.89","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.88","rawPrefix":"DON","followingSpeechAnchor":"speech43","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":993,"originalHtml":"<A NAME=1.2.88>DON</A><br>\n</blockquote>\n\n<A NAME=speech43><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:44"},{"kind":"speech","text":"A woman, master.","sourceLine":"1.2.93","speaker":"MOTH","id":"lll:1.2:45"},{"kind":"speech","text":"Of what complexion?","sourceLine":"1.2.95","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.94","rawPrefix":"DON","followingSpeechAnchor":"speech45","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1007,"originalHtml":"<A NAME=1.2.94>DON</A><br>\n</blockquote>\n\n<A NAME=speech45><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:46"},{"kind":"speech","text":"Of all the four, or the three, or the two, or one of the four.","sourceLine":"1.2.96","speaker":"MOTH","id":"lll:1.2:47"},{"kind":"speech","text":"Tell me precisely of what complexion.","sourceLine":"1.2.98","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.97","rawPrefix":"DON","followingSpeechAnchor":"speech47","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1018,"originalHtml":"<A NAME=1.2.97>DON</A><br>\n</blockquote>\n\n<A NAME=speech47><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:48"},{"kind":"speech","text":"Of the sea-water green, sir.","sourceLine":"1.2.99","speaker":"MOTH","id":"lll:1.2:49"},{"kind":"speech","text":"Is that one of the four complexions?","sourceLine":"1.2.101","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.100","rawPrefix":"DON","followingSpeechAnchor":"speech49","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1029,"originalHtml":"<A NAME=1.2.100>DON</A><br>\n</blockquote>\n\n<A NAME=speech49><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:50"},{"kind":"speech","text":"As I have read, sir; and the best of them too.","sourceLine":"1.2.102","speaker":"MOTH","id":"lll:1.2:51"},{"kind":"speech","text":"Green indeed is the colour of lovers; but to have a\nlove of that colour, methinks Samson had small reason\nfor it. He surely affected her for her wit.","sourceLine":"1.2.104","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.103","rawPrefix":"DON","followingSpeechAnchor":"speech51","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1040,"originalHtml":"<A NAME=1.2.103>DON</A><br>\n</blockquote>\n\n<A NAME=speech51><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:52"},{"kind":"speech","text":"It was so, sir; for she had a green wit.","sourceLine":"1.2.107","speaker":"MOTH","id":"lll:1.2:53"},{"kind":"speech","text":"My love is most immaculate white and red.","sourceLine":"1.2.109","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.108","rawPrefix":"DON","followingSpeechAnchor":"speech53","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1053,"originalHtml":"<A NAME=1.2.108>DON</A><br>\n</blockquote>\n\n<A NAME=speech53><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:54"},{"kind":"speech","text":"Most maculate thoughts, master, are masked under\nsuch colours.","sourceLine":"1.2.110","speaker":"MOTH","id":"lll:1.2:55"},{"kind":"speech","text":"Define, define, well-educated infant.","sourceLine":"1.2.113","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.112","rawPrefix":"DON","followingSpeechAnchor":"speech55","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1065,"originalHtml":"<A NAME=1.2.112>DON</A><br>\n</blockquote>\n\n<A NAME=speech55><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:56"},{"kind":"speech","text":"My father's wit and my mother's tongue, assist me!","sourceLine":"1.2.114","speaker":"MOTH","id":"lll:1.2:57"},{"kind":"speech","text":"Sweet invocation of a child; most pretty and\npathetical!","sourceLine":"1.2.116","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.115","rawPrefix":"DON","followingSpeechAnchor":"speech57","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1076,"originalHtml":"<A NAME=1.2.115>DON</A><br>\n</blockquote>\n\n<A NAME=speech57><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:58"},{"kind":"speech","text":"If she be made of white and red,\nHer faults will ne'er be known,\nFor blushing cheeks by faults are bred\nAnd fears by pale white shown:\nThen if she fear, or be to blame,\nBy this you shall not know,\nFor still her cheeks possess the same\nWhich native she doth owe.\nA dangerous rhyme, master, against the reason of\nwhite and red.","sourceLine":"1.2.118","speaker":"MOTH","id":"lll:1.2:59"},{"kind":"speech","text":"Is there not a ballad, boy, of the King and the Beggar?","sourceLine":"1.2.129","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.128","rawPrefix":"DON","followingSpeechAnchor":"speech59","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1097,"originalHtml":"<A NAME=1.2.128>DON</A><br>\n</blockquote>\n\n<A NAME=speech59><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:60"},{"kind":"speech","text":"The world was very guilty of such a ballad some\nthree ages since: but I think now 'tis not to be\nfound; or, if it were, it would neither serve for\nthe writing nor the tune.","sourceLine":"1.2.130","speaker":"MOTH","id":"lll:1.2:61"},{"kind":"speech","text":"I will have that subject newly writ o'er, that I may\nexample my digression by some mighty precedent.\nBoy, I do love that country girl that I took in the\npark with the rational hind Costard: she deserves well.","sourceLine":"1.2.135","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.134","rawPrefix":"DON","followingSpeechAnchor":"speech61","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1111,"originalHtml":"<A NAME=1.2.134>DON</A><br>\n</blockquote>\n\n<A NAME=speech61><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:62"},{"kind":"speech","text":"[Aside] To be whipped; and yet a better love than\nmy master.","sourceLine":"1.2.139","speaker":"MOTH","id":"lll:1.2:63"},{"kind":"speech","text":"Sing, boy; my spirit grows heavy in love.","sourceLine":"1.2.142","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.141","rawPrefix":"DON","followingSpeechAnchor":"speech63","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1126,"originalHtml":"<A NAME=1.2.141>DON</A><br>\n</blockquote>\n\n<A NAME=speech63><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:64"},{"kind":"speech","text":"And that's great marvel, loving a light wench.","sourceLine":"1.2.143","speaker":"MOTH","id":"lll:1.2:65"},{"kind":"speech","text":"I say, sing.","sourceLine":"1.2.145","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.144","rawPrefix":"DON","followingSpeechAnchor":"speech65","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1137,"originalHtml":"<A NAME=1.2.144>DON</A><br>\n</blockquote>\n\n<A NAME=speech65><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:66"},{"kind":"speech","text":"Forbear till this company be past.","sourceLine":"1.2.146","speaker":"MOTH","id":"lll:1.2:67"},{"kind":"stage","text":"Enter DULL, COSTARD, and JAQUENETTA","id":"lll:1.2:68"},{"kind":"speech","text":"Sir, the duke's pleasure is, that you keep Costard\nsafe: and you must suffer him to take no delight\nnor no penance; but a' must fast three days a week.\nFor this damsel, I must keep her at the park: she\nis allowed for the day-woman. Fare you well.","sourceLine":"1.2.147","speaker":"DULL","id":"lll:1.2:69"},{"kind":"speech","text":"I do betray myself with blushing. Maid!","sourceLine":"1.2.153","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.152","rawPrefix":"DON","followingSpeechAnchor":"speech68","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1158,"originalHtml":"<A NAME=1.2.152>DON</A><br>\n</blockquote>\n\n<A NAME=speech68><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:70"},{"kind":"speech","text":"Man?","sourceLine":"1.2.154","speaker":"JAQUENETTA","id":"lll:1.2:71"},{"kind":"speech","text":"I will visit thee at the lodge.","sourceLine":"1.2.156","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.155","rawPrefix":"DON","followingSpeechAnchor":"speech70","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1169,"originalHtml":"<A NAME=1.2.155>DON</A><br>\n</blockquote>\n\n<A NAME=speech70><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:72"},{"kind":"speech","text":"That's hereby.","sourceLine":"1.2.157","speaker":"JAQUENETTA","id":"lll:1.2:73"},{"kind":"speech","text":"I know where it is situate.","sourceLine":"1.2.159","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.158","rawPrefix":"DON","followingSpeechAnchor":"speech72","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1180,"originalHtml":"<A NAME=1.2.158>DON</A><br>\n</blockquote>\n\n<A NAME=speech72><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:74"},{"kind":"speech","text":"Lord, how wise you are!","sourceLine":"1.2.160","speaker":"JAQUENETTA","id":"lll:1.2:75"},{"kind":"speech","text":"I will tell thee wonders.","sourceLine":"1.2.162","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.161","rawPrefix":"DON","followingSpeechAnchor":"speech74","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1191,"originalHtml":"<A NAME=1.2.161>DON</A><br>\n</blockquote>\n\n<A NAME=speech74><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:76"},{"kind":"speech","text":"With that face?","sourceLine":"1.2.163","speaker":"JAQUENETTA","id":"lll:1.2:77"},{"kind":"speech","text":"I love thee.","sourceLine":"1.2.165","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.164","rawPrefix":"DON","followingSpeechAnchor":"speech76","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1202,"originalHtml":"<A NAME=1.2.164>DON</A><br>\n</blockquote>\n\n<A NAME=speech76><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:78"},{"kind":"speech","text":"So I heard you say.","sourceLine":"1.2.166","speaker":"JAQUENETTA","id":"lll:1.2:79"},{"kind":"speech","text":"And so, farewell.","sourceLine":"1.2.168","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.167","rawPrefix":"DON","followingSpeechAnchor":"speech78","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1213,"originalHtml":"<A NAME=1.2.167>DON</A><br>\n</blockquote>\n\n<A NAME=speech78><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:80"},{"kind":"speech","text":"Fair weather after you!","sourceLine":"1.2.169","speaker":"JAQUENETTA","id":"lll:1.2:81"},{"kind":"speech","text":"Come, Jaquenetta, away!","sourceLine":"1.2.170","speaker":"DULL","id":"lll:1.2:82"},{"kind":"stage","text":"Exeunt DULL and JAQUENETTA","id":"lll:1.2:83"},{"kind":"speech","text":"Villain, thou shalt fast for thy offences ere thou\nbe pardoned.","sourceLine":"1.2.172","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.171","rawPrefix":"DON","followingSpeechAnchor":"speech81","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1230,"originalHtml":"<A NAME=1.2.171>DON</A><br>\n</blockquote>\n\n<A NAME=speech81><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:84"},{"kind":"speech","text":"Well, sir, I hope, when I do it, I shall do it on a\nfull stomach.","sourceLine":"1.2.174","speaker":"COSTARD","id":"lll:1.2:85"},{"kind":"speech","text":"Thou shalt be heavily punished.","sourceLine":"1.2.177","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.176","rawPrefix":"DON","followingSpeechAnchor":"speech83","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1243,"originalHtml":"<A NAME=1.2.176>DON</A><br>\n</blockquote>\n\n<A NAME=speech83><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:86"},{"kind":"speech","text":"I am more bound to you than your fellows, for they\nare but lightly rewarded.","sourceLine":"1.2.178","speaker":"COSTARD","id":"lll:1.2:87"},{"kind":"speech","text":"Take away this villain; shut him up.","sourceLine":"1.2.181","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.180","rawPrefix":"DON","followingSpeechAnchor":"speech85","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1255,"originalHtml":"<A NAME=1.2.180>DON</A><br>\n</blockquote>\n\n<A NAME=speech85><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:88"},{"kind":"speech","text":"Come, you transgressing slave; away!","sourceLine":"1.2.182","speaker":"MOTH","id":"lll:1.2:89"},{"kind":"speech","text":"Let me not be pent up, sir: I will fast, being loose.","sourceLine":"1.2.183","speaker":"COSTARD","id":"lll:1.2:90"},{"kind":"speech","text":"No, sir; that were fast and loose: thou shalt to prison.","sourceLine":"1.2.184","speaker":"MOTH","id":"lll:1.2:91"},{"kind":"speech","text":"Well, if ever I do see the merry days of desolation\nthat I have seen, some shall see.","sourceLine":"1.2.185","speaker":"COSTARD","id":"lll:1.2:92"},{"kind":"speech","text":"What shall some see?","sourceLine":"1.2.187","speaker":"MOTH","id":"lll:1.2:93"},{"kind":"speech","text":"Nay, nothing, Master Moth, but what they look upon.\nIt is not for prisoners to be too silent in their\nwords; and therefore I will say nothing: I thank\nGod I have as little patience as another man; and\ntherefore I can be quiet.","sourceLine":"1.2.188","speaker":"COSTARD","id":"lll:1.2:94"},{"kind":"stage","text":"Exeunt MOTH and COSTARD","id":"lll:1.2:95"},{"kind":"speech","text":"I do affect the very ground, which is base, where\nher shoe, which is baser, guided by her foot, which\nis basest, doth tread. I shall be forsworn, which\nis a great argument of falsehood, if I love. And\nhow can that be true love which is falsely\nattempted? Love is a familiar; Love is a devil:\nthere is no evil angel but Love. Yet was Samson so\ntempted, and he had an excellent strength; yet was\nSolomon so seduced, and he had a very good wit.\nCupid's butt-shaft is too hard for Hercules' club;\nand therefore too much odds for a Spaniard's rapier.\nThe first and second cause will not serve my turn;\nthe passado he respects not, the duello he regards\nnot: his disgrace is to be called boy; but his\nglory is to subdue men. Adieu, valour! rust rapier!\nbe still, drum! for your manager is in love; yea,\nhe loveth. Assist me, some extemporal god of rhyme,\nfor I am sure I shall turn sonnet. Devise, wit;\nwrite, pen; for I am for whole volumes in folio.","sourceLine":"1.2.194","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"1.2.193","rawPrefix":"DON","followingSpeechAnchor":"speech92","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":1297,"originalHtml":"<A NAME=1.2.193>DON</A><br>\n</blockquote>\n\n<A NAME=speech92><b>ADRIANO DE ARMADO</b>"},"id":"lll:1.2:96"},{"kind":"stage","text":"Exit","id":"lll:1.2:97"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"1.2.213","speaker":"DON ADRIANO DE ARMADO","id":"lll:1.2:98"}],"scene":2},{"id":"2.1","label":"Act 2 · SCENE I. The same.","act":2,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter the PRINCESS of France, ROSALINE, MARIA, KATHARINE, BOYET, Lords, and other Attendants","id":"lll:2.1:1"},{"kind":"speech","text":"Now, madam, summon up your dearest spirits:\nConsider who the king your father sends,\nTo whom he sends, and what's his embassy:\nYourself, held precious in the world's esteem,\nTo parley with the sole inheritor\nOf all perfections that a man may owe,\nMatchless Navarre; the plea of no less weight\nThan Aquitaine, a dowry for a queen.\nBe now as prodigal of all dear grace\nAs Nature was in making graces dear\nWhen she did starve the general world beside\nAnd prodigally gave them all to you.","sourceLine":"2.1.1","speaker":"BOYET","id":"lll:2.1:2"},{"kind":"speech","text":"Good Lord Boyet, my beauty, though but mean,\nNeeds not the painted flourish of your praise:\nBeauty is bought by judgement of the eye,\nNot utter'd by base sale of chapmen's tongues:\nI am less proud to hear you tell my worth\nThan you much willing to be counted wise\nIn spending your wit in the praise of mine.\nBut now to task the tasker: good Boyet,\nYou are not ignorant, all-telling fame\nDoth noise abroad, Navarre hath made a vow,\nTill painful study shall outwear three years,\nNo woman may approach his silent court:\nTherefore to's seemeth it a needful course,\nBefore we enter his forbidden gates,\nTo know his pleasure; and in that behalf,\nBold of your worthiness, we single you\nAs our best-moving fair solicitor.\nTell him, the daughter of the King of France,\nOn serious business, craving quick dispatch,\nImportunes personal conference with his grace:\nHaste, signify so much; while we attend,\nLike humble-visaged suitors, his high will.","sourceLine":"2.1.13","speaker":"PRINCESS","id":"lll:2.1:3"},{"kind":"speech","text":"Proud of employment, willingly I go.","sourceLine":"2.1.35","speaker":"BOYET","id":"lll:2.1:4"},{"kind":"speech","text":"All pride is willing pride, and yours is so.","sourceLine":"2.1.36","speaker":"PRINCESS","id":"lll:2.1:5"},{"kind":"stage","text":"Exit BOYET","id":"lll:2.1:6"},{"kind":"speech","text":"Who are the votaries, my loving lords,\nThat are vow-fellows with this virtuous duke?","sourceLine":"2.1.37","speaker":"PRINCESS","id":"lll:2.1:7"},{"kind":"speech","text":"Lord Longaville is one.","sourceLine":"2.1.39","speaker":"First Lord","id":"lll:2.1:8"},{"kind":"speech","text":"Know you the man?","sourceLine":"2.1.40","speaker":"PRINCESS","id":"lll:2.1:9"},{"kind":"speech","text":"I know him, madam: at a marriage-feast,\nBetween Lord Perigort and the beauteous heir\nOf Jaques Falconbridge, solemnized\nIn Normandy, saw I this Longaville:\nA man of sovereign parts he is esteem'd;\nWell fitted in arts, glorious in arms:\nNothing becomes him ill that he would well.\nThe only soil of his fair virtue's gloss,\nIf virtue's gloss will stain with any soil,\nIs a sharp wit matched with too blunt a will;\nWhose edge hath power to cut, whose will still wills\nIt should none spare that come within his power.","sourceLine":"2.1.41","speaker":"MARIA","id":"lll:2.1:10"},{"kind":"speech","text":"Some merry mocking lord, belike; is't so?","sourceLine":"2.1.53","speaker":"PRINCESS","id":"lll:2.1:11"},{"kind":"speech","text":"They say so most that most his humours know.","sourceLine":"2.1.54","speaker":"MARIA","id":"lll:2.1:12"},{"kind":"speech","text":"Such short-lived wits do wither as they grow.\nWho are the rest?","sourceLine":"2.1.55","speaker":"PRINCESS","id":"lll:2.1:13"},{"kind":"speech","text":"The young Dumain, a well-accomplished youth,\nOf all that virtue love for virtue loved:\nMost power to do most harm, least knowing ill;\nFor he hath wit to make an ill shape good,\nAnd shape to win grace though he had no wit.\nI saw him at the Duke Alencon's once;\nAnd much too little of that good I saw\nIs my report to his great worthiness.","sourceLine":"2.1.57","speaker":"KATHARINE","id":"lll:2.1:14"},{"kind":"speech","text":"Another of these students at that time\nWas there with him, if I have heard a truth.\nBiron they call him; but a merrier man,\nWithin the limit of becoming mirth,\nI never spent an hour's talk withal:\nHis eye begets occasion for his wit;\nFor every object that the one doth catch\nThe other turns to a mirth-moving jest,\nWhich his fair tongue, conceit's expositor,\nDelivers in such apt and gracious words\nThat aged ears play truant at his tales\nAnd younger hearings are quite ravished;\nSo sweet and voluble is his discourse.","sourceLine":"2.1.65","speaker":"ROSALINE","id":"lll:2.1:15"},{"kind":"speech","text":"God bless my ladies! are they all in love,\nThat every one her own hath garnished\nWith such bedecking ornaments of praise?","sourceLine":"2.1.78","speaker":"PRINCESS","id":"lll:2.1:16"},{"kind":"speech","text":"Here comes Boyet.","sourceLine":"2.1.81","speaker":"First Lord","id":"lll:2.1:17"},{"kind":"stage","text":"Re-enter BOYET","id":"lll:2.1:18"},{"kind":"speech","text":"Now, what admittance, lord?","sourceLine":"2.1.82","speaker":"PRINCESS","id":"lll:2.1:19"},{"kind":"speech","text":"Navarre had notice of your fair approach;\nAnd he and his competitors in oath\nWere all address'd to meet you, gentle lady,\nBefore I came. Marry, thus much I have learnt:\nHe rather means to lodge you in the field,\nLike one that comes here to besiege his court,\nThan seek a dispensation for his oath,\nTo let you enter his unpeopled house.\nHere comes Navarre.","sourceLine":"2.1.83","speaker":"BOYET","id":"lll:2.1:20"},{"kind":"stage","text":"Enter FERDINAND, LONGAVILLE, DUMAIN, BIRON, and Attendants","id":"lll:2.1:21"},{"kind":"speech","text":"Fair princess, welcome to the court of Navarre.","sourceLine":"2.1.92","speaker":"FERDINAND","id":"lll:2.1:22"},{"kind":"speech","text":"'Fair' I give you back again; and 'welcome' I have\nnot yet: the roof of this court is too high to be\nyours; and welcome to the wide fields too base to be mine.","sourceLine":"2.1.93","speaker":"PRINCESS","id":"lll:2.1:23"},{"kind":"speech","text":"You shall be welcome, madam, to my court.","sourceLine":"2.1.96","speaker":"FERDINAND","id":"lll:2.1:24"},{"kind":"speech","text":"I will be welcome, then: conduct me thither.","sourceLine":"2.1.97","speaker":"PRINCESS","id":"lll:2.1:25"},{"kind":"speech","text":"Hear me, dear lady; I have sworn an oath.","sourceLine":"2.1.98","speaker":"FERDINAND","id":"lll:2.1:26"},{"kind":"speech","text":"Our Lady help my lord! he'll be forsworn.","sourceLine":"2.1.99","speaker":"PRINCESS","id":"lll:2.1:27"},{"kind":"speech","text":"Not for the world, fair madam, by my will.","sourceLine":"2.1.100","speaker":"FERDINAND","id":"lll:2.1:28"},{"kind":"speech","text":"Why, will shall break it; will and nothing else.","sourceLine":"2.1.101","speaker":"PRINCESS","id":"lll:2.1:29"},{"kind":"speech","text":"Your ladyship is ignorant what it is.","sourceLine":"2.1.102","speaker":"FERDINAND","id":"lll:2.1:30"},{"kind":"speech","text":"Were my lord so, his ignorance were wise,\nWhere now his knowledge must prove ignorance.\nI hear your grace hath sworn out house-keeping:\nTis deadly sin to keep that oath, my lord,\nAnd sin to break it.\nBut pardon me. I am too sudden-bold:\nTo teach a teacher ill beseemeth me.\nVouchsafe to read the purpose of my coming,\nAnd suddenly resolve me in my suit.","sourceLine":"2.1.103","speaker":"PRINCESS","id":"lll:2.1:31"},{"kind":"speech","text":"Madam, I will, if suddenly I may.","sourceLine":"2.1.112","speaker":"FERDINAND","id":"lll:2.1:32"},{"kind":"speech","text":"You will the sooner, that I were away;\nFor you'll prove perjured if you make me stay.","sourceLine":"2.1.113","speaker":"PRINCESS","id":"lll:2.1:33"},{"kind":"speech","text":"Did not I dance with you in Brabant once?","sourceLine":"2.1.115","speaker":"BIRON","id":"lll:2.1:34"},{"kind":"speech","text":"Did not I dance with you in Brabant once?","sourceLine":"2.1.116","speaker":"ROSALINE","id":"lll:2.1:35"},{"kind":"speech","text":"I know you did.","sourceLine":"2.1.117","speaker":"BIRON","id":"lll:2.1:36"},{"kind":"speech","text":"How needless was it then to ask the question!","sourceLine":"2.1.118","speaker":"ROSALINE","id":"lll:2.1:37"},{"kind":"speech","text":"You must not be so quick.","sourceLine":"2.1.119","speaker":"BIRON","id":"lll:2.1:38"},{"kind":"speech","text":"'Tis 'long of you that spur me with such questions.","sourceLine":"2.1.120","speaker":"ROSALINE","id":"lll:2.1:39"},{"kind":"speech","text":"Your wit's too hot, it speeds too fast, 'twill tire.","sourceLine":"2.1.121","speaker":"BIRON","id":"lll:2.1:40"},{"kind":"speech","text":"Not till it leave the rider in the mire.","sourceLine":"2.1.122","speaker":"ROSALINE","id":"lll:2.1:41"},{"kind":"speech","text":"What time o' day?","sourceLine":"2.1.123","speaker":"BIRON","id":"lll:2.1:42"},{"kind":"speech","text":"The hour that fools should ask.","sourceLine":"2.1.124","speaker":"ROSALINE","id":"lll:2.1:43"},{"kind":"speech","text":"Now fair befall your mask!","sourceLine":"2.1.125","speaker":"BIRON","id":"lll:2.1:44"},{"kind":"speech","text":"Fair fall the face it covers!","sourceLine":"2.1.126","speaker":"ROSALINE","id":"lll:2.1:45"},{"kind":"speech","text":"And send you many lovers!","sourceLine":"2.1.127","speaker":"BIRON","id":"lll:2.1:46"},{"kind":"speech","text":"Amen, so you be none.","sourceLine":"2.1.128","speaker":"ROSALINE","id":"lll:2.1:47"},{"kind":"speech","text":"Nay, then will I be gone.","sourceLine":"2.1.129","speaker":"BIRON","id":"lll:2.1:48"},{"kind":"speech","text":"Madam, your father here doth intimate\nThe payment of a hundred thousand crowns;\nBeing but the one half of an entire sum\nDisbursed by my father in his wars.\nBut say that he or we, as neither have,\nReceived that sum, yet there remains unpaid\nA hundred thousand more; in surety of the which,\nOne part of Aquitaine is bound to us,\nAlthough not valued to the money's worth.\nIf then the king your father will restore\nBut that one half which is unsatisfied,\nWe will give up our right in Aquitaine,\nAnd hold fair friendship with his majesty.\nBut that, it seems, he little purposeth,\nFor here he doth demand to have repaid\nA hundred thousand crowns; and not demands,\nOn payment of a hundred thousand crowns,\nTo have his title live in Aquitaine;\nWhich we much rather had depart withal\nAnd have the money by our father lent\nThan Aquitaine so gelded as it is.\nDear Princess, were not his requests so far\nFrom reason's yielding, your fair self should make\nA yielding 'gainst some reason in my breast\nAnd go well satisfied to France again.","sourceLine":"2.1.130","speaker":"FERDINAND","id":"lll:2.1:49"},{"kind":"speech","text":"You do the king my father too much wrong\nAnd wrong the reputation of your name,\nIn so unseeming to confess receipt\nOf that which hath so faithfully been paid.","sourceLine":"2.1.155","speaker":"PRINCESS","id":"lll:2.1:50"},{"kind":"speech","text":"I do protest I never heard of it;\nAnd if you prove it, I'll repay it back\nOr yield up Aquitaine.","sourceLine":"2.1.159","speaker":"FERDINAND","id":"lll:2.1:51"},{"kind":"speech","text":"We arrest your word.\nBoyet, you can produce acquittances\nFor such a sum from special officers\nOf Charles his father.","sourceLine":"2.1.162","speaker":"PRINCESS","id":"lll:2.1:52"},{"kind":"speech","text":"Satisfy me so.","sourceLine":"2.1.166","speaker":"FERDINAND","id":"lll:2.1:53"},{"kind":"speech","text":"So please your grace, the packet is not come\nWhere that and other specialties are bound:\nTo-morrow you shall have a sight of them.","sourceLine":"2.1.167","speaker":"BOYET","id":"lll:2.1:54"},{"kind":"speech","text":"It shall suffice me: at which interview\nAll liberal reason I will yield unto.\nMeantime receive such welcome at my hand\nAs honour without breach of honour may\nMake tender of to thy true worthiness:\nYou may not come, fair princess, in my gates;\nBut here without you shall be so received\nAs you shall deem yourself lodged in my heart,\nThough so denied fair harbour in my house.\nYour own good thoughts excuse me, and farewell:\nTo-morrow shall we visit you again.","sourceLine":"2.1.170","speaker":"FERDINAND","id":"lll:2.1:55"},{"kind":"speech","text":"Sweet health and fair desires consort your grace!","sourceLine":"2.1.181","speaker":"PRINCESS","id":"lll:2.1:56"},{"kind":"speech","text":"Thy own wish wish I thee in every place!","sourceLine":"2.1.182","speaker":"FERDINAND","id":"lll:2.1:57"},{"kind":"stage","text":"Exit","id":"lll:2.1:58"},{"kind":"speech","text":"Lady, I will commend you to mine own heart.","sourceLine":"2.1.183","speaker":"BIRON","id":"lll:2.1:59"},{"kind":"speech","text":"Pray you, do my commendations; I would be glad to see it.","sourceLine":"2.1.184","speaker":"ROSALINE","id":"lll:2.1:60"},{"kind":"speech","text":"I would you heard it groan.","sourceLine":"2.1.185","speaker":"BIRON","id":"lll:2.1:61"},{"kind":"speech","text":"Is the fool sick?","sourceLine":"2.1.186","speaker":"ROSALINE","id":"lll:2.1:62"},{"kind":"speech","text":"Sick at the heart.","sourceLine":"2.1.187","speaker":"BIRON","id":"lll:2.1:63"},{"kind":"speech","text":"Alack, let it blood.","sourceLine":"2.1.188","speaker":"ROSALINE","id":"lll:2.1:64"},{"kind":"speech","text":"Would that do it good?","sourceLine":"2.1.189","speaker":"BIRON","id":"lll:2.1:65"},{"kind":"speech","text":"My physic says 'ay.'","sourceLine":"2.1.190","speaker":"ROSALINE","id":"lll:2.1:66"},{"kind":"speech","text":"Will you prick't with your eye?","sourceLine":"2.1.191","speaker":"BIRON","id":"lll:2.1:67"},{"kind":"speech","text":"No point, with my knife.","sourceLine":"2.1.192","speaker":"ROSALINE","id":"lll:2.1:68"},{"kind":"speech","text":"Now, God save thy life!","sourceLine":"2.1.193","speaker":"BIRON","id":"lll:2.1:69"},{"kind":"speech","text":"And yours from long living!","sourceLine":"2.1.194","speaker":"ROSALINE","id":"lll:2.1:70"},{"kind":"speech","text":"I cannot stay thanksgiving.","sourceLine":"2.1.195","speaker":"BIRON","id":"lll:2.1:71"},{"kind":"stage","text":"Retiring","id":"lll:2.1:72"},{"kind":"speech","text":"Sir, I pray you, a word: what lady is that same?","sourceLine":"2.1.196","speaker":"DUMAIN","id":"lll:2.1:73"},{"kind":"speech","text":"The heir of Alencon, Katharine her name.","sourceLine":"2.1.197","speaker":"BOYET","id":"lll:2.1:74"},{"kind":"speech","text":"A gallant lady. Monsieur, fare you well.","sourceLine":"2.1.198","speaker":"DUMAIN","id":"lll:2.1:75"},{"kind":"stage","text":"Exit","id":"lll:2.1:76"},{"kind":"speech","text":"I beseech you a word: what is she in the white?","sourceLine":"2.1.199","speaker":"LONGAVILLE","id":"lll:2.1:77"},{"kind":"speech","text":"A woman sometimes, an you saw her in the light.","sourceLine":"2.1.200","speaker":"BOYET","id":"lll:2.1:78"},{"kind":"speech","text":"Perchance light in the light. I desire her name.","sourceLine":"2.1.201","speaker":"LONGAVILLE","id":"lll:2.1:79"},{"kind":"speech","text":"She hath but one for herself; to desire that were a shame.","sourceLine":"2.1.202","speaker":"BOYET","id":"lll:2.1:80"},{"kind":"speech","text":"Pray you, sir, whose daughter?","sourceLine":"2.1.203","speaker":"LONGAVILLE","id":"lll:2.1:81"},{"kind":"speech","text":"Her mother's, I have heard.","sourceLine":"2.1.204","speaker":"BOYET","id":"lll:2.1:82"},{"kind":"speech","text":"God's blessing on your beard!","sourceLine":"2.1.205","speaker":"LONGAVILLE","id":"lll:2.1:83"},{"kind":"speech","text":"Good sir, be not offended.\nShe is an heir of Falconbridge.","sourceLine":"2.1.206","speaker":"BOYET","id":"lll:2.1:84"},{"kind":"speech","text":"Nay, my choler is ended.\nShe is a most sweet lady.","sourceLine":"2.1.208","speaker":"LONGAVILLE","id":"lll:2.1:85"},{"kind":"speech","text":"Not unlike, sir, that may be.","sourceLine":"2.1.210","speaker":"BOYET","id":"lll:2.1:86"},{"kind":"stage","text":"Exit LONGAVILLE","id":"lll:2.1:87"},{"kind":"speech","text":"What's her name in the cap?","sourceLine":"2.1.211","speaker":"BIRON","id":"lll:2.1:88"},{"kind":"speech","text":"Rosaline, by good hap.","sourceLine":"2.1.212","speaker":"BOYET","id":"lll:2.1:89"},{"kind":"speech","text":"Is she wedded or no?","sourceLine":"2.1.213","speaker":"BIRON","id":"lll:2.1:90"},{"kind":"speech","text":"To her will, sir, or so.","sourceLine":"2.1.214","speaker":"BOYET","id":"lll:2.1:91"},{"kind":"speech","text":"You are welcome, sir: adieu.","sourceLine":"2.1.215","speaker":"BIRON","id":"lll:2.1:92"},{"kind":"speech","text":"Farewell to me, sir, and welcome to you.","sourceLine":"2.1.216","speaker":"BOYET","id":"lll:2.1:93"},{"kind":"stage","text":"Exit BIRON","id":"lll:2.1:94"},{"kind":"speech","text":"That last is Biron, the merry madcap lord:\nNot a word with him but a jest.","sourceLine":"2.1.217","speaker":"MARIA","id":"lll:2.1:95"},{"kind":"speech","text":"And every jest but a word.","sourceLine":"2.1.219","speaker":"BOYET","id":"lll:2.1:96"},{"kind":"speech","text":"It was well done of you to take him at his word.","sourceLine":"2.1.220","speaker":"PRINCESS","id":"lll:2.1:97"},{"kind":"speech","text":"I was as willing to grapple as he was to board.","sourceLine":"2.1.221","speaker":"BOYET","id":"lll:2.1:98"},{"kind":"speech","text":"Two hot sheeps, marry.","sourceLine":"2.1.222","speaker":"MARIA","id":"lll:2.1:99"},{"kind":"speech","text":"And wherefore not ships?\nNo sheep, sweet lamb, unless we feed on your lips.","sourceLine":"2.1.223","speaker":"BOYET","id":"lll:2.1:100"},{"kind":"speech","text":"You sheep, and I pasture: shall that finish the jest?","sourceLine":"2.1.225","speaker":"MARIA","id":"lll:2.1:101"},{"kind":"speech","text":"So you grant pasture for me.","sourceLine":"2.1.226","speaker":"BOYET","id":"lll:2.1:102"},{"kind":"stage","text":"Offering to kiss her","id":"lll:2.1:103"},{"kind":"speech","text":"Not so, gentle beast:\nMy lips are no common, though several they be.","sourceLine":"2.1.227","speaker":"MARIA","id":"lll:2.1:104"},{"kind":"speech","text":"Belonging to whom?","sourceLine":"2.1.229","speaker":"BOYET","id":"lll:2.1:105"},{"kind":"speech","text":"To my fortunes and me.","sourceLine":"2.1.230","speaker":"MARIA","id":"lll:2.1:106"},{"kind":"speech","text":"Good wits will be jangling; but, gentles, agree:\nThis civil war of wits were much better used\nOn Navarre and his book-men; for here 'tis abused.","sourceLine":"2.1.231","speaker":"PRINCESS","id":"lll:2.1:107"},{"kind":"speech","text":"If my observation, which very seldom lies,\nBy the heart's still rhetoric disclosed with eyes,\nDeceive me not now, Navarre is infected.","sourceLine":"2.1.234","speaker":"BOYET","id":"lll:2.1:108"},{"kind":"speech","text":"With what?","sourceLine":"2.1.237","speaker":"PRINCESS","id":"lll:2.1:109"},{"kind":"speech","text":"With that which we lovers entitle affected.","sourceLine":"2.1.238","speaker":"BOYET","id":"lll:2.1:110"},{"kind":"speech","text":"Your reason?","sourceLine":"2.1.239","speaker":"PRINCESS","id":"lll:2.1:111"},{"kind":"speech","text":"Why, all his behaviors did make their retire\nTo the court of his eye, peeping thorough desire:\nHis heart, like an agate, with your print impress'd,\nProud with his form, in his eye pride express'd:\nHis tongue, all impatient to speak and not see,\nDid stumble with haste in his eyesight to be;\nAll senses to that sense did make their repair,\nTo feel only looking on fairest of fair:\nMethought all his senses were lock'd in his eye,\nAs jewels in crystal for some prince to buy;\nWho, tendering their own worth from where they were glass'd,\nDid point you to buy them, along as you pass'd:\nHis face's own margent did quote such amazes\nThat all eyes saw his eyes enchanted with gazes.\nI'll give you Aquitaine and all that is his,\nAn you give him for my sake but one loving kiss.","sourceLine":"2.1.240","speaker":"BOYET","id":"lll:2.1:112"},{"kind":"speech","text":"Come to our pavilion: Boyet is disposed.","sourceLine":"2.1.256","speaker":"PRINCESS","id":"lll:2.1:113"},{"kind":"speech","text":"But to speak that in words which his eye hath\ndisclosed.\nI only have made a mouth of his eye,\nBy adding a tongue which I know will not lie.","sourceLine":"2.1.257","speaker":"BOYET","id":"lll:2.1:114"},{"kind":"speech","text":"Thou art an old love-monger and speakest skilfully.","sourceLine":"2.1.261","speaker":"ROSALINE","id":"lll:2.1:115"},{"kind":"speech","text":"He is Cupid's grandfather and learns news of him.","sourceLine":"2.1.262","speaker":"MARIA","id":"lll:2.1:116"},{"kind":"speech","text":"Then was Venus like her mother, for her father is but grim.","sourceLine":"2.1.263","speaker":"ROSALINE","id":"lll:2.1:117"},{"kind":"speech","text":"Do you hear, my mad wenches?","sourceLine":"2.1.264","speaker":"BOYET","id":"lll:2.1:118"},{"kind":"speech","text":"No.","sourceLine":"2.1.265","speaker":"MARIA","id":"lll:2.1:119"},{"kind":"speech","text":"What then, do you see?","sourceLine":"2.1.266","speaker":"BOYET","id":"lll:2.1:120"},{"kind":"speech","text":"Ay, our way to be gone.","sourceLine":"2.1.267","speaker":"ROSALINE","id":"lll:2.1:121"},{"kind":"speech","text":"You are too hard for me.","sourceLine":"2.1.268","speaker":"BOYET","id":"lll:2.1:122"},{"kind":"stage","text":"Exeunt","id":"lll:2.1:123"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"2.1.269","speaker":"BOYET","id":"lll:2.1:124"}],"scene":1},{"id":"3.1","label":"Act 3 · SCENE I. The same.","act":3,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter DON ADRIANO DE ARMADO and MOTH","id":"lll:3.1:1"},{"kind":"speech","text":"Warble, child; make passionate my sense of hearing.","sourceLine":"3.1.2","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.1","rawPrefix":"DON","followingSpeechAnchor":"speech1","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2058,"originalHtml":"<A NAME=3.1.1>DON</A><br>\n</blockquote>\n\n<A NAME=speech1><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:2"},{"kind":"speech","text":"Concolinel.","sourceLine":"3.1.3","speaker":"MOTH","id":"lll:3.1:3"},{"kind":"stage","text":"Singing","id":"lll:3.1:4"},{"kind":"speech","text":"Sweet air! Go, tenderness of years; take this key,\ngive enlargement to the swain, bring him festinately\nhither: I must employ him in a letter to my love.","sourceLine":"3.1.5","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.4","rawPrefix":"DON","followingSpeechAnchor":"speech3","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2070,"originalHtml":"<A NAME=3.1.4>DON</A><br>\n</blockquote>\n\n<A NAME=speech3><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:5"},{"kind":"speech","text":"Master, will you win your love with a French brawl?","sourceLine":"3.1.8","speaker":"MOTH","id":"lll:3.1:6"},{"kind":"speech","text":"How meanest thou? brawling in French?","sourceLine":"3.1.10","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.9","rawPrefix":"DON","followingSpeechAnchor":"speech5","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2083,"originalHtml":"<A NAME=3.1.9>DON</A><br>\n</blockquote>\n\n<A NAME=speech5><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:7"},{"kind":"speech","text":"No, my complete master: but to jig off a tune at\nthe tongue's end, canary to it with your feet, humour\nit with turning up your eyelids, sigh a note and\nsing a note, sometime through the throat, as if you\nswallowed love with singing love, sometime through\nthe nose, as if you snuffed up love by smelling\nlove; with your hat penthouse-like o'er the shop of\nyour eyes; with your arms crossed on your thin-belly\ndoublet like a rabbit on a spit; or your hands in\nyour pocket like a man after the old painting; and\nkeep not too long in one tune, but a snip and away.\nThese are complements, these are humours; these\nbetray nice wenches, that would be betrayed without\nthese; and make them men of note--do you note\nme?--that most are affected to these.","sourceLine":"3.1.11","speaker":"MOTH","id":"lll:3.1:8"},{"kind":"speech","text":"How hast thou purchased this experience?","sourceLine":"3.1.27","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.26","rawPrefix":"DON","followingSpeechAnchor":"speech7","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2108,"originalHtml":"<A NAME=3.1.26>DON</A><br>\n</blockquote>\n\n<A NAME=speech7><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:9"},{"kind":"speech","text":"By my penny of observation.","sourceLine":"3.1.28","speaker":"MOTH","id":"lll:3.1:10"},{"kind":"speech","text":"But O,--but O,--","sourceLine":"3.1.30","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.29","rawPrefix":"DON","followingSpeechAnchor":"speech9","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2119,"originalHtml":"<A NAME=3.1.29>DON</A><br>\n</blockquote>\n\n<A NAME=speech9><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:11"},{"kind":"speech","text":"'The hobby-horse is forgot.'","sourceLine":"3.1.31","speaker":"MOTH","id":"lll:3.1:12"},{"kind":"speech","text":"Callest thou my love 'hobby-horse'?","sourceLine":"3.1.33","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.32","rawPrefix":"DON","followingSpeechAnchor":"speech11","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2130,"originalHtml":"<A NAME=3.1.32>DON</A><br>\n</blockquote>\n\n<A NAME=speech11><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:13"},{"kind":"speech","text":"No, master; the hobby-horse is but a colt, and your\nlove perhaps a hackney. But have you forgot your love?","sourceLine":"3.1.34","speaker":"MOTH","id":"lll:3.1:14"},{"kind":"speech","text":"Almost I had.","sourceLine":"3.1.37","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.36","rawPrefix":"DON","followingSpeechAnchor":"speech13","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2142,"originalHtml":"<A NAME=3.1.36>DON</A><br>\n</blockquote>\n\n<A NAME=speech13><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:15"},{"kind":"speech","text":"Negligent student! learn her by heart.","sourceLine":"3.1.38","speaker":"MOTH","id":"lll:3.1:16"},{"kind":"speech","text":"By heart and in heart, boy.","sourceLine":"3.1.40","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.39","rawPrefix":"DON","followingSpeechAnchor":"speech15","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2153,"originalHtml":"<A NAME=3.1.39>DON</A><br>\n</blockquote>\n\n<A NAME=speech15><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:17"},{"kind":"speech","text":"And out of heart, master: all those three I will prove.","sourceLine":"3.1.41","speaker":"MOTH","id":"lll:3.1:18"},{"kind":"speech","text":"What wilt thou prove?","sourceLine":"3.1.43","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.42","rawPrefix":"DON","followingSpeechAnchor":"speech17","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2164,"originalHtml":"<A NAME=3.1.42>DON</A><br>\n</blockquote>\n\n<A NAME=speech17><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:19"},{"kind":"speech","text":"A man, if I live; and this, by, in, and without, upon\nthe instant: by heart you love her, because your\nheart cannot come by her; in heart you love her,\nbecause your heart is in love with her; and out of\nheart you love her, being out of heart that you\ncannot enjoy her.","sourceLine":"3.1.44","speaker":"MOTH","id":"lll:3.1:20"},{"kind":"speech","text":"I am all these three.","sourceLine":"3.1.51","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.50","rawPrefix":"DON","followingSpeechAnchor":"speech19","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2180,"originalHtml":"<A NAME=3.1.50>DON</A><br>\n</blockquote>\n\n<A NAME=speech19><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:21"},{"kind":"speech","text":"And three times as much more, and yet nothing at\nall.","sourceLine":"3.1.52","speaker":"MOTH","id":"lll:3.1:22"},{"kind":"speech","text":"Fetch hither the swain: he must carry me a letter.","sourceLine":"3.1.55","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.54","rawPrefix":"DON","followingSpeechAnchor":"speech21","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2192,"originalHtml":"<A NAME=3.1.54>DON</A><br>\n</blockquote>\n\n<A NAME=speech21><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:23"},{"kind":"speech","text":"A message well sympathized; a horse to be ambassador\nfor an ass.","sourceLine":"3.1.56","speaker":"MOTH","id":"lll:3.1:24"},{"kind":"speech","text":"Ha, ha! what sayest thou?","sourceLine":"3.1.59","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.58","rawPrefix":"DON","followingSpeechAnchor":"speech23","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2204,"originalHtml":"<A NAME=3.1.58>DON</A><br>\n</blockquote>\n\n<A NAME=speech23><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:25"},{"kind":"speech","text":"Marry, sir, you must send the ass upon the horse,\nfor he is very slow-gaited. But I go.","sourceLine":"3.1.60","speaker":"MOTH","id":"lll:3.1:26"},{"kind":"speech","text":"The way is but short: away!","sourceLine":"3.1.63","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.62","rawPrefix":"DON","followingSpeechAnchor":"speech25","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2216,"originalHtml":"<A NAME=3.1.62>DON</A><br>\n</blockquote>\n\n<A NAME=speech25><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:27"},{"kind":"speech","text":"As swift as lead, sir.","sourceLine":"3.1.64","speaker":"MOTH","id":"lll:3.1:28"},{"kind":"speech","text":"The meaning, pretty ingenious?\nIs not lead a metal heavy, dull, and slow?","sourceLine":"3.1.66","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.65","rawPrefix":"DON","followingSpeechAnchor":"speech27","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2227,"originalHtml":"<A NAME=3.1.65>DON</A><br>\n</blockquote>\n\n<A NAME=speech27><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:29"},{"kind":"speech","text":"Minime, honest master; or rather, master, no.","sourceLine":"3.1.68","speaker":"MOTH","id":"lll:3.1:30"},{"kind":"speech","text":"I say lead is slow.","sourceLine":"3.1.70","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.69","rawPrefix":"DON","followingSpeechAnchor":"speech29","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2239,"originalHtml":"<A NAME=3.1.69>DON</A><br>\n</blockquote>\n\n<A NAME=speech29><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:31"},{"kind":"speech","text":"You are too swift, sir, to say so:\nIs that lead slow which is fired from a gun?","sourceLine":"3.1.71","speaker":"MOTH","id":"lll:3.1:32"},{"kind":"speech","text":"Sweet smoke of rhetoric!\nHe reputes me a cannon; and the bullet, that's he:\nI shoot thee at the swain.","sourceLine":"3.1.74","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.73","rawPrefix":"DON","followingSpeechAnchor":"speech31","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2251,"originalHtml":"<A NAME=3.1.73>DON</A><br>\n</blockquote>\n\n<A NAME=speech31><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:33"},{"kind":"speech","text":"Thump then and I flee.","sourceLine":"3.1.77","speaker":"MOTH","id":"lll:3.1:34"},{"kind":"stage","text":"Exit","id":"lll:3.1:35"},{"kind":"speech","text":"A most acute juvenal; voluble and free of grace!\nBy thy favour, sweet welkin, I must sigh in thy face:\nMost rude melancholy, valour gives thee place.\nMy herald is return'd.","sourceLine":"3.1.79","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.78","rawPrefix":"DON","followingSpeechAnchor":"speech33","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2265,"originalHtml":"<A NAME=3.1.78>DON</A><br>\n</blockquote>\n\n<A NAME=speech33><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:36"},{"kind":"stage","text":"Re-enter MOTH with COSTARD","id":"lll:3.1:37"},{"kind":"speech","text":"A wonder, master! here's a costard broken in a shin.","sourceLine":"3.1.83","speaker":"MOTH","id":"lll:3.1:38"},{"kind":"speech","text":"Some enigma, some riddle: come, thy l'envoy; begin.","sourceLine":"3.1.85","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.84","rawPrefix":"DON","followingSpeechAnchor":"speech35","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2280,"originalHtml":"<A NAME=3.1.84>DON</A><br>\n</blockquote>\n\n<A NAME=speech35><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:39"},{"kind":"speech","text":"No enigma, no riddle, no l'envoy; no salve in the\nmail, sir: O, sir, plantain, a plain plantain! no\nl'envoy, no l'envoy; no salve, sir, but a plantain!","sourceLine":"3.1.86","speaker":"COSTARD","id":"lll:3.1:40"},{"kind":"speech","text":"By virtue, thou enforcest laughter; thy silly\nthought my spleen; the heaving of my lungs provokes\nme to ridiculous smiling. O, pardon me, my stars!\nDoth the inconsiderate take salve for l'envoy, and\nthe word l'envoy for a salve?","sourceLine":"3.1.90","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.89","rawPrefix":"DON","followingSpeechAnchor":"speech37","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2293,"originalHtml":"<A NAME=3.1.89>DON</A><br>\n</blockquote>\n\n<A NAME=speech37><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:41"},{"kind":"speech","text":"Do the wise think them other? is not l'envoy a salve?","sourceLine":"3.1.95","speaker":"MOTH","id":"lll:3.1:42"},{"kind":"speech","text":"No, page: it is an epilogue or discourse, to make plain\nSome obscure precedence that hath tofore been sain.\nI will example it:\nThe fox, the ape, and the humble-bee,\nWere still at odds, being but three.\nThere's the moral. Now the l'envoy.","sourceLine":"3.1.97","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.96","rawPrefix":"DON","followingSpeechAnchor":"speech39","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2308,"originalHtml":"<A NAME=3.1.96>DON</A><br>\n</blockquote>\n\n<A NAME=speech39><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:43"},{"kind":"speech","text":"I will add the l'envoy. Say the moral again.","sourceLine":"3.1.103","speaker":"MOTH","id":"lll:3.1:44"},{"kind":"speech","text":"The fox, the ape, and the humble-bee,\nWere still at odds, being but three.","sourceLine":"3.1.105","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.104","rawPrefix":"DON","followingSpeechAnchor":"speech41","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2324,"originalHtml":"<A NAME=3.1.104>DON</A><br>\n</blockquote>\n\n<A NAME=speech41><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:45"},{"kind":"speech","text":"Until the goose came out of door,\nAnd stay'd the odds by adding four.\nNow will I begin your moral, and do you follow with\nmy l'envoy.\nThe fox, the ape, and the humble-bee,\nWere still at odds, being but three.","sourceLine":"3.1.107","speaker":"MOTH","id":"lll:3.1:46"},{"kind":"speech","text":"Until the goose came out of door,\nStaying the odds by adding four.","sourceLine":"3.1.114","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.113","rawPrefix":"DON","followingSpeechAnchor":"speech43","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2341,"originalHtml":"<A NAME=3.1.113>DON</A><br>\n</blockquote>\n\n<A NAME=speech43><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:47"},{"kind":"speech","text":"A good l'envoy, ending in the goose: would you\ndesire more?","sourceLine":"3.1.116","speaker":"MOTH","id":"lll:3.1:48"},{"kind":"speech","text":"The boy hath sold him a bargain, a goose, that's flat.\nSir, your pennyworth is good, an your goose be fat.\nTo sell a bargain well is as cunning as fast and loose:\nLet me see; a fat l'envoy; ay, that's a fat goose.","sourceLine":"3.1.118","speaker":"COSTARD","id":"lll:3.1:49"},{"kind":"speech","text":"Come hither, come hither. How did this argument begin?","sourceLine":"3.1.123","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.122","rawPrefix":"DON","followingSpeechAnchor":"speech46","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2362,"originalHtml":"<A NAME=3.1.122>DON</A><br>\n</blockquote>\n\n<A NAME=speech46><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:50"},{"kind":"speech","text":"By saying that a costard was broken in a shin.\nThen call'd you for the l'envoy.","sourceLine":"3.1.124","speaker":"MOTH","id":"lll:3.1:51"},{"kind":"speech","text":"True, and I for a plantain: thus came your\nargument in;\nThen the boy's fat l'envoy, the goose that you bought;\nAnd he ended the market.","sourceLine":"3.1.126","speaker":"COSTARD","id":"lll:3.1:52"},{"kind":"speech","text":"But tell me; how was there a costard broken in a shin?","sourceLine":"3.1.131","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.130","rawPrefix":"DON","followingSpeechAnchor":"speech49","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2382,"originalHtml":"<A NAME=3.1.130>DON</A><br>\n</blockquote>\n\n<A NAME=speech49><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:53"},{"kind":"speech","text":"I will tell you sensibly.","sourceLine":"3.1.132","speaker":"MOTH","id":"lll:3.1:54"},{"kind":"speech","text":"Thou hast no feeling of it, Moth: I will speak that l'envoy:\nI Costard, running out, that was safely within,\nFell over the threshold and broke my shin.","sourceLine":"3.1.133","speaker":"COSTARD","id":"lll:3.1:55"},{"kind":"speech","text":"We will talk no more of this matter.","sourceLine":"3.1.137","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.136","rawPrefix":"DON","followingSpeechAnchor":"speech52","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2400,"originalHtml":"<A NAME=3.1.136>DON</A><br>\n</blockquote>\n\n<A NAME=speech52><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:56"},{"kind":"speech","text":"Till there be more matter in the shin.","sourceLine":"3.1.138","speaker":"COSTARD","id":"lll:3.1:57"},{"kind":"speech","text":"Sirrah Costard, I will enfranchise thee.","sourceLine":"3.1.140","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.139","rawPrefix":"DON","followingSpeechAnchor":"speech54","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2411,"originalHtml":"<A NAME=3.1.139>DON</A><br>\n</blockquote>\n\n<A NAME=speech54><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:58"},{"kind":"speech","text":"O, marry me to one Frances: I smell some l'envoy,\nsome goose, in this.","sourceLine":"3.1.141","speaker":"COSTARD","id":"lll:3.1:59"},{"kind":"speech","text":"By my sweet soul, I mean setting thee at liberty,\nenfreedoming thy person; thou wert immured,\nrestrained, captivated, bound.","sourceLine":"3.1.144","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.143","rawPrefix":"DON","followingSpeechAnchor":"speech56","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2423,"originalHtml":"<A NAME=3.1.143>DON</A><br>\n</blockquote>\n\n<A NAME=speech56><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:60"},{"kind":"speech","text":"True, true; and now you will be my purgation and let me loose.","sourceLine":"3.1.147","speaker":"COSTARD","id":"lll:3.1:61"},{"kind":"speech","text":"I give thee thy liberty, set thee from durance; and,\nin lieu thereof, impose on thee nothing but this:\nbear this significant","sourceLine":"3.1.149","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"3.1.148","rawPrefix":"DON","followingSpeechAnchor":"speech58","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":2436,"originalHtml":"<A NAME=3.1.148>DON</A><br>\n</blockquote>\n\n<A NAME=speech58><b>ADRIANO DE ARMADO</b>"},"id":"lll:3.1:62"},{"kind":"stage","text":"Giving a letter","id":"lll:3.1:63"},{"kind":"speech","text":"to the country maid Jaquenetta:\nthere is remuneration; for the best ward of mine\nhonour is rewarding my dependents. Moth, follow.","sourceLine":"3.1.152","speaker":"DON ADRIANO DE ARMADO","id":"lll:3.1:64"},{"kind":"stage","text":"Exit","id":"lll:3.1:65"},{"kind":"speech","text":"Like the sequel, I. Signior Costard, adieu.","sourceLine":"3.1.155","speaker":"MOTH","id":"lll:3.1:66"},{"kind":"speech","text":"My sweet ounce of man's flesh! my incony Jew!","sourceLine":"3.1.156","speaker":"COSTARD","id":"lll:3.1:67"},{"kind":"stage","text":"Exit MOTH","id":"lll:3.1:68"},{"kind":"speech","text":"Now will I look to his remuneration. Remuneration!\nO, that's the Latin word for three farthings: three\nfarthings--remuneration.--'What's the price of this\ninkle?'--'One penny.'--'No, I'll give you a\nremuneration:' why, it carries it. Remuneration!\nwhy, it is a fairer name than French crown. I will\nnever buy and sell out of this word.","sourceLine":"3.1.157","speaker":"COSTARD","id":"lll:3.1:69"},{"kind":"stage","text":"Enter BIRON","id":"lll:3.1:70"},{"kind":"speech","text":"O, my good knave Costard! exceedingly well met.","sourceLine":"3.1.164","speaker":"BIRON","id":"lll:3.1:71"},{"kind":"speech","text":"Pray you, sir, how much carnation ribbon may a man\nbuy for a remuneration?","sourceLine":"3.1.165","speaker":"COSTARD","id":"lll:3.1:72"},{"kind":"speech","text":"What is a remuneration?","sourceLine":"3.1.167","speaker":"BIRON","id":"lll:3.1:73"},{"kind":"speech","text":"Marry, sir, halfpenny farthing.","sourceLine":"3.1.168","speaker":"COSTARD","id":"lll:3.1:74"},{"kind":"speech","text":"Why, then, three-farthing worth of silk.","sourceLine":"3.1.169","speaker":"BIRON","id":"lll:3.1:75"},{"kind":"speech","text":"I thank your worship: God be wi' you!","sourceLine":"3.1.170","speaker":"COSTARD","id":"lll:3.1:76"},{"kind":"speech","text":"Stay, slave; I must employ thee:\nAs thou wilt win my favour, good my knave,\nDo one thing for me that I shall entreat.","sourceLine":"3.1.171","speaker":"BIRON","id":"lll:3.1:77"},{"kind":"speech","text":"When would you have it done, sir?","sourceLine":"3.1.174","speaker":"COSTARD","id":"lll:3.1:78"},{"kind":"speech","text":"This afternoon.","sourceLine":"3.1.175","speaker":"BIRON","id":"lll:3.1:79"},{"kind":"speech","text":"Well, I will do it, sir: fare you well.","sourceLine":"3.1.176","speaker":"COSTARD","id":"lll:3.1:80"},{"kind":"speech","text":"Thou knowest not what it is.","sourceLine":"3.1.177","speaker":"BIRON","id":"lll:3.1:81"},{"kind":"speech","text":"I shall know, sir, when I have done it.","sourceLine":"3.1.178","speaker":"COSTARD","id":"lll:3.1:82"},{"kind":"speech","text":"Why, villain, thou must know first.","sourceLine":"3.1.179","speaker":"BIRON","id":"lll:3.1:83"},{"kind":"speech","text":"I will come to your worship to-morrow morning.","sourceLine":"3.1.180","speaker":"COSTARD","id":"lll:3.1:84"},{"kind":"speech","text":"It must be done this afternoon.\nHark, slave, it is but this:\nThe princess comes to hunt here in the park,\nAnd in her train there is a gentle lady;\nWhen tongues speak sweetly, then they name her name,\nAnd Rosaline they call her: ask for her;\nAnd to her white hand see thou do commend\nThis seal'd-up counsel. There's thy guerdon; go.","sourceLine":"3.1.181","speaker":"BIRON","id":"lll:3.1:85"},{"kind":"stage","text":"Giving him a shilling","id":"lll:3.1:86"},{"kind":"speech","text":"Gardon, O sweet gardon! better than remuneration,\na'leven-pence farthing better: most sweet gardon! I\nwill do it sir, in print. Gardon! Remuneration!","sourceLine":"3.1.189","speaker":"COSTARD","id":"lll:3.1:87"},{"kind":"stage","text":"Exit","id":"lll:3.1:88"},{"kind":"speech","text":"And I, forsooth, in love! I, that have been love's whip;\nA very beadle to a humorous sigh;\nA critic, nay, a night-watch constable;\nA domineering pedant o'er the boy;\nThan whom no mortal so magnificent!\nThis whimpled, whining, purblind, wayward boy;\nThis senior-junior, giant-dwarf, Dan Cupid;\nRegent of love-rhymes, lord of folded arms,\nThe anointed sovereign of sighs and groans,\nLiege of all loiterers and malcontents,\nDread prince of plackets, king of codpieces,\nSole imperator and great general\nOf trotting 'paritors:--O my little heart:--\nAnd I to be a corporal of his field,\nAnd wear his colours like a tumbler's hoop!\nWhat, I! I love! I sue! I seek a wife!\nA woman, that is like a German clock,\nStill a-repairing, ever out of frame,\nAnd never going aright, being a watch,\nBut being watch'd that it may still go right!\nNay, to be perjured, which is worst of all;\nAnd, among three, to love the worst of all;\nA wightly wanton with a velvet brow,\nWith two pitch-balls stuck in her face for eyes;\nAy, and by heaven, one that will do the deed\nThough Argus were her eunuch and her guard:\nAnd I to sigh for her! to watch for her!\nTo pray for her! Go to; it is a plague\nThat Cupid will impose for my neglect\nOf his almighty dreadful little might.\nWell, I will love, write, sigh, pray, sue and groan:\nSome men must love my lady and some Joan.","sourceLine":"3.1.192","speaker":"BIRON","id":"lll:3.1:89"},{"kind":"stage","text":"Exit","id":"lll:3.1:90"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"3.1.224","speaker":"BIRON","id":"lll:3.1:91"}],"scene":1},{"id":"4.1","label":"Act 4 · SCENE I. The same.","act":4,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter the PRINCESS, and her train, a Forester, BOYET, ROSALINE, MARIA, and KATHARINE","id":"lll:4.1:1"},{"kind":"speech","text":"Was that the king, that spurred his horse so hard\nAgainst the steep uprising of the hill?","sourceLine":"4.1.1","speaker":"PRINCESS","id":"lll:4.1:2"},{"kind":"speech","text":"I know not; but I think it was not he.","sourceLine":"4.1.3","speaker":"BOYET","id":"lll:4.1:3"},{"kind":"speech","text":"Whoe'er a' was, a' show'd a mounting mind.\nWell, lords, to-day we shall have our dispatch:\nOn Saturday we will return to France.\nThen, forester, my friend, where is the bush\nThat we must stand and play the murderer in?","sourceLine":"4.1.4","speaker":"PRINCESS","id":"lll:4.1:4"},{"kind":"speech","text":"Hereby, upon the edge of yonder coppice;\nA stand where you may make the fairest shoot.","sourceLine":"4.1.9","speaker":"Forester","id":"lll:4.1:5"},{"kind":"speech","text":"I thank my beauty, I am fair that shoot,\nAnd thereupon thou speak'st the fairest shoot.","sourceLine":"4.1.11","speaker":"PRINCESS","id":"lll:4.1:6"},{"kind":"speech","text":"Pardon me, madam, for I meant not so.","sourceLine":"4.1.13","speaker":"Forester","id":"lll:4.1:7"},{"kind":"speech","text":"What, what? first praise me and again say no?\nO short-lived pride! Not fair? alack for woe!","sourceLine":"4.1.14","speaker":"PRINCESS","id":"lll:4.1:8"},{"kind":"speech","text":"Yes, madam, fair.","sourceLine":"4.1.16","speaker":"Forester","id":"lll:4.1:9"},{"kind":"speech","text":"Nay, never paint me now:\nWhere fair is not, praise cannot mend the brow.\nHere, good my glass, take this for telling true:\nFair payment for foul words is more than due.","sourceLine":"4.1.17","speaker":"PRINCESS","id":"lll:4.1:10"},{"kind":"speech","text":"Nothing but fair is that which you inherit.","sourceLine":"4.1.21","speaker":"Forester","id":"lll:4.1:11"},{"kind":"speech","text":"See see, my beauty will be saved by merit!\nO heresy in fair, fit for these days!\nA giving hand, though foul, shall have fair praise.\nBut come, the bow: now mercy goes to kill,\nAnd shooting well is then accounted ill.\nThus will I save my credit in the shoot:\nNot wounding, pity would not let me do't;\nIf wounding, then it was to show my skill,\nThat more for praise than purpose meant to kill.\nAnd out of question so it is sometimes,\nGlory grows guilty of detested crimes,\nWhen, for fame's sake, for praise, an outward part,\nWe bend to that the working of the heart;\nAs I for praise alone now seek to spill\nThe poor deer's blood, that my heart means no ill.","sourceLine":"4.1.22","speaker":"PRINCESS","id":"lll:4.1:12"},{"kind":"speech","text":"Do not curst wives hold that self-sovereignty\nOnly for praise sake, when they strive to be\nLords o'er their lords?","sourceLine":"4.1.37","speaker":"BOYET","id":"lll:4.1:13"},{"kind":"speech","text":"Only for praise: and praise we may afford\nTo any lady that subdues a lord.","sourceLine":"4.1.40","speaker":"PRINCESS","id":"lll:4.1:14"},{"kind":"speech","text":"Here comes a member of the commonwealth.","sourceLine":"4.1.42","speaker":"BOYET","id":"lll:4.1:15"},{"kind":"stage","text":"Enter COSTARD","id":"lll:4.1:16"},{"kind":"speech","text":"God dig-you-den all! Pray you, which is the head lady?","sourceLine":"4.1.43","speaker":"COSTARD","id":"lll:4.1:17"},{"kind":"speech","text":"Thou shalt know her, fellow, by the rest that have no heads.","sourceLine":"4.1.44","speaker":"PRINCESS","id":"lll:4.1:18"},{"kind":"speech","text":"Which is the greatest lady, the highest?","sourceLine":"4.1.45","speaker":"COSTARD","id":"lll:4.1:19"},{"kind":"speech","text":"The thickest and the tallest.","sourceLine":"4.1.46","speaker":"PRINCESS","id":"lll:4.1:20"},{"kind":"speech","text":"The thickest and the tallest! it is so; truth is truth.\nAn your waist, mistress, were as slender as my wit,\nOne o' these maids' girdles for your waist should be fit.\nAre not you the chief woman? you are the thickest here.","sourceLine":"4.1.47","speaker":"COSTARD","id":"lll:4.1:21"},{"kind":"speech","text":"What's your will, sir? what's your will?","sourceLine":"4.1.51","speaker":"PRINCESS","id":"lll:4.1:22"},{"kind":"speech","text":"I have a letter from Monsieur Biron to one Lady Rosaline.","sourceLine":"4.1.52","speaker":"COSTARD","id":"lll:4.1:23"},{"kind":"speech","text":"O, thy letter, thy letter! he's a good friend of mine:\nStand aside, good bearer. Boyet, you can carve;\nBreak up this capon.","sourceLine":"4.1.53","speaker":"PRINCESS","id":"lll:4.1:24"},{"kind":"speech","text":"I am bound to serve.\nThis letter is mistook, it importeth none here;\nIt is writ to Jaquenetta.","sourceLine":"4.1.56","speaker":"BOYET","id":"lll:4.1:25"},{"kind":"speech","text":"We will read it, I swear.\nBreak the neck of the wax, and every one give ear.","sourceLine":"4.1.59","speaker":"PRINCESS","id":"lll:4.1:26"},{"kind":"stage","text":"Reads","id":"lll:4.1:27"},{"kind":"speech","text":"'By heaven, that thou art fair, is most infallible;\ntrue, that thou art beauteous; truth itself, that\nthou art lovely. More fairer than fair, beautiful\nthan beauteous, truer than truth itself, have\ncommiseration on thy heroical vassal! The\nmagnanimous and most illustrate king Cophetua set\neye upon the pernicious and indubitate beggar\nZenelophon; and he it was that might rightly say,\nVeni, vidi, vici; which to annothanize in the\nvulgar,--O base and obscure vulgar!--videlicet, He\ncame, saw, and overcame: he came, one; saw two;\novercame, three. Who came? the king: why did he\ncome? to see: why did he see? to overcome: to\nwhom came he? to the beggar: what saw he? the\nbeggar: who overcame he? the beggar. The\nconclusion is victory: on whose side? the king's.\nThe captive is enriched: on whose side? the\nbeggar's. The catastrophe is a nuptial: on whose\nside? the king's: no, on both in one, or one in\nboth. I am the king; for so stands the comparison:\nthou the beggar; for so witnesseth thy lowliness.\nShall I command thy love? I may: shall I enforce\nthy love? I could: shall I entreat thy love? I\nwill. What shalt thou exchange for rags? robes;\nfor tittles? titles; for thyself? me. Thus,\nexpecting thy reply, I profane my lips on thy foot,\nmy eyes on thy picture. and my heart on thy every\npart. Thine, in the dearest design of industry,\nDON ADRIANO DE ARMADO.'\nThus dost thou hear the Nemean lion roar\n'Gainst thee, thou lamb, that standest as his prey.\nSubmissive fall his princely feet before,\nAnd he from forage will incline to play:\nBut if thou strive, poor soul, what art thou then?\nFood for his rage, repasture for his den.","sourceLine":"4.1.61","speaker":"BOYET","id":"lll:4.1:28"},{"kind":"speech","text":"What plume of feathers is he that indited this letter?\nWhat vane? what weathercock? did you ever hear better?","sourceLine":"4.1.96","speaker":"PRINCESS","id":"lll:4.1:29"},{"kind":"speech","text":"I am much deceived but I remember the style.","sourceLine":"4.1.98","speaker":"BOYET","id":"lll:4.1:30"},{"kind":"speech","text":"Else your memory is bad, going o'er it erewhile.","sourceLine":"4.1.99","speaker":"PRINCESS","id":"lll:4.1:31"},{"kind":"speech","text":"This Armado is a Spaniard, that keeps here in court;\nA phantasime, a Monarcho, and one that makes sport\nTo the prince and his bookmates.","sourceLine":"4.1.100","speaker":"BOYET","id":"lll:4.1:32"},{"kind":"speech","text":"Thou fellow, a word:\nWho gave thee this letter?","sourceLine":"4.1.103","speaker":"PRINCESS","id":"lll:4.1:33"},{"kind":"speech","text":"I told you; my lord.","sourceLine":"4.1.105","speaker":"COSTARD","id":"lll:4.1:34"},{"kind":"speech","text":"To whom shouldst thou give it?","sourceLine":"4.1.106","speaker":"PRINCESS","id":"lll:4.1:35"},{"kind":"speech","text":"From my lord to my lady.","sourceLine":"4.1.107","speaker":"COSTARD","id":"lll:4.1:36"},{"kind":"speech","text":"From which lord to which lady?","sourceLine":"4.1.108","speaker":"PRINCESS","id":"lll:4.1:37"},{"kind":"speech","text":"From my lord Biron, a good master of mine,\nTo a lady of France that he call'd Rosaline.","sourceLine":"4.1.109","speaker":"COSTARD","id":"lll:4.1:38"},{"kind":"speech","text":"Thou hast mistaken his letter. Come, lords, away.","sourceLine":"4.1.111","speaker":"PRINCESS","id":"lll:4.1:39"},{"kind":"stage","text":"To ROSALINE","id":"lll:4.1:40"},{"kind":"speech","text":"Here, sweet, put up this: 'twill be thine another day.","sourceLine":"4.1.112","speaker":"PRINCESS","id":"lll:4.1:41"},{"kind":"stage","text":"Exeunt PRINCESS and train","id":"lll:4.1:42"},{"kind":"speech","text":"Who is the suitor? who is the suitor?","sourceLine":"4.1.113","speaker":"BOYET","id":"lll:4.1:43"},{"kind":"speech","text":"Shall I teach you to know?","sourceLine":"4.1.114","speaker":"ROSALINE","id":"lll:4.1:44"},{"kind":"speech","text":"Ay, my continent of beauty.","sourceLine":"4.1.115","speaker":"BOYET","id":"lll:4.1:45"},{"kind":"speech","text":"Why, she that bears the bow.\nFinely put off!","sourceLine":"4.1.116","speaker":"ROSALINE","id":"lll:4.1:46"},{"kind":"speech","text":"My lady goes to kill horns; but, if thou marry,\nHang me by the neck, if horns that year miscarry.\nFinely put on!","sourceLine":"4.1.118","speaker":"BOYET","id":"lll:4.1:47"},{"kind":"speech","text":"Well, then, I am the shooter.","sourceLine":"4.1.121","speaker":"ROSALINE","id":"lll:4.1:48"},{"kind":"speech","text":"And who is your deer?","sourceLine":"4.1.122","speaker":"BOYET","id":"lll:4.1:49"},{"kind":"speech","text":"If we choose by the horns, yourself come not near.\nFinely put on, indeed!","sourceLine":"4.1.123","speaker":"ROSALINE","id":"lll:4.1:50"},{"kind":"speech","text":"You still wrangle with her, Boyet, and she strikes\nat the brow.","sourceLine":"4.1.125","speaker":"MARIA","id":"lll:4.1:51"},{"kind":"speech","text":"But she herself is hit lower: have I hit her now?","sourceLine":"4.1.127","speaker":"BOYET","id":"lll:4.1:52"},{"kind":"speech","text":"Shall I come upon thee with an old saying, that was\na man when King Pepin of France was a little boy, as\ntouching the hit it?","sourceLine":"4.1.128","speaker":"ROSALINE","id":"lll:4.1:53"},{"kind":"speech","text":"So I may answer thee with one as old, that was a\nwoman when Queen Guinover of Britain was a little\nwench, as touching the hit it.","sourceLine":"4.1.131","speaker":"BOYET","id":"lll:4.1:54"},{"kind":"speech","text":"Thou canst not hit it, hit it, hit it,\nThou canst not hit it, my good man.","sourceLine":"4.1.134","speaker":"ROSALINE","id":"lll:4.1:55"},{"kind":"speech","text":"An I cannot, cannot, cannot,\nAn I cannot, another can.","sourceLine":"4.1.136","speaker":"BOYET","id":"lll:4.1:56"},{"kind":"stage","text":"Exeunt ROSALINE and KATHARINE","id":"lll:4.1:57"},{"kind":"speech","text":"By my troth, most pleasant: how both did fit it!","sourceLine":"4.1.138","speaker":"COSTARD","id":"lll:4.1:58"},{"kind":"speech","text":"A mark marvellous well shot, for they both did hit it.","sourceLine":"4.1.139","speaker":"MARIA","id":"lll:4.1:59"},{"kind":"speech","text":"A mark! O, mark but that mark! A mark, says my lady!\nLet the mark have a prick in't, to mete at, if it may be.","sourceLine":"4.1.140","speaker":"BOYET","id":"lll:4.1:60"},{"kind":"speech","text":"Wide o' the bow hand! i' faith, your hand is out.","sourceLine":"4.1.142","speaker":"MARIA","id":"lll:4.1:61"},{"kind":"speech","text":"Indeed, a' must shoot nearer, or he'll ne'er hit the clout.","sourceLine":"4.1.143","speaker":"COSTARD","id":"lll:4.1:62"},{"kind":"speech","text":"An if my hand be out, then belike your hand is in.","sourceLine":"4.1.144","speaker":"BOYET","id":"lll:4.1:63"},{"kind":"speech","text":"Then will she get the upshoot by cleaving the pin.","sourceLine":"4.1.145","speaker":"COSTARD","id":"lll:4.1:64"},{"kind":"speech","text":"Come, come, you talk greasily; your lips grow foul.","sourceLine":"4.1.146","speaker":"MARIA","id":"lll:4.1:65"},{"kind":"speech","text":"She's too hard for you at pricks, sir: challenge her to bowl.","sourceLine":"4.1.147","speaker":"COSTARD","id":"lll:4.1:66"},{"kind":"speech","text":"I fear too much rubbing. Good night, my good owl.","sourceLine":"4.1.148","speaker":"BOYET","id":"lll:4.1:67"},{"kind":"stage","text":"Exeunt BOYET and MARIA","id":"lll:4.1:68"},{"kind":"speech","text":"By my soul, a swain! a most simple clown!\nLord, Lord, how the ladies and I have put him down!\nO' my troth, most sweet jests! most incony\nvulgar wit!\nWhen it comes so smoothly off, so obscenely, as it\nwere, so fit.\nArmado o' th' one side,--O, a most dainty man!\nTo see him walk before a lady and to bear her fan!\nTo see him kiss his hand! and how most sweetly a'\nwill swear!\nAnd his page o' t' other side, that handful of wit!\nAh, heavens, it is a most pathetical nit!\nSola, sola!","sourceLine":"4.1.149","speaker":"COSTARD","id":"lll:4.1:69"},{"kind":"stage","text":"Shout within","id":"lll:4.1:70"},{"kind":"stage","text":"Exit COSTARD, running","id":"lll:4.1:71"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"4.1.162","speaker":"COSTARD","id":"lll:4.1:72"}],"scene":1},{"id":"4.2","label":"Act 4 · SCENE II. The same.","act":4,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter HOLOFERNES, SIR NATHANIEL, and DULL","id":"lll:4.2:1"},{"kind":"speech","text":"Very reverend sport, truly; and done in the testimony\nof a good conscience.","sourceLine":"4.2.1","speaker":"SIR NATHANIEL","id":"lll:4.2:2"},{"kind":"speech","text":"The deer was, as you know, sanguis, in blood; ripe\nas the pomewater, who now hangeth like a jewel in\nthe ear of caelo, the sky, the welkin, the heaven;\nand anon falleth like a crab on the face of terra,\nthe soil, the land, the earth.","sourceLine":"4.2.3","speaker":"HOLOFERNES","id":"lll:4.2:3"},{"kind":"speech","text":"Truly, Master Holofernes, the epithets are sweetly\nvaried, like a scholar at the least: but, sir, I\nassure ye, it was a buck of the first head.","sourceLine":"4.2.8","speaker":"SIR NATHANIEL","id":"lll:4.2:4"},{"kind":"speech","text":"Sir Nathaniel, haud credo.","sourceLine":"4.2.11","speaker":"HOLOFERNES","id":"lll:4.2:5"},{"kind":"speech","text":"'Twas not a haud credo; 'twas a pricket.","sourceLine":"4.2.12","speaker":"DULL","id":"lll:4.2:6"},{"kind":"speech","text":"Most barbarous intimation! yet a kind of\ninsinuation, as it were, in via, in way, of\nexplication; facere, as it were, replication, or\nrather, ostentare, to show, as it were, his\ninclination, after his undressed, unpolished,\nuneducated, unpruned, untrained, or rather,\nunlettered, or ratherest, unconfirmed fashion, to\ninsert again my haud credo for a deer.","sourceLine":"4.2.13","speaker":"HOLOFERNES","id":"lll:4.2:7"},{"kind":"speech","text":"I said the deer was not a haud credo; twas a pricket.","sourceLine":"4.2.21","speaker":"DULL","id":"lll:4.2:8"},{"kind":"speech","text":"Twice-sod simplicity, his coctus!\nO thou monster Ignorance, how deformed dost thou look!","sourceLine":"4.2.22","speaker":"HOLOFERNES","id":"lll:4.2:9"},{"kind":"speech","text":"Sir, he hath never fed of the dainties that are bred\nin a book; he hath not eat paper, as it were; he\nhath not drunk ink: his intellect is not\nreplenished; he is only an animal, only sensible in\nthe duller parts:\nAnd such barren plants are set before us, that we\nthankful should be,\nWhich we of taste and feeling are, for those parts that\ndo fructify in us more than he.\nFor as it would ill become me to be vain, indiscreet, or a fool,\nSo were there a patch set on learning, to see him in a school:\nBut omne bene, say I; being of an old father's mind,\nMany can brook the weather that love not the wind.","sourceLine":"4.2.24","speaker":"SIR NATHANIEL","id":"lll:4.2:10"},{"kind":"speech","text":"You two are book-men: can you tell me by your wit\nWhat was a month old at Cain's birth, that's not five\nweeks old as yet?","sourceLine":"4.2.37","speaker":"DULL","id":"lll:4.2:11"},{"kind":"speech","text":"Dictynna, goodman Dull; Dictynna, goodman Dull.","sourceLine":"4.2.40","speaker":"HOLOFERNES","id":"lll:4.2:12"},{"kind":"speech","text":"What is Dictynna?","sourceLine":"4.2.41","speaker":"DULL","id":"lll:4.2:13"},{"kind":"speech","text":"A title to Phoebe, to Luna, to the moon.","sourceLine":"4.2.42","speaker":"SIR NATHANIEL","id":"lll:4.2:14"},{"kind":"speech","text":"The moon was a month old when Adam was no more,\nAnd raught not to five weeks when he came to\nfive-score.\nThe allusion holds in the exchange.","sourceLine":"4.2.43","speaker":"HOLOFERNES","id":"lll:4.2:15"},{"kind":"speech","text":"'Tis true indeed; the collusion holds in the exchange.","sourceLine":"4.2.47","speaker":"DULL","id":"lll:4.2:16"},{"kind":"speech","text":"God comfort thy capacity! I say, the allusion holds\nin the exchange.","sourceLine":"4.2.48","speaker":"HOLOFERNES","id":"lll:4.2:17"},{"kind":"speech","text":"And I say, the pollusion holds in the exchange; for\nthe moon is never but a month old: and I say beside\nthat, 'twas a pricket that the princess killed.","sourceLine":"4.2.50","speaker":"DULL","id":"lll:4.2:18"},{"kind":"speech","text":"Sir Nathaniel, will you hear an extemporal epitaph\non the death of the deer? And, to humour the\nignorant, call I the deer the princess killed a pricket.","sourceLine":"4.2.53","speaker":"HOLOFERNES","id":"lll:4.2:19"},{"kind":"speech","text":"Perge, good Master Holofernes, perge; so it shall\nplease you to abrogate scurrility.","sourceLine":"4.2.56","speaker":"SIR NATHANIEL","id":"lll:4.2:20"},{"kind":"speech","text":"I will something affect the letter, for it argues facility.\nThe preyful princess pierced and prick'd a pretty\npleasing pricket;\nSome say a sore; but not a sore, till now made\nsore with shooting.\nThe dogs did yell: put L to sore, then sorel jumps\nfrom thicket;\nOr pricket sore, or else sorel; the people fall a-hooting.\nIf sore be sore, then L to sore makes fifty sores\none sorel.\nOf one sore I an hundred make by adding but one more L.","sourceLine":"4.2.58","speaker":"HOLOFERNES","id":"lll:4.2:21"},{"kind":"speech","text":"A rare talent!","sourceLine":"4.2.69","speaker":"SIR NATHANIEL","id":"lll:4.2:22"},{"kind":"speech","text":"[Aside] If a talent be a claw, look how he claws\nhim with a talent.","sourceLine":"4.2.70","speaker":"DULL","id":"lll:4.2:23"},{"kind":"speech","text":"This is a gift that I have, simple, simple; a\nfoolish extravagant spirit, full of forms, figures,\nshapes, objects, ideas, apprehensions, motions,\nrevolutions: these are begot in the ventricle of\nmemory, nourished in the womb of pia mater, and\ndelivered upon the mellowing of occasion. But the\ngift is good in those in whom it is acute, and I am\nthankful for it.","sourceLine":"4.2.72","speaker":"HOLOFERNES","id":"lll:4.2:24"},{"kind":"speech","text":"Sir, I praise the Lord for you; and so may my\nparishioners; for their sons are well tutored by\nyou, and their daughters profit very greatly under\nyou: you are a good member of the commonwealth.","sourceLine":"4.2.80","speaker":"SIR NATHANIEL","id":"lll:4.2:25"},{"kind":"speech","text":"Mehercle, if their sons be ingenuous, they shall\nwant no instruction; if their daughters be capable,\nI will put it to them: but vir sapit qui pauca\nloquitur; a soul feminine saluteth us.","sourceLine":"4.2.84","speaker":"HOLOFERNES","id":"lll:4.2:26"},{"kind":"stage","text":"Enter JAQUENETTA and COSTARD","id":"lll:4.2:27"},{"kind":"speech","text":"God give you good morrow, master Parson.","sourceLine":"4.2.88","speaker":"JAQUENETTA","id":"lll:4.2:28"},{"kind":"speech","text":"Master Parson, quasi pers-on. An if one should be\npierced, which is the one?","sourceLine":"4.2.89","speaker":"HOLOFERNES","id":"lll:4.2:29"},{"kind":"speech","text":"Marry, master schoolmaster, he that is likest to a hogshead.","sourceLine":"4.2.91","speaker":"COSTARD","id":"lll:4.2:30"},{"kind":"speech","text":"Piercing a hogshead! a good lustre of conceit in a\ntuft of earth; fire enough for a flint, pearl enough\nfor a swine: 'tis pretty; it is well.","sourceLine":"4.2.92","speaker":"HOLOFERNES","id":"lll:4.2:31"},{"kind":"speech","text":"Good master Parson, be so good as read me this\nletter: it was given me by Costard, and sent me\nfrom Don Armado: I beseech you, read it.","sourceLine":"4.2.95","speaker":"JAQUENETTA","id":"lll:4.2:32"},{"kind":"speech","text":"Fauste, precor gelida quando pecus omne sub umbra\nRuminat,--and so forth. Ah, good old Mantuan! I\nmay speak of thee as the traveller doth of Venice;\nVenetia, Venetia,\nChi non ti vede non ti pretia.\nOld Mantuan, old Mantuan! who understandeth thee\nnot, loves thee not. Ut, re, sol, la, mi, fa.\nUnder pardon, sir, what are the contents? or rather,\nas Horace says in his--What, my soul, verses?","sourceLine":"4.2.98","speaker":"HOLOFERNES","id":"lll:4.2:33"},{"kind":"speech","text":"Ay, sir, and very learned.","sourceLine":"4.2.107","speaker":"SIR NATHANIEL","id":"lll:4.2:34"},{"kind":"speech","text":"Let me hear a staff, a stanze, a verse; lege, domine.","sourceLine":"4.2.108","speaker":"HOLOFERNES","id":"lll:4.2:35"},{"kind":"speech","text":"[Reads]\nIf love make me forsworn, how shall I swear to love?\nAh, never faith could hold, if not to beauty vow'd!\nThough to myself forsworn, to thee I'll faithful prove:\nThose thoughts to me were oaks, to thee like\nosiers bow'd.\nStudy his bias leaves and makes his book thine eyes,\nWhere all those pleasures live that art would\ncomprehend:\nIf knowledge be the mark, to know thee shall suffice;\nWell learned is that tongue that well can thee commend,\nAll ignorant that soul that sees thee without wonder;\nWhich is to me some praise that I thy parts admire:\nThy eye Jove's lightning bears, thy voice his dreadful thunder,\nWhich not to anger bent, is music and sweet fire.\nCelestial as thou art, O, pardon, love, this wrong,\nThat sings heaven's praise with such an earthly tongue.","sourceLine":"4.2.109","speaker":"SIR NATHANIEL","id":"lll:4.2:36"},{"kind":"speech","text":"You find not the apostraphas, and so miss the\naccent: let me supervise the canzonet. Here are\nonly numbers ratified; but, for the elegancy,\nfacility, and golden cadence of poesy, caret.\nOvidius Naso was the man: and why, indeed, Naso,\nbut for smelling out the odouriferous flowers of\nfancy, the jerks of invention? Imitari is nothing:\nso doth the hound his master, the ape his keeper,\nthe tired horse his rider. But, damosella virgin,\nwas this directed to you?","sourceLine":"4.2.126","speaker":"HOLOFERNES","id":"lll:4.2:37"},{"kind":"speech","text":"Ay, sir, from one Monsieur Biron, one of the strange\nqueen's lords.","sourceLine":"4.2.136","speaker":"JAQUENETTA","id":"lll:4.2:38"},{"kind":"speech","text":"I will overglance the superscript: 'To the\nsnow-white hand of the most beauteous Lady\nRosaline.' I will look again on the intellect of\nthe letter, for the nomination of the party writing\nto the person written unto: 'Your ladyship's in all\ndesired employment, BIRON.' Sir Nathaniel, this\nBiron is one of the votaries with the king; and here\nhe hath framed a letter to a sequent of the stranger\nqueen's, which accidentally, or by the way of\nprogression, hath miscarried. Trip and go, my\nsweet; deliver this paper into the royal hand of the\nking: it may concern much. Stay not thy\ncompliment; I forgive thy duty; adieu.","sourceLine":"4.2.138","speaker":"HOLOFERNES","id":"lll:4.2:39"},{"kind":"speech","text":"Good Costard, go with me. Sir, God save your life!","sourceLine":"4.2.151","speaker":"JAQUENETTA","id":"lll:4.2:40"},{"kind":"speech","text":"Have with thee, my girl.","sourceLine":"4.2.152","speaker":"COSTARD","id":"lll:4.2:41"},{"kind":"stage","text":"Exeunt COSTARD and JAQUENETTA","id":"lll:4.2:42"},{"kind":"speech","text":"Sir, you have done this in the fear of God, very\nreligiously; and, as a certain father saith,--","sourceLine":"4.2.153","speaker":"SIR NATHANIEL","id":"lll:4.2:43"},{"kind":"speech","text":"Sir tell me not of the father; I do fear colourable\ncolours. But to return to the verses: did they\nplease you, Sir Nathaniel?","sourceLine":"4.2.155","speaker":"HOLOFERNES","id":"lll:4.2:44"},{"kind":"speech","text":"Marvellous well for the pen.","sourceLine":"4.2.158","speaker":"SIR NATHANIEL","id":"lll:4.2:45"},{"kind":"speech","text":"I do dine to-day at the father's of a certain pupil\nof mine; where, if, before repast, it shall please\nyou to gratify the table with a grace, I will, on my\nprivilege I have with the parents of the foresaid\nchild or pupil, undertake your ben venuto; where I\nwill prove those verses to be very unlearned,\nneither savouring of poetry, wit, nor invention: I\nbeseech your society.","sourceLine":"4.2.159","speaker":"HOLOFERNES","id":"lll:4.2:46"},{"kind":"speech","text":"And thank you too; for society, saith the text, is\nthe happiness of life.","sourceLine":"4.2.167","speaker":"SIR NATHANIEL","id":"lll:4.2:47"},{"kind":"speech","text":"And, certes, the text most infallibly concludes it.","sourceLine":"4.2.169","speaker":"HOLOFERNES","id":"lll:4.2:48"},{"kind":"stage","text":"To DULL","id":"lll:4.2:49"},{"kind":"speech","text":"Sir, I do invite you too; you shall not\nsay me nay: pauca verba. Away! the gentles are at\ntheir game, and we will to our recreation.","sourceLine":"4.2.170","speaker":"HOLOFERNES","id":"lll:4.2:50"},{"kind":"stage","text":"Exeunt","id":"lll:4.2:51"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"4.2.173","speaker":"HOLOFERNES","id":"lll:4.2:52"}],"scene":2},{"id":"4.3","label":"Act 4 · SCENE III. The same.","act":4,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter BIRON, with a paper","id":"lll:4.3:1"},{"kind":"speech","text":"The king he is hunting the deer; I am coursing\nmyself: they have pitched a toil; I am toiling in\na pitch,--pitch that defiles: defile! a foul\nword. Well, set thee down, sorrow! for so they say\nthe fool said, and so say I, and I the fool: well\nproved, wit! By the Lord, this love is as mad as\nAjax: it kills sheep; it kills me, I a sheep:\nwell proved again o' my side! I will not love: if\nI do, hang me; i' faith, I will not. O, but her\neye,--by this light, but for her eye, I would not\nlove her; yes, for her two eyes. Well, I do nothing\nin the world but lie, and lie in my throat. By\nheaven, I do love: and it hath taught me to rhyme\nand to be melancholy; and here is part of my rhyme,\nand here my melancholy. Well, she hath one o' my\nsonnets already: the clown bore it, the fool sent\nit, and the lady hath it: sweet clown, sweeter\nfool, sweetest lady! By the world, I would not care\na pin, if the other three were in. Here comes one\nwith a paper: God give him grace to groan!","sourceLine":"4.3.1","speaker":"BIRON","id":"lll:4.3:2"},{"kind":"stage","text":"Stands aside","id":"lll:4.3:3"},{"kind":"stage","text":"Enter FERDINAND, with a paper","id":"lll:4.3:4"},{"kind":"speech","text":"Ay me!","sourceLine":"4.3.21","speaker":"FERDINAND","id":"lll:4.3:5"},{"kind":"speech","text":"[Aside] Shot, by heaven! Proceed, sweet Cupid:\nthou hast thumped him with thy bird-bolt under the\nleft pap. In faith, secrets!","sourceLine":"4.3.22","speaker":"BIRON","id":"lll:4.3:6"},{"kind":"speech","text":"[Reads]\nSo sweet a kiss the golden sun gives not\nTo those fresh morning drops upon the rose,\nAs thy eye-beams, when their fresh rays have smote\nThe night of dew that on my cheeks down flows:\nNor shines the silver moon one half so bright\nThrough the transparent bosom of the deep,\nAs doth thy face through tears of mine give light;\nThou shinest in every tear that I do weep:\nNo drop but as a coach doth carry thee;\nSo ridest thou triumphing in my woe.\nDo but behold the tears that swell in me,\nAnd they thy glory through my grief will show:\nBut do not love thyself; then thou wilt keep\nMy tears for glasses, and still make me weep.\nO queen of queens! how far dost thou excel,\nNo thought can think, nor tongue of mortal tell.\nHow shall she know my griefs? I'll drop the paper:\nSweet leaves, shade folly. Who is he comes here?","sourceLine":"4.3.25","speaker":"FERDINAND","id":"lll:4.3:7"},{"kind":"stage","text":"Steps aside","id":"lll:4.3:8"},{"kind":"speech","text":"What, Longaville! and reading! listen, ear.","sourceLine":"4.3.44","speaker":"FERDINAND","id":"lll:4.3:9"},{"kind":"speech","text":"Now, in thy likeness, one more fool appear!","sourceLine":"4.3.45","speaker":"BIRON","id":"lll:4.3:10"},{"kind":"stage","text":"Enter LONGAVILLE, with a paper","id":"lll:4.3:11"},{"kind":"speech","text":"Ay me, I am forsworn!","sourceLine":"4.3.46","speaker":"LONGAVILLE","id":"lll:4.3:12"},{"kind":"speech","text":"Why, he comes in like a perjure, wearing papers.","sourceLine":"4.3.47","speaker":"BIRON","id":"lll:4.3:13"},{"kind":"speech","text":"In love, I hope: sweet fellowship in shame!","sourceLine":"4.3.48","speaker":"FERDINAND","id":"lll:4.3:14"},{"kind":"speech","text":"One drunkard loves another of the name.","sourceLine":"4.3.49","speaker":"BIRON","id":"lll:4.3:15"},{"kind":"speech","text":"Am I the first that have been perjured so?","sourceLine":"4.3.50","speaker":"LONGAVILLE","id":"lll:4.3:16"},{"kind":"speech","text":"I could put thee in comfort. Not by two that I know:\nThou makest the triumviry, the corner-cap of society,\nThe shape of Love's Tyburn that hangs up simplicity.","sourceLine":"4.3.51","speaker":"BIRON","id":"lll:4.3:17"},{"kind":"speech","text":"I fear these stubborn lines lack power to move:\nO sweet Maria, empress of my love!\nThese numbers will I tear, and write in prose.","sourceLine":"4.3.54","speaker":"LONGAVILLE","id":"lll:4.3:18"},{"kind":"speech","text":"O, rhymes are guards on wanton Cupid's hose:\nDisfigure not his slop.","sourceLine":"4.3.57","speaker":"BIRON","id":"lll:4.3:19"},{"kind":"speech","text":"This same shall go.","sourceLine":"4.3.59","speaker":"LONGAVILLE","id":"lll:4.3:20"},{"kind":"stage","text":"Reads","id":"lll:4.3:21"},{"kind":"speech","text":"Did not the heavenly rhetoric of thine eye,\n'Gainst whom the world cannot hold argument,\nPersuade my heart to this false perjury?\nVows for thee broke deserve not punishment.\nA woman I forswore; but I will prove,\nThou being a goddess, I forswore not thee:\nMy vow was earthly, thou a heavenly love;\nThy grace being gain'd cures all disgrace in me.\nVows are but breath, and breath a vapour is:\nThen thou, fair sun, which on my earth dost shine,\nExhalest this vapour-vow; in thee it is:\nIf broken then, it is no fault of mine:\nIf by me broke, what fool is not so wise\nTo lose an oath to win a paradise?","sourceLine":"4.3.60","speaker":"LONGAVILLE","id":"lll:4.3:22"},{"kind":"speech","text":"This is the liver-vein, which makes flesh a deity,\nA green goose a goddess: pure, pure idolatry.\nGod amend us, God amend! we are much out o' the way.","sourceLine":"4.3.74","speaker":"BIRON","id":"lll:4.3:23"},{"kind":"speech","text":"By whom shall I send this?--Company! stay.","sourceLine":"4.3.77","speaker":"LONGAVILLE","id":"lll:4.3:24"},{"kind":"stage","text":"Steps aside","id":"lll:4.3:25"},{"kind":"speech","text":"All hid, all hid; an old infant play.\nLike a demigod here sit I in the sky.\nAnd wretched fools' secrets heedfully o'ereye.\nMore sacks to the mill! O heavens, I have my wish!","sourceLine":"4.3.78","speaker":"BIRON","id":"lll:4.3:26"},{"kind":"stage","text":"Enter DUMAIN, with a paper","id":"lll:4.3:27"},{"kind":"speech","text":"Dumain transform'd! four woodcocks in a dish!","sourceLine":"4.3.82","speaker":"BIRON","id":"lll:4.3:28"},{"kind":"speech","text":"O most divine Kate!","sourceLine":"4.3.83","speaker":"DUMAIN","id":"lll:4.3:29"},{"kind":"speech","text":"O most profane coxcomb!","sourceLine":"4.3.84","speaker":"BIRON","id":"lll:4.3:30"},{"kind":"speech","text":"By heaven, the wonder in a mortal eye!","sourceLine":"4.3.85","speaker":"DUMAIN","id":"lll:4.3:31"},{"kind":"speech","text":"By earth, she is not, corporal, there you lie.","sourceLine":"4.3.86","speaker":"BIRON","id":"lll:4.3:32"},{"kind":"speech","text":"Her amber hair for foul hath amber quoted.","sourceLine":"4.3.87","speaker":"DUMAIN","id":"lll:4.3:33"},{"kind":"speech","text":"An amber-colour'd raven was well noted.","sourceLine":"4.3.88","speaker":"BIRON","id":"lll:4.3:34"},{"kind":"speech","text":"As upright as the cedar.","sourceLine":"4.3.89","speaker":"DUMAIN","id":"lll:4.3:35"},{"kind":"speech","text":"Stoop, I say;\nHer shoulder is with child.","sourceLine":"4.3.90","speaker":"BIRON","id":"lll:4.3:36"},{"kind":"speech","text":"As fair as day.","sourceLine":"4.3.92","speaker":"DUMAIN","id":"lll:4.3:37"},{"kind":"speech","text":"Ay, as some days; but then no sun must shine.","sourceLine":"4.3.93","speaker":"BIRON","id":"lll:4.3:38"},{"kind":"speech","text":"O that I had my wish!","sourceLine":"4.3.94","speaker":"DUMAIN","id":"lll:4.3:39"},{"kind":"speech","text":"And I had mine!","sourceLine":"4.3.95","speaker":"LONGAVILLE","id":"lll:4.3:40"},{"kind":"speech","text":"And I mine too, good Lord!","sourceLine":"4.3.96","speaker":"FERDINAND","id":"lll:4.3:41"},{"kind":"speech","text":"Amen, so I had mine: is not that a good word?","sourceLine":"4.3.97","speaker":"BIRON","id":"lll:4.3:42"},{"kind":"speech","text":"I would forget her; but a fever she\nReigns in my blood and will remember'd be.","sourceLine":"4.3.98","speaker":"DUMAIN","id":"lll:4.3:43"},{"kind":"speech","text":"A fever in your blood! why, then incision\nWould let her out in saucers: sweet misprision!","sourceLine":"4.3.100","speaker":"BIRON","id":"lll:4.3:44"},{"kind":"speech","text":"Once more I'll read the ode that I have writ.","sourceLine":"4.3.102","speaker":"DUMAIN","id":"lll:4.3:45"},{"kind":"speech","text":"Once more I'll mark how love can vary wit.","sourceLine":"4.3.103","speaker":"BIRON","id":"lll:4.3:46"},{"kind":"speech","text":"[Reads]\nOn a day--alack the day!--\nLove, whose month is ever May,\nSpied a blossom passing fair\nPlaying in the wanton air:\nThrough the velvet leaves the wind,\nAll unseen, can passage find;\nThat the lover, sick to death,\nWish himself the heaven's breath.\nAir, quoth he, thy cheeks may blow;\nAir, would I might triumph so!\nBut, alack, my hand is sworn\nNe'er to pluck thee from thy thorn;\nVow, alack, for youth unmeet,\nYouth so apt to pluck a sweet!\nDo not call it sin in me,\nThat I am forsworn for thee;\nThou for whom Jove would swear\nJuno but an Ethiope were;\nAnd deny himself for Jove,\nTurning mortal for thy love.\nThis will I send, and something else more plain,\nThat shall express my true love's fasting pain.\nO, would the king, Biron, and Longaville,\nWere lovers too! Ill, to example ill,\nWould from my forehead wipe a perjured note;\nFor none offend where all alike do dote.","sourceLine":"4.3.104","speaker":"DUMAIN","id":"lll:4.3:47"},{"kind":"speech","text":"[Advancing] Dumain, thy love is far from charity.\nYou may look pale, but I should blush, I know,\nTo be o'erheard and taken napping so.","sourceLine":"4.3.131","speaker":"LONGAVILLE","id":"lll:4.3:48"},{"kind":"speech","text":"[Advancing] Come, sir, you blush; as his your case is such;\nYou chide at him, offending twice as much;\nYou do not love Maria; Longaville\nDid never sonnet for her sake compile,\nNor never lay his wreathed arms athwart\nHis loving bosom to keep down his heart.\nI have been closely shrouded in this bush\nAnd mark'd you both and for you both did blush:\nI heard your guilty rhymes, observed your fashion,\nSaw sighs reek from you, noted well your passion:\nAy me! says one; O Jove! the other cries;\nOne, her hairs were gold, crystal the other's eyes:","sourceLine":"4.3.134","speaker":"FERDINAND","id":"lll:4.3:49"},{"kind":"stage","text":"To LONGAVILLE","id":"lll:4.3:50"},{"kind":"speech","text":"You would for paradise break faith, and troth;","sourceLine":"4.3.146","speaker":"FERDINAND","id":"lll:4.3:51"},{"kind":"stage","text":"To DUMAIN","id":"lll:4.3:52"},{"kind":"speech","text":"And Jove, for your love, would infringe an oath.\nWhat will Biron say when that he shall hear\nFaith so infringed, which such zeal did swear?\nHow will he scorn! how will he spend his wit!\nHow will he triumph, leap and laugh at it!\nFor all the wealth that ever I did see,\nI would not have him know so much by me.","sourceLine":"4.3.147","speaker":"FERDINAND","id":"lll:4.3:53"},{"kind":"speech","text":"Now step I forth to whip hypocrisy.","sourceLine":"4.3.154","speaker":"BIRON","id":"lll:4.3:54"},{"kind":"stage","text":"Advancing","id":"lll:4.3:55"},{"kind":"speech","text":"Ah, good my liege, I pray thee, pardon me!\nGood heart, what grace hast thou, thus to reprove\nThese worms for loving, that art most in love?\nYour eyes do make no coaches; in your tears\nThere is no certain princess that appears;\nYou'll not be perjured, 'tis a hateful thing;\nTush, none but minstrels like of sonneting!\nBut are you not ashamed? nay, are you not,\nAll three of you, to be thus much o'ershot?\nYou found his mote; the king your mote did see;\nBut I a beam do find in each of three.\nO, what a scene of foolery have I seen,\nOf sighs, of groans, of sorrow and of teen!\nO me, with what strict patience have I sat,\nTo see a king transformed to a gnat!\nTo see great Hercules whipping a gig,\nAnd profound Solomon to tune a jig,\nAnd Nestor play at push-pin with the boys,\nAnd critic Timon laugh at idle toys!\nWhere lies thy grief, O, tell me, good Dumain?\nAnd gentle Longaville, where lies thy pain?\nAnd where my liege's? all about the breast:\nA caudle, ho!","sourceLine":"4.3.155","speaker":"BIRON","id":"lll:4.3:56"},{"kind":"speech","text":"Too bitter is thy jest.\nAre we betray'd thus to thy over-view?","sourceLine":"4.3.178","speaker":"FERDINAND","id":"lll:4.3:57"},{"kind":"speech","text":"Not you to me, but I betray'd by you:\nI, that am honest; I, that hold it sin\nTo break the vow I am engaged in;\nI am betray'd, by keeping company\nWith men like men of inconstancy.\nWhen shall you see me write a thing in rhyme?\nOr groan for love? or spend a minute's time\nIn pruning me? When shall you hear that I\nWill praise a hand, a foot, a face, an eye,\nA gait, a state, a brow, a breast, a waist,\nA leg, a limb?","sourceLine":"4.3.180","speaker":"BIRON","id":"lll:4.3:58"},{"kind":"speech","text":"Soft! whither away so fast?\nA true man or a thief that gallops so?","sourceLine":"4.3.191","speaker":"FERDINAND","id":"lll:4.3:59"},{"kind":"speech","text":"I post from love: good lover, let me go.","sourceLine":"4.3.193","speaker":"BIRON","id":"lll:4.3:60"},{"kind":"stage","text":"Enter JAQUENETTA and COSTARD","id":"lll:4.3:61"},{"kind":"speech","text":"God bless the king!","sourceLine":"4.3.194","speaker":"JAQUENETTA","id":"lll:4.3:62"},{"kind":"speech","text":"What present hast thou there?","sourceLine":"4.3.195","speaker":"FERDINAND","id":"lll:4.3:63"},{"kind":"speech","text":"Some certain treason.","sourceLine":"4.3.196","speaker":"COSTARD","id":"lll:4.3:64"},{"kind":"speech","text":"What makes treason here?","sourceLine":"4.3.197","speaker":"FERDINAND","id":"lll:4.3:65"},{"kind":"speech","text":"Nay, it makes nothing, sir.","sourceLine":"4.3.198","speaker":"COSTARD","id":"lll:4.3:66"},{"kind":"speech","text":"If it mar nothing neither,\nThe treason and you go in peace away together.","sourceLine":"4.3.199","speaker":"FERDINAND","id":"lll:4.3:67"},{"kind":"speech","text":"I beseech your grace, let this letter be read:\nOur parson misdoubts it; 'twas treason, he said.","sourceLine":"4.3.201","speaker":"JAQUENETTA","id":"lll:4.3:68"},{"kind":"speech","text":"Biron, read it over.","sourceLine":"4.3.203","speaker":"FERDINAND","id":"lll:4.3:69"},{"kind":"stage","text":"Giving him the paper","id":"lll:4.3:70"},{"kind":"speech","text":"Where hadst thou it?","sourceLine":"4.3.204","speaker":"FERDINAND","id":"lll:4.3:71"},{"kind":"speech","text":"Of Costard.","sourceLine":"4.3.205","speaker":"JAQUENETTA","id":"lll:4.3:72"},{"kind":"speech","text":"Where hadst thou it?","sourceLine":"4.3.206","speaker":"FERDINAND","id":"lll:4.3:73"},{"kind":"speech","text":"Of Dun Adramadio, Dun Adramadio.","sourceLine":"4.3.207","speaker":"COSTARD","id":"lll:4.3:74"},{"kind":"stage","text":"BIRON tears the letter","id":"lll:4.3:75"},{"kind":"speech","text":"How now! what is in you? why dost thou tear it?","sourceLine":"4.3.208","speaker":"FERDINAND","id":"lll:4.3:76"},{"kind":"speech","text":"A toy, my liege, a toy: your grace needs not fear it.","sourceLine":"4.3.209","speaker":"BIRON","id":"lll:4.3:77"},{"kind":"speech","text":"It did move him to passion, and therefore let's hear it.","sourceLine":"4.3.210","speaker":"LONGAVILLE","id":"lll:4.3:78"},{"kind":"speech","text":"It is Biron's writing, and here is his name.","sourceLine":"4.3.211","speaker":"DUMAIN","id":"lll:4.3:79"},{"kind":"stage","text":"Gathering up the pieces","id":"lll:4.3:80"},{"kind":"speech","text":"[To COSTARD] Ah, you whoreson loggerhead! you were\nborn to do me shame.\nGuilty, my lord, guilty! I confess, I confess.","sourceLine":"4.3.212","speaker":"BIRON","id":"lll:4.3:81"},{"kind":"speech","text":"What?","sourceLine":"4.3.215","speaker":"FERDINAND","id":"lll:4.3:82"},{"kind":"speech","text":"That you three fools lack'd me fool to make up the mess:\nHe, he, and you, and you, my liege, and I,\nAre pick-purses in love, and we deserve to die.\nO, dismiss this audience, and I shall tell you more.","sourceLine":"4.3.216","speaker":"BIRON","id":"lll:4.3:83"},{"kind":"speech","text":"Now the number is even.","sourceLine":"4.3.220","speaker":"DUMAIN","id":"lll:4.3:84"},{"kind":"speech","text":"True, true; we are four.\nWill these turtles be gone?","sourceLine":"4.3.221","speaker":"BIRON","id":"lll:4.3:85"},{"kind":"speech","text":"Hence, sirs; away!","sourceLine":"4.3.223","speaker":"FERDINAND","id":"lll:4.3:86"},{"kind":"speech","text":"Walk aside the true folk, and let the traitors stay.","sourceLine":"4.3.224","speaker":"COSTARD","id":"lll:4.3:87"},{"kind":"stage","text":"Exeunt COSTARD and JAQUENETTA","id":"lll:4.3:88"},{"kind":"speech","text":"Sweet lords, sweet lovers, O, let us embrace!\nAs true we are as flesh and blood can be:\nThe sea will ebb and flow, heaven show his face;\nYoung blood doth not obey an old decree:\nWe cannot cross the cause why we were born;\nTherefore of all hands must we be forsworn.","sourceLine":"4.3.225","speaker":"BIRON","id":"lll:4.3:89"},{"kind":"speech","text":"What, did these rent lines show some love of thine?","sourceLine":"4.3.231","speaker":"FERDINAND","id":"lll:4.3:90"},{"kind":"speech","text":"Did they, quoth you? Who sees the heavenly Rosaline,\nThat, like a rude and savage man of Inde,\nAt the first opening of the gorgeous east,\nBows not his vassal head and strucken blind\nKisses the base ground with obedient breast?\nWhat peremptory eagle-sighted eye\nDares look upon the heaven of her brow,\nThat is not blinded by her majesty?","sourceLine":"4.3.232","speaker":"BIRON","id":"lll:4.3:91"},{"kind":"speech","text":"What zeal, what fury hath inspired thee now?\nMy love, her mistress, is a gracious moon;\nShe an attending star, scarce seen a light.","sourceLine":"4.3.240","speaker":"FERDINAND","id":"lll:4.3:92"},{"kind":"speech","text":"My eyes are then no eyes, nor I Biron:\nO, but for my love, day would turn to night!\nOf all complexions the cull'd sovereignty\nDo meet, as at a fair, in her fair cheek,\nWhere several worthies make one dignity,\nWhere nothing wants that want itself doth seek.\nLend me the flourish of all gentle tongues,--\nFie, painted rhetoric! O, she needs it not:\nTo things of sale a seller's praise belongs,\nShe passes praise; then praise too short doth blot.\nA wither'd hermit, five-score winters worn,\nMight shake off fifty, looking in her eye:\nBeauty doth varnish age, as if new-born,\nAnd gives the crutch the cradle's infancy:\nO, 'tis the sun that maketh all things shine.","sourceLine":"4.3.243","speaker":"BIRON","id":"lll:4.3:93"},{"kind":"speech","text":"By heaven, thy love is black as ebony.","sourceLine":"4.3.258","speaker":"FERDINAND","id":"lll:4.3:94"},{"kind":"speech","text":"Is ebony like her? O wood divine!\nA wife of such wood were felicity.\nO, who can give an oath? where is a book?\nThat I may swear beauty doth beauty lack,\nIf that she learn not of her eye to look:\nNo face is fair that is not full so black.","sourceLine":"4.3.259","speaker":"BIRON","id":"lll:4.3:95"},{"kind":"speech","text":"O paradox! Black is the badge of hell,\nThe hue of dungeons and the suit of night;\nAnd beauty's crest becomes the heavens well.","sourceLine":"4.3.265","speaker":"FERDINAND","id":"lll:4.3:96"},{"kind":"speech","text":"Devils soonest tempt, resembling spirits of light.\nO, if in black my lady's brows be deck'd,\nIt mourns that painting and usurping hair\nShould ravish doters with a false aspect;\nAnd therefore is she born to make black fair.\nHer favour turns the fashion of the days,\nFor native blood is counted painting now;\nAnd therefore red, that would avoid dispraise,\nPaints itself black, to imitate her brow.","sourceLine":"4.3.268","speaker":"BIRON","id":"lll:4.3:97"},{"kind":"speech","text":"To look like her are chimney-sweepers black.","sourceLine":"4.3.277","speaker":"DUMAIN","id":"lll:4.3:98"},{"kind":"speech","text":"And since her time are colliers counted bright.","sourceLine":"4.3.278","speaker":"LONGAVILLE","id":"lll:4.3:99"},{"kind":"speech","text":"And Ethiopes of their sweet complexion crack.","sourceLine":"4.3.279","speaker":"FERDINAND","id":"lll:4.3:100"},{"kind":"speech","text":"Dark needs no candles now, for dark is light.","sourceLine":"4.3.280","speaker":"DUMAIN","id":"lll:4.3:101"},{"kind":"speech","text":"Your mistresses dare never come in rain,\nFor fear their colours should be wash'd away.","sourceLine":"4.3.281","speaker":"BIRON","id":"lll:4.3:102"},{"kind":"speech","text":"'Twere good, yours did; for, sir, to tell you plain,\nI'll find a fairer face not wash'd to-day.","sourceLine":"4.3.283","speaker":"FERDINAND","id":"lll:4.3:103"},{"kind":"speech","text":"I'll prove her fair, or talk till doomsday here.","sourceLine":"4.3.285","speaker":"BIRON","id":"lll:4.3:104"},{"kind":"speech","text":"No devil will fright thee then so much as she.","sourceLine":"4.3.286","speaker":"FERDINAND","id":"lll:4.3:105"},{"kind":"speech","text":"I never knew man hold vile stuff so dear.","sourceLine":"4.3.287","speaker":"DUMAIN","id":"lll:4.3:106"},{"kind":"speech","text":"Look, here's thy love: my foot and her face see.","sourceLine":"4.3.288","speaker":"LONGAVILLE","id":"lll:4.3:107"},{"kind":"speech","text":"O, if the streets were paved with thine eyes,\nHer feet were much too dainty for such tread!","sourceLine":"4.3.289","speaker":"BIRON","id":"lll:4.3:108"},{"kind":"speech","text":"O, vile! then, as she goes, what upward lies\nThe street should see as she walk'd overhead.","sourceLine":"4.3.291","speaker":"DUMAIN","id":"lll:4.3:109"},{"kind":"speech","text":"But what of this? are we not all in love?","sourceLine":"4.3.293","speaker":"FERDINAND","id":"lll:4.3:110"},{"kind":"speech","text":"Nothing so sure; and thereby all forsworn.","sourceLine":"4.3.294","speaker":"BIRON","id":"lll:4.3:111"},{"kind":"speech","text":"Then leave this chat; and, good Biron, now prove\nOur loving lawful, and our faith not torn.","sourceLine":"4.3.295","speaker":"FERDINAND","id":"lll:4.3:112"},{"kind":"speech","text":"Ay, marry, there; some flattery for this evil.","sourceLine":"4.3.297","speaker":"DUMAIN","id":"lll:4.3:113"},{"kind":"speech","text":"O, some authority how to proceed;\nSome tricks, some quillets, how to cheat the devil.","sourceLine":"4.3.298","speaker":"LONGAVILLE","id":"lll:4.3:114"},{"kind":"speech","text":"Some salve for perjury.","sourceLine":"4.3.300","speaker":"DUMAIN","id":"lll:4.3:115"},{"kind":"speech","text":"'Tis more than need.\nHave at you, then, affection's men at arms.\nConsider what you first did swear unto,\nTo fast, to study, and to see no woman;\nFlat treason 'gainst the kingly state of youth.\nSay, can you fast? your stomachs are too young;\nAnd abstinence engenders maladies.\nAnd where that you have vow'd to study, lords,\nIn that each of you have forsworn his book,\nCan you still dream and pore and thereon look?\nFor when would you, my lord, or you, or you,\nHave found the ground of study's excellence\nWithout the beauty of a woman's face?","sourceLine":"4.3.301","speaker":"BIRON","id":"lll:4.3:116"},{"kind":"stage","text":"From women's eyes this doctrine I derive; They are the ground, the books, the academes From whence doth spring the true Promethean fire","id":"lll:4.3:117"},{"kind":"speech","text":"Why, universal plodding poisons up\nThe nimble spirits in the arteries,\nAs motion and long-during action tires\nThe sinewy vigour of the traveller.\nNow, for not looking on a woman's face,\nYou have in that forsworn the use of eyes\nAnd study too, the causer of your vow;\nFor where is any author in the world\nTeaches such beauty as a woman's eye?\nLearning is but an adjunct to ourself\nAnd where we are our learning likewise is:\nThen when ourselves we see in ladies' eyes,\nDo we not likewise see our learning there?\nO, we have made a vow to study, lords,\nAnd in that vow we have forsworn our books.\nFor when would you, my liege, or you, or you,\nIn leaden contemplation have found out\nSuch fiery numbers as the prompting eyes\nOf beauty's tutors have enrich'd you with?\nOther slow arts entirely keep the brain;\nAnd therefore, finding barren practisers,\nScarce show a harvest of their heavy toil:\nBut love, first learned in a lady's eyes,\nLives not alone immured in the brain;\nBut, with the motion of all elements,\nCourses as swift as thought in every power,\nAnd gives to every power a double power,\nAbove their functions and their offices.\nIt adds a precious seeing to the eye;\nA lover's eyes will gaze an eagle blind;\nA lover's ear will hear the lowest sound,\nWhen the suspicious head of theft is stopp'd:\nLove's feeling is more soft and sensible\nThan are the tender horns of cockl'd snails;\nLove's tongue proves dainty Bacchus gross in taste:\nFor valour, is not Love a Hercules,\nStill climbing trees in the Hesperides?\nSubtle as Sphinx; as sweet and musical\nAs bright Apollo's lute, strung with his hair:\nAnd when Love speaks, the voice of all the gods\nMakes heaven drowsy with the harmony.\nNever durst poet touch a pen to write\nUntil his ink were temper'd with Love's sighs;\nO, then his lines would ravish savage ears\nAnd plant in tyrants mild humility.\nFrom women's eyes this doctrine I derive:\nThey sparkle still the right Promethean fire;\nThey are the books, the arts, the academes,\nThat show, contain and nourish all the world:\nElse none at all in ought proves excellent.\nThen fools you were these women to forswear,\nOr keeping what is sworn, you will prove fools.\nFor wisdom's sake, a word that all men love,\nOr for love's sake, a word that loves all men,\nOr for men's sake, the authors of these women,\nOr women's sake, by whom we men are men,\nLet us once lose our oaths to find ourselves,\nOr else we lose ourselves to keep our oaths.\nIt is religion to be thus forsworn,\nFor charity itself fulfills the law,\nAnd who can sever love from charity?","sourceLine":"4.3.314","speaker":"BIRON","id":"lll:4.3:118"},{"kind":"speech","text":"Saint Cupid, then! and, soldiers, to the field!","sourceLine":"4.3.375","speaker":"FERDINAND","id":"lll:4.3:119"},{"kind":"speech","text":"Advance your standards, and upon them, lords;\nPell-mell, down with them! but be first advised,\nIn conflict that you get the sun of them.","sourceLine":"4.3.376","speaker":"BIRON","id":"lll:4.3:120"},{"kind":"speech","text":"Now to plain-dealing; lay these glozes by:\nShall we resolve to woo these girls of France?","sourceLine":"4.3.379","speaker":"LONGAVILLE","id":"lll:4.3:121"},{"kind":"speech","text":"And win them too: therefore let us devise\nSome entertainment for them in their tents.","sourceLine":"4.3.381","speaker":"FERDINAND","id":"lll:4.3:122"},{"kind":"speech","text":"First, from the park let us conduct them thither;\nThen homeward every man attach the hand\nOf his fair mistress: in the afternoon\nWe will with some strange pastime solace them,\nSuch as the shortness of the time can shape;\nFor revels, dances, masks and merry hours\nForerun fair Love, strewing her way with flowers.","sourceLine":"4.3.383","speaker":"BIRON","id":"lll:4.3:123"},{"kind":"speech","text":"Away, away! no time shall be omitted\nThat will betime, and may by us be fitted.","sourceLine":"4.3.390","speaker":"FERDINAND","id":"lll:4.3:124"},{"kind":"speech","text":"Allons! allons! Sow'd cockle reap'd no corn;\nAnd justice always whirls in equal measure:\nLight wenches may prove plagues to men forsworn;\nIf so, our copper buys no better treasure.","sourceLine":"4.3.392","speaker":"BIRON","id":"lll:4.3:125"},{"kind":"stage","text":"Exeunt","id":"lll:4.3:126"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"4.3.396","speaker":"BIRON","id":"lll:4.3:127"}],"scene":3},{"id":"5.1","label":"Act 5 · SCENE I. The same.","act":5,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter HOLOFERNES, SIR NATHANIEL, and DULL","id":"lll:5.1:1"},{"kind":"speech","text":"Satis quod sufficit.","sourceLine":"5.1.1","speaker":"HOLOFERNES","id":"lll:5.1:2"},{"kind":"speech","text":"I praise God for you, sir: your reasons at dinner\nhave been sharp and sententious; pleasant without\nscurrility, witty without affection, audacious without\nimpudency, learned without opinion, and strange with-\nout heresy. I did converse this quondam day with\na companion of the king's, who is intituled, nomi-\nnated, or called, Don Adriano de Armado.","sourceLine":"5.1.2","speaker":"SIR NATHANIEL","id":"lll:5.1:3"},{"kind":"speech","text":"Novi hominem tanquam te: his humour is lofty, his\ndiscourse peremptory, his tongue filed, his eye\nambitious, his gait majestical, and his general\nbehavior vain, ridiculous, and thrasonical. He is\ntoo picked, too spruce, too affected, too odd, as it\nwere, too peregrinate, as I may call it.","sourceLine":"5.1.9","speaker":"HOLOFERNES","id":"lll:5.1:4"},{"kind":"speech","text":"A most singular and choice epithet.","sourceLine":"5.1.15","speaker":"SIR NATHANIEL","id":"lll:5.1:5"},{"kind":"stage","text":"Draws out his table-book","id":"lll:5.1:6"},{"kind":"speech","text":"He draweth out the thread of his verbosity finer\nthan the staple of his argument. I abhor such\nfanatical phantasimes, such insociable and\npoint-devise companions; such rackers of\northography, as to speak dout, fine, when he should\nsay doubt; det, when he should pronounce debt,--d,\ne, b, t, not d, e, t: he clepeth a calf, cauf;\nhalf, hauf; neighbour vocatur nebor; neigh\nabbreviated ne. This is abhominable,--which he\nwould call abbominable: it insinuateth me of\ninsanie: anne intelligis, domine? to make frantic, lunatic.","sourceLine":"5.1.16","speaker":"HOLOFERNES","id":"lll:5.1:7"},{"kind":"speech","text":"Laus Deo, bene intelligo.","sourceLine":"5.1.27","speaker":"SIR NATHANIEL","id":"lll:5.1:8"},{"kind":"speech","text":"Bon, bon, fort bon, Priscian! a little scratch'd,\n'twill serve.","sourceLine":"5.1.28","speaker":"HOLOFERNES","id":"lll:5.1:9"},{"kind":"speech","text":"Videsne quis venit?","sourceLine":"5.1.30","speaker":"SIR NATHANIEL","id":"lll:5.1:10"},{"kind":"speech","text":"Video, et gaudeo.","sourceLine":"5.1.31","speaker":"HOLOFERNES","id":"lll:5.1:11"},{"kind":"stage","text":"Enter DON ADRIANO DE ARMADO, MOTH, and COSTARD","id":"lll:5.1:12"},{"kind":"speech","text":"Chirrah!","sourceLine":"5.1.33","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.32","rawPrefix":"DON","followingSpeechAnchor":"speech10","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4271,"originalHtml":"<A NAME=5.1.32>DON</A><br>\n</blockquote>\n\n<A NAME=speech10><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:13"},{"kind":"stage","text":"To MOTH","id":"lll:5.1:14"},{"kind":"speech","text":"Quare chirrah, not sirrah?","sourceLine":"5.1.34","speaker":"HOLOFERNES","id":"lll:5.1:15"},{"kind":"speech","text":"Men of peace, well encountered.","sourceLine":"5.1.36","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.35","rawPrefix":"DON","followingSpeechAnchor":"speech12","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4283,"originalHtml":"<A NAME=5.1.35>DON</A><br>\n</blockquote>\n\n<A NAME=speech12><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:16"},{"kind":"speech","text":"Most military sir, salutation.","sourceLine":"5.1.37","speaker":"HOLOFERNES","id":"lll:5.1:17"},{"kind":"speech","text":"[Aside to COSTARD] They have been at a great feast\nof languages, and stolen the scraps.","sourceLine":"5.1.38","speaker":"MOTH","id":"lll:5.1:18"},{"kind":"speech","text":"O, they have lived long on the alms-basket of words.\nI marvel thy master hath not eaten thee for a word;\nfor thou art not so long by the head as\nhonorificabilitudinitatibus: thou art easier\nswallowed than a flap-dragon.","sourceLine":"5.1.40","speaker":"COSTARD","id":"lll:5.1:19"},{"kind":"speech","text":"Peace! the peal begins.","sourceLine":"5.1.45","speaker":"MOTH","id":"lll:5.1:20"},{"kind":"speech","text":"[To HOLOFERNES] Monsieur, are you not lettered?","sourceLine":"5.1.47","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.46","rawPrefix":"DON","followingSpeechAnchor":"speech17","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4314,"originalHtml":"<A NAME=5.1.46>DON</A><br>\n</blockquote>\n\n<A NAME=speech17><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:21"},{"kind":"speech","text":"Yes, yes; he teaches boys the hornbook. What is a,\nb, spelt backward, with the horn on his head?","sourceLine":"5.1.48","speaker":"MOTH","id":"lll:5.1:22"},{"kind":"speech","text":"Ba, pueritia, with a horn added.","sourceLine":"5.1.50","speaker":"HOLOFERNES","id":"lll:5.1:23"},{"kind":"speech","text":"Ba, most silly sheep with a horn. You hear his learning.","sourceLine":"5.1.51","speaker":"MOTH","id":"lll:5.1:24"},{"kind":"speech","text":"Quis, quis, thou consonant?","sourceLine":"5.1.52","speaker":"HOLOFERNES","id":"lll:5.1:25"},{"kind":"speech","text":"The third of the five vowels, if you repeat them; or\nthe fifth, if I.","sourceLine":"5.1.53","speaker":"MOTH","id":"lll:5.1:26"},{"kind":"speech","text":"I will repeat them,--a, e, i,--","sourceLine":"5.1.55","speaker":"HOLOFERNES","id":"lll:5.1:27"},{"kind":"speech","text":"The sheep: the other two concludes it,--o, u.","sourceLine":"5.1.56","speaker":"MOTH","id":"lll:5.1:28"},{"kind":"speech","text":"Now, by the salt wave of the Mediterraneum, a sweet\ntouch, a quick venue of wit! snip, snap, quick and\nhome! it rejoiceth my intellect: true wit!","sourceLine":"5.1.58","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.57","rawPrefix":"DON","followingSpeechAnchor":"speech25","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4357,"originalHtml":"<A NAME=5.1.57>DON</A><br>\n</blockquote>\n\n<A NAME=speech25><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:29"},{"kind":"speech","text":"Offered by a child to an old man; which is wit-old.","sourceLine":"5.1.61","speaker":"MOTH","id":"lll:5.1:30"},{"kind":"speech","text":"What is the figure? what is the figure?","sourceLine":"5.1.62","speaker":"HOLOFERNES","id":"lll:5.1:31"},{"kind":"speech","text":"Horns.","sourceLine":"5.1.63","speaker":"MOTH","id":"lll:5.1:32"},{"kind":"speech","text":"Thou disputest like an infant: go, whip thy gig.","sourceLine":"5.1.64","speaker":"HOLOFERNES","id":"lll:5.1:33"},{"kind":"speech","text":"Lend me your horn to make one, and I will whip about\nyour infamy circum circa,--a gig of a cuckold's horn.","sourceLine":"5.1.65","speaker":"MOTH","id":"lll:5.1:34"},{"kind":"speech","text":"An I had but one penny in the world, thou shouldst\nhave it to buy gingerbread: hold, there is the very\nremuneration I had of thy master, thou halfpenny\npurse of wit, thou pigeon-egg of discretion. O, an\nthe heavens were so pleased that thou wert but my\nbastard, what a joyful father wouldst thou make me!\nGo to; thou hast it ad dunghill, at the fingers'\nends, as they say.","sourceLine":"5.1.67","speaker":"COSTARD","id":"lll:5.1:35"},{"kind":"speech","text":"O, I smell false Latin; dunghill for unguem.","sourceLine":"5.1.75","speaker":"HOLOFERNES","id":"lll:5.1:36"},{"kind":"speech","text":"Arts-man, preambulate, we will be singled from the\nbarbarous. Do you not educate youth at the\ncharge-house on the top of the mountain?","sourceLine":"5.1.77","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.76","rawPrefix":"DON","followingSpeechAnchor":"speech33","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4408,"originalHtml":"<A NAME=5.1.76>DON</A><br>\n</blockquote>\n\n<A NAME=speech33><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:37"},{"kind":"speech","text":"Or mons, the hill.","sourceLine":"5.1.80","speaker":"HOLOFERNES","id":"lll:5.1:38"},{"kind":"speech","text":"At your sweet pleasure, for the mountain.","sourceLine":"5.1.82","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.81","rawPrefix":"DON","followingSpeechAnchor":"speech35","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4421,"originalHtml":"<A NAME=5.1.81>DON</A><br>\n</blockquote>\n\n<A NAME=speech35><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:39"},{"kind":"speech","text":"I do, sans question.","sourceLine":"5.1.83","speaker":"HOLOFERNES","id":"lll:5.1:40"},{"kind":"speech","text":"Sir, it is the king's most sweet pleasure and\naffection to congratulate the princess at her\npavilion in the posteriors of this day, which the\nrude multitude call the afternoon.","sourceLine":"5.1.85","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.84","rawPrefix":"DON","followingSpeechAnchor":"speech37","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4432,"originalHtml":"<A NAME=5.1.84>DON</A><br>\n</blockquote>\n\n<A NAME=speech37><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:41"},{"kind":"speech","text":"The posterior of the day, most generous sir, is\nliable, congruent and measurable for the afternoon:\nthe word is well culled, chose, sweet and apt, I do\nassure you, sir, I do assure.","sourceLine":"5.1.89","speaker":"HOLOFERNES","id":"lll:5.1:42"},{"kind":"speech","text":"Sir, the king is a noble gentleman, and my familiar,\nI do assure ye, very good friend: for what is\ninward between us, let it pass. I do beseech thee,\nremember thy courtesy; I beseech thee, apparel thy\nhead: and among other important and most serious\ndesigns, and of great import indeed, too, but let\nthat pass: for I must tell thee, it will please his\ngrace, by the world, sometime to lean upon my poor\nshoulder, and with his royal finger, thus, dally\nwith my excrement, with my mustachio; but, sweet\nheart, let that pass. By the world, I recount no\nfable: some certain special honours it pleaseth his\ngreatness to impart to Armado, a soldier, a man of\ntravel, that hath seen the world; but let that pass.\nThe very all of all is,--but, sweet heart, I do\nimplore secrecy,--that the king would have me\npresent the princess, sweet chuck, with some\ndelightful ostentation, or show, or pageant, or\nantique, or firework. Now, understanding that the\ncurate and your sweet self are good at such\neruptions and sudden breaking out of mirth, as it\nwere, I have acquainted you withal, to the end to\ncrave your assistance.","sourceLine":"5.1.94","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.93","rawPrefix":"DON","followingSpeechAnchor":"speech39","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4449,"originalHtml":"<A NAME=5.1.93>DON</A><br>\n</blockquote>\n\n<A NAME=speech39><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:43"},{"kind":"speech","text":"Sir, you shall present before her the Nine Worthies.\nSir, as concerning some entertainment of time, some\nshow in the posterior of this day, to be rendered by\nour assistants, at the king's command, and this most\ngallant, illustrate, and learned gentleman, before\nthe princess; I say none so fit as to present the\nNine Worthies.","sourceLine":"5.1.117","speaker":"HOLOFERNES","id":"lll:5.1:44"},{"kind":"speech","text":"Where will you find men worthy enough to present them?","sourceLine":"5.1.124","speaker":"SIR NATHANIEL","id":"lll:5.1:45"},{"kind":"speech","text":"Joshua, yourself; myself and this gallant gentleman,\nJudas Maccabaeus; this swain, because of his great\nlimb or joint, shall pass Pompey the Great; the\npage, Hercules,--","sourceLine":"5.1.125","speaker":"HOLOFERNES","id":"lll:5.1:46"},{"kind":"speech","text":"Pardon, sir; error: he is not quantity enough for\nthat Worthy's thumb: he is not so big as the end of his club.","sourceLine":"5.1.130","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.129","rawPrefix":"DON","followingSpeechAnchor":"speech43","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4501,"originalHtml":"<A NAME=5.1.129>DON</A><br>\n</blockquote>\n\n<A NAME=speech43><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:47"},{"kind":"speech","text":"Shall I have audience? he shall present Hercules in\nminority: his enter and exit shall be strangling a\nsnake; and I will have an apology for that purpose.","sourceLine":"5.1.132","speaker":"HOLOFERNES","id":"lll:5.1:48"},{"kind":"speech","text":"An excellent device! so, if any of the audience\nhiss, you may cry 'Well done, Hercules! now thou\ncrushest the snake!' that is the way to make an\noffence gracious, though few have the grace to do it.","sourceLine":"5.1.135","speaker":"MOTH","id":"lll:5.1:49"},{"kind":"speech","text":"For the rest of the Worthies?--","sourceLine":"5.1.140","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.139","rawPrefix":"DON","followingSpeechAnchor":"speech46","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4523,"originalHtml":"<A NAME=5.1.139>DON</A><br>\n</blockquote>\n\n<A NAME=speech46><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:50"},{"kind":"speech","text":"I will play three myself.","sourceLine":"5.1.141","speaker":"HOLOFERNES","id":"lll:5.1:51"},{"kind":"speech","text":"Thrice-worthy gentleman!","sourceLine":"5.1.142","speaker":"MOTH","id":"lll:5.1:52"},{"kind":"speech","text":"Shall I tell you a thing?","sourceLine":"5.1.144","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.143","rawPrefix":"DON","followingSpeechAnchor":"speech49","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4539,"originalHtml":"<A NAME=5.1.143>DON</A><br>\n</blockquote>\n\n<A NAME=speech49><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:53"},{"kind":"speech","text":"We attend.","sourceLine":"5.1.145","speaker":"HOLOFERNES","id":"lll:5.1:54"},{"kind":"speech","text":"We will have, if this fadge not, an antique. I\nbeseech you, follow.","sourceLine":"5.1.147","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.1.146","rawPrefix":"DON","followingSpeechAnchor":"speech51","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":4550,"originalHtml":"<A NAME=5.1.146>DON</A><br>\n</blockquote>\n\n<A NAME=speech51><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.1:55"},{"kind":"speech","text":"Via, goodman Dull! thou hast spoken no word all this while.","sourceLine":"5.1.149","speaker":"HOLOFERNES","id":"lll:5.1:56"},{"kind":"speech","text":"Nor understood none neither, sir.","sourceLine":"5.1.150","speaker":"DULL","id":"lll:5.1:57"},{"kind":"speech","text":"Allons! we will employ thee.","sourceLine":"5.1.151","speaker":"HOLOFERNES","id":"lll:5.1:58"},{"kind":"speech","text":"I'll make one in a dance, or so; or I will play\nOn the tabour to the Worthies, and let them dance the hay.","sourceLine":"5.1.152","speaker":"DULL","id":"lll:5.1:59"},{"kind":"speech","text":"Most dull, honest Dull! To our sport, away!","sourceLine":"5.1.154","speaker":"HOLOFERNES","id":"lll:5.1:60"},{"kind":"stage","text":"Exeunt","id":"lll:5.1:61"},{"kind":"speech","text":"LOVE'S LABOURS LOST","sourceLine":"5.1.155","speaker":"HOLOFERNES","id":"lll:5.1:62"}],"scene":1},{"id":"5.2","label":"Act 5 · SCENE II. The same.","act":5,"sourceUrl":"https://shakespeare.mit.edu/lll/full.html","blocks":[{"kind":"stage","text":"Enter the PRINCESS, KATHARINE, ROSALINE, and MARIA","id":"lll:5.2:1"},{"kind":"speech","text":"Sweet hearts, we shall be rich ere we depart,\nIf fairings come thus plentifully in:\nA lady wall'd about with diamonds!\nLook you what I have from the loving king.","sourceLine":"5.2.1","speaker":"PRINCESS","id":"lll:5.2:2"},{"kind":"speech","text":"Madame, came nothing else along with that?","sourceLine":"5.2.5","speaker":"ROSALINE","id":"lll:5.2:3"},{"kind":"speech","text":"Nothing but this! yes, as much love in rhyme\nAs would be cramm'd up in a sheet of paper,\nWrit o' both sides the leaf, margent and all,\nThat he was fain to seal on Cupid's name.","sourceLine":"5.2.6","speaker":"PRINCESS","id":"lll:5.2:4"},{"kind":"speech","text":"That was the way to make his godhead wax,\nFor he hath been five thousand years a boy.","sourceLine":"5.2.10","speaker":"ROSALINE","id":"lll:5.2:5"},{"kind":"speech","text":"Ay, and a shrewd unhappy gallows too.","sourceLine":"5.2.12","speaker":"KATHARINE","id":"lll:5.2:6"},{"kind":"speech","text":"You'll ne'er be friends with him; a' kill'd your sister.","sourceLine":"5.2.13","speaker":"ROSALINE","id":"lll:5.2:7"},{"kind":"speech","text":"He made her melancholy, sad, and heavy;\nAnd so she died: had she been light, like you,\nOf such a merry, nimble, stirring spirit,\nShe might ha' been a grandam ere she died:\nAnd so may you; for a light heart lives long.","sourceLine":"5.2.14","speaker":"KATHARINE","id":"lll:5.2:8"},{"kind":"speech","text":"What's your dark meaning, mouse, of this light word?","sourceLine":"5.2.19","speaker":"ROSALINE","id":"lll:5.2:9"},{"kind":"speech","text":"A light condition in a beauty dark.","sourceLine":"5.2.20","speaker":"KATHARINE","id":"lll:5.2:10"},{"kind":"speech","text":"We need more light to find your meaning out.","sourceLine":"5.2.21","speaker":"ROSALINE","id":"lll:5.2:11"},{"kind":"speech","text":"You'll mar the light by taking it in snuff;\nTherefore I'll darkly end the argument.","sourceLine":"5.2.22","speaker":"KATHARINE","id":"lll:5.2:12"},{"kind":"speech","text":"Look what you do, you do it still i' the dark.","sourceLine":"5.2.24","speaker":"ROSALINE","id":"lll:5.2:13"},{"kind":"speech","text":"So do not you, for you are a light wench.","sourceLine":"5.2.25","speaker":"KATHARINE","id":"lll:5.2:14"},{"kind":"speech","text":"Indeed I weigh not you, and therefore light.","sourceLine":"5.2.26","speaker":"ROSALINE","id":"lll:5.2:15"},{"kind":"speech","text":"You weigh me not? O, that's you care not for me.","sourceLine":"5.2.27","speaker":"KATHARINE","id":"lll:5.2:16"},{"kind":"speech","text":"Great reason; for 'past cure is still past care.'","sourceLine":"5.2.28","speaker":"ROSALINE","id":"lll:5.2:17"},{"kind":"speech","text":"Well bandied both; a set of wit well play'd.\nBut Rosaline, you have a favour too:\nWho sent it? and what is it?","sourceLine":"5.2.29","speaker":"PRINCESS","id":"lll:5.2:18"},{"kind":"speech","text":"I would you knew:\nAn if my face were but as fair as yours,\nMy favour were as great; be witness this.\nNay, I have verses too, I thank Biron:\nThe numbers true; and, were the numbering too,\nI were the fairest goddess on the ground:\nI am compared to twenty thousand fairs.\nO, he hath drawn my picture in his letter!","sourceLine":"5.2.32","speaker":"ROSALINE","id":"lll:5.2:19"},{"kind":"speech","text":"Any thing like?","sourceLine":"5.2.40","speaker":"PRINCESS","id":"lll:5.2:20"},{"kind":"speech","text":"Much in the letters; nothing in the praise.","sourceLine":"5.2.41","speaker":"ROSALINE","id":"lll:5.2:21"},{"kind":"speech","text":"Beauteous as ink; a good conclusion.","sourceLine":"5.2.42","speaker":"PRINCESS","id":"lll:5.2:22"},{"kind":"speech","text":"Fair as a text B in a copy-book.","sourceLine":"5.2.43","speaker":"KATHARINE","id":"lll:5.2:23"},{"kind":"speech","text":"'Ware pencils, ho! let me not die your debtor,\nMy red dominical, my golden letter:\nO, that your face were not so full of O's!","sourceLine":"5.2.44","speaker":"ROSALINE","id":"lll:5.2:24"},{"kind":"speech","text":"A pox of that jest! and I beshrew all shrows.","sourceLine":"5.2.47","speaker":"KATHARINE","id":"lll:5.2:25"},{"kind":"speech","text":"But, Katharine, what was sent to you from fair Dumain?","sourceLine":"5.2.48","speaker":"PRINCESS","id":"lll:5.2:26"},{"kind":"speech","text":"Madam, this glove.","sourceLine":"5.2.49","speaker":"KATHARINE","id":"lll:5.2:27"},{"kind":"speech","text":"Did he not send you twain?","sourceLine":"5.2.50","speaker":"PRINCESS","id":"lll:5.2:28"},{"kind":"speech","text":"Yes, madam, and moreover\nSome thousand verses of a faithful lover,\nA huge translation of hypocrisy,\nVilely compiled, profound simplicity.","sourceLine":"5.2.51","speaker":"KATHARINE","id":"lll:5.2:29"},{"kind":"speech","text":"This and these pearls to me sent Longaville:\nThe letter is too long by half a mile.","sourceLine":"5.2.55","speaker":"MARIA","id":"lll:5.2:30"},{"kind":"speech","text":"I think no less. Dost thou not wish in heart\nThe chain were longer and the letter short?","sourceLine":"5.2.57","speaker":"PRINCESS","id":"lll:5.2:31"},{"kind":"speech","text":"Ay, or I would these hands might never part.","sourceLine":"5.2.59","speaker":"MARIA","id":"lll:5.2:32"},{"kind":"speech","text":"We are wise girls to mock our lovers so.","sourceLine":"5.2.60","speaker":"PRINCESS","id":"lll:5.2:33"},{"kind":"speech","text":"They are worse fools to purchase mocking so.\nThat same Biron I'll torture ere I go:\nO that I knew he were but in by the week!\nHow I would make him fawn and beg and seek\nAnd wait the season and observe the times\nAnd spend his prodigal wits in bootless rhymes\nAnd shape his service wholly to my hests\nAnd make him proud to make me proud that jests!\nSo perttaunt-like would I o'ersway his state\nThat he should be my fool and I his fate.","sourceLine":"5.2.61","speaker":"ROSALINE","id":"lll:5.2:34"},{"kind":"speech","text":"None are so surely caught, when they are catch'd,\nAs wit turn'd fool: folly, in wisdom hatch'd,\nHath wisdom's warrant and the help of school\nAnd wit's own grace to grace a learned fool.","sourceLine":"5.2.71","speaker":"PRINCESS","id":"lll:5.2:35"},{"kind":"speech","text":"The blood of youth burns not with such excess\nAs gravity's revolt to wantonness.","sourceLine":"5.2.75","speaker":"ROSALINE","id":"lll:5.2:36"},{"kind":"speech","text":"Folly in fools bears not so strong a note\nAs foolery in the wise, when wit doth dote;\nSince all the power thereof it doth apply\nTo prove, by wit, worth in simplicity.","sourceLine":"5.2.77","speaker":"MARIA","id":"lll:5.2:37"},{"kind":"speech","text":"Here comes Boyet, and mirth is in his face.","sourceLine":"5.2.81","speaker":"PRINCESS","id":"lll:5.2:38"},{"kind":"stage","text":"Enter BOYET","id":"lll:5.2:39"},{"kind":"speech","text":"O, I am stabb'd with laughter! Where's her grace?","sourceLine":"5.2.82","speaker":"BOYET","id":"lll:5.2:40"},{"kind":"speech","text":"Thy news Boyet?","sourceLine":"5.2.83","speaker":"PRINCESS","id":"lll:5.2:41"},{"kind":"speech","text":"Prepare, madam, prepare!\nArm, wenches, arm! encounters mounted are\nAgainst your peace: Love doth approach disguised,\nArmed in arguments; you'll be surprised:\nMuster your wits; stand in your own defence;\nOr hide your heads like cowards, and fly hence.","sourceLine":"5.2.84","speaker":"BOYET","id":"lll:5.2:42"},{"kind":"speech","text":"Saint Denis to Saint Cupid! What are they\nThat charge their breath against us? say, scout, say.","sourceLine":"5.2.90","speaker":"PRINCESS","id":"lll:5.2:43"},{"kind":"speech","text":"Under the cool shade of a sycamore\nI thought to close mine eyes some half an hour;\nWhen, lo! to interrupt my purposed rest,\nToward that shade I might behold addrest\nThe king and his companions: warily\nI stole into a neighbour thicket by,\nAnd overheard what you shall overhear,\nThat, by and by, disguised they will be here.\nTheir herald is a pretty knavish page,\nThat well by heart hath conn'd his embassage:\nAction and accent did they teach him there;\n'Thus must thou speak,' and 'thus thy body bear:'\nAnd ever and anon they made a doubt\nPresence majestical would put him out,\n'For,' quoth the king, 'an angel shalt thou see;\nYet fear not thou, but speak audaciously.'\nThe boy replied, 'An angel is not evil;\nI should have fear'd her had she been a devil.'\nWith that, all laugh'd and clapp'd him on the shoulder,\nMaking the bold wag by their praises bolder:\nOne rubb'd his elbow thus, and fleer'd and swore\nA better speech was never spoke before;\nAnother, with his finger and his thumb,\nCried, 'Via! we will do't, come what will come;'\nThe third he caper'd, and cried, 'All goes well;'\nThe fourth turn'd on the toe, and down he fell.\nWith that, they all did tumble on the ground,\nWith such a zealous laughter, so profound,\nThat in this spleen ridiculous appears,\nTo cheque their folly, passion's solemn tears.","sourceLine":"5.2.92","speaker":"BOYET","id":"lll:5.2:44"},{"kind":"speech","text":"But what, but what, come they to visit us?","sourceLine":"5.2.122","speaker":"PRINCESS","id":"lll:5.2:45"},{"kind":"speech","text":"They do, they do: and are apparell'd thus.\nLike Muscovites or Russians, as I guess.\nTheir purpose is to parle, to court and dance;\nAnd every one his love-feat will advance\nUnto his several mistress, which they'll know\nBy favours several which they did bestow.","sourceLine":"5.2.123","speaker":"BOYET","id":"lll:5.2:46"},{"kind":"speech","text":"And will they so? the gallants shall be task'd;\nFor, ladies, we shall every one be mask'd;\nAnd not a man of them shall have the grace,\nDespite of suit, to see a lady's face.\nHold, Rosaline, this favour thou shalt wear,\nAnd then the king will court thee for his dear;\nHold, take thou this, my sweet, and give me thine,\nSo shall Biron take me for Rosaline.\nAnd change your favours too; so shall your loves\nWoo contrary, deceived by these removes.","sourceLine":"5.2.129","speaker":"PRINCESS","id":"lll:5.2:47"},{"kind":"speech","text":"Come on, then; wear the favours most in sight.","sourceLine":"5.2.139","speaker":"ROSALINE","id":"lll:5.2:48"},{"kind":"speech","text":"But in this changing what is your intent?","sourceLine":"5.2.140","speaker":"KATHARINE","id":"lll:5.2:49"},{"kind":"speech","text":"The effect of my intent is to cross theirs:\nThey do it but in mocking merriment;\nAnd mock for mock is only my intent.\nTheir several counsels they unbosom shall\nTo loves mistook, and so be mock'd withal\nUpon the next occasion that we meet,\nWith visages displayed, to talk and greet.","sourceLine":"5.2.141","speaker":"PRINCESS","id":"lll:5.2:50"},{"kind":"speech","text":"But shall we dance, if they desire to't?","sourceLine":"5.2.148","speaker":"ROSALINE","id":"lll:5.2:51"},{"kind":"speech","text":"No, to the death, we will not move a foot;\nNor to their penn'd speech render we no grace,\nBut while 'tis spoke each turn away her face.","sourceLine":"5.2.149","speaker":"PRINCESS","id":"lll:5.2:52"},{"kind":"speech","text":"Why, that contempt will kill the speaker's heart,\nAnd quite divorce his memory from his part.","sourceLine":"5.2.152","speaker":"BOYET","id":"lll:5.2:53"},{"kind":"speech","text":"Therefore I do it; and I make no doubt\nThe rest will ne'er come in, if he be out\nThere's no such sport as sport by sport o'erthrown,\nTo make theirs ours and ours none but our own:\nSo shall we stay, mocking intended game,\nAnd they, well mock'd, depart away with shame.","sourceLine":"5.2.154","speaker":"PRINCESS","id":"lll:5.2:54"},{"kind":"stage","text":"Trumpets sound within","id":"lll:5.2:55"},{"kind":"speech","text":"The trumpet sounds: be mask'd; the maskers come.","sourceLine":"5.2.160","speaker":"BOYET","id":"lll:5.2:56"},{"kind":"stage","text":"The Ladies mask","id":"lll:5.2:57"},{"kind":"stage","text":"Enter Blackamoors with music; MOTH; FERDINAND, BIRON, LONGAVILLE, and DUMAIN, in Russian habits, and masked","id":"lll:5.2:58"},{"kind":"speech","text":"All hail, the richest beauties on the earth!--","sourceLine":"5.2.161","speaker":"MOTH","id":"lll:5.2:59"},{"kind":"speech","text":"Beauties no richer than rich taffeta.","sourceLine":"5.2.162","speaker":"BOYET","id":"lll:5.2:60"},{"kind":"speech","text":"A holy parcel of the fairest dames.","sourceLine":"5.2.163","speaker":"MOTH","id":"lll:5.2:61"},{"kind":"stage","text":"The Ladies turn their backs to him","id":"lll:5.2:62"},{"kind":"speech","text":"That ever turn'd their--backs--to mortal views!","sourceLine":"5.2.164","speaker":"MOTH","id":"lll:5.2:63"},{"kind":"speech","text":"[Aside to MOTH] Their eyes, villain, their eyes!","sourceLine":"5.2.165","speaker":"BIRON","id":"lll:5.2:64"},{"kind":"speech","text":"That ever turn'd their eyes to mortal views!--Out--","sourceLine":"5.2.166","speaker":"MOTH","id":"lll:5.2:65"},{"kind":"speech","text":"True; out indeed.","sourceLine":"5.2.167","speaker":"BOYET","id":"lll:5.2:66"},{"kind":"speech","text":"Out of your favours, heavenly spirits, vouchsafe\nNot to behold--","sourceLine":"5.2.168","speaker":"MOTH","id":"lll:5.2:67"},{"kind":"speech","text":"[Aside to MOTH] Once to behold, rogue.","sourceLine":"5.2.170","speaker":"BIRON","id":"lll:5.2:68"},{"kind":"speech","text":"Once to behold with your sun-beamed eyes,\n--with your sun-beamed eyes--","sourceLine":"5.2.171","speaker":"MOTH","id":"lll:5.2:69"},{"kind":"speech","text":"They will not answer to that epithet;\nYou were best call it 'daughter-beamed eyes.'","sourceLine":"5.2.173","speaker":"BOYET","id":"lll:5.2:70"},{"kind":"speech","text":"They do not mark me, and that brings me out.","sourceLine":"5.2.175","speaker":"MOTH","id":"lll:5.2:71"},{"kind":"speech","text":"Is this your perfectness? be gone, you rogue!","sourceLine":"5.2.176","speaker":"BIRON","id":"lll:5.2:72"},{"kind":"stage","text":"Exit MOTH","id":"lll:5.2:73"},{"kind":"speech","text":"What would these strangers? know their minds, Boyet:\nIf they do speak our language, 'tis our will:\nThat some plain man recount their purposes\nKnow what they would.","sourceLine":"5.2.177","speaker":"ROSALINE","id":"lll:5.2:74"},{"kind":"speech","text":"What would you with the princess?","sourceLine":"5.2.181","speaker":"BOYET","id":"lll:5.2:75"},{"kind":"speech","text":"Nothing but peace and gentle visitation.","sourceLine":"5.2.182","speaker":"BIRON","id":"lll:5.2:76"},{"kind":"speech","text":"What would they, say they?","sourceLine":"5.2.183","speaker":"ROSALINE","id":"lll:5.2:77"},{"kind":"speech","text":"Nothing but peace and gentle visitation.","sourceLine":"5.2.184","speaker":"BOYET","id":"lll:5.2:78"},{"kind":"speech","text":"Why, that they have; and bid them so be gone.","sourceLine":"5.2.185","speaker":"ROSALINE","id":"lll:5.2:79"},{"kind":"speech","text":"She says, you have it, and you may be gone.","sourceLine":"5.2.186","speaker":"BOYET","id":"lll:5.2:80"},{"kind":"speech","text":"Say to her, we have measured many miles\nTo tread a measure with her on this grass.","sourceLine":"5.2.187","speaker":"FERDINAND","id":"lll:5.2:81"},{"kind":"speech","text":"They say, that they have measured many a mile\nTo tread a measure with you on this grass.","sourceLine":"5.2.189","speaker":"BOYET","id":"lll:5.2:82"},{"kind":"speech","text":"It is not so. Ask them how many inches\nIs in one mile: if they have measured many,\nThe measure then of one is easily told.","sourceLine":"5.2.191","speaker":"ROSALINE","id":"lll:5.2:83"},{"kind":"speech","text":"If to come hither you have measured miles,\nAnd many miles, the princess bids you tell\nHow many inches doth fill up one mile.","sourceLine":"5.2.194","speaker":"BOYET","id":"lll:5.2:84"},{"kind":"speech","text":"Tell her, we measure them by weary steps.","sourceLine":"5.2.197","speaker":"BIRON","id":"lll:5.2:85"},{"kind":"speech","text":"She hears herself.","sourceLine":"5.2.198","speaker":"BOYET","id":"lll:5.2:86"},{"kind":"speech","text":"How many weary steps,\nOf many weary miles you have o'ergone,\nAre number'd in the travel of one mile?","sourceLine":"5.2.199","speaker":"ROSALINE","id":"lll:5.2:87"},{"kind":"speech","text":"We number nothing that we spend for you:\nOur duty is so rich, so infinite,\nThat we may do it still without accompt.\nVouchsafe to show the sunshine of your face,\nThat we, like savages, may worship it.","sourceLine":"5.2.202","speaker":"BIRON","id":"lll:5.2:88"},{"kind":"speech","text":"My face is but a moon, and clouded too.","sourceLine":"5.2.207","speaker":"ROSALINE","id":"lll:5.2:89"},{"kind":"speech","text":"Blessed are clouds, to do as such clouds do!\nVouchsafe, bright moon, and these thy stars, to shine,\nThose clouds removed, upon our watery eyne.","sourceLine":"5.2.208","speaker":"FERDINAND","id":"lll:5.2:90"},{"kind":"speech","text":"O vain petitioner! beg a greater matter;\nThou now request'st but moonshine in the water.","sourceLine":"5.2.211","speaker":"ROSALINE","id":"lll:5.2:91"},{"kind":"speech","text":"Then, in our measure do but vouchsafe one change.\nThou bid'st me beg: this begging is not strange.","sourceLine":"5.2.213","speaker":"FERDINAND","id":"lll:5.2:92"},{"kind":"speech","text":"Play, music, then! Nay, you must do it soon.","sourceLine":"5.2.215","speaker":"ROSALINE","id":"lll:5.2:93"},{"kind":"stage","text":"Music plays","id":"lll:5.2:94"},{"kind":"speech","text":"Not yet! no dance! Thus change I like the moon.","sourceLine":"5.2.216","speaker":"ROSALINE","id":"lll:5.2:95"},{"kind":"speech","text":"Will you not dance? How come you thus estranged?","sourceLine":"5.2.217","speaker":"FERDINAND","id":"lll:5.2:96"},{"kind":"speech","text":"You took the moon at full, but now she's changed.","sourceLine":"5.2.218","speaker":"ROSALINE","id":"lll:5.2:97"},{"kind":"speech","text":"Yet still she is the moon, and I the man.\nThe music plays; vouchsafe some motion to it.","sourceLine":"5.2.219","speaker":"FERDINAND","id":"lll:5.2:98"},{"kind":"speech","text":"Our ears vouchsafe it.","sourceLine":"5.2.221","speaker":"ROSALINE","id":"lll:5.2:99"},{"kind":"speech","text":"But your legs should do it.","sourceLine":"5.2.222","speaker":"FERDINAND","id":"lll:5.2:100"},{"kind":"speech","text":"Since you are strangers and come here by chance,\nWe'll not be nice: take hands. We will not dance.","sourceLine":"5.2.223","speaker":"ROSALINE","id":"lll:5.2:101"},{"kind":"speech","text":"Why take we hands, then?","sourceLine":"5.2.225","speaker":"FERDINAND","id":"lll:5.2:102"},{"kind":"speech","text":"Only to part friends:\nCurtsy, sweet hearts; and so the measure ends.","sourceLine":"5.2.226","speaker":"ROSALINE","id":"lll:5.2:103"},{"kind":"speech","text":"More measure of this measure; be not nice.","sourceLine":"5.2.228","speaker":"FERDINAND","id":"lll:5.2:104"},{"kind":"speech","text":"We can afford no more at such a price.","sourceLine":"5.2.229","speaker":"ROSALINE","id":"lll:5.2:105"},{"kind":"speech","text":"Prize you yourselves: what buys your company?","sourceLine":"5.2.230","speaker":"FERDINAND","id":"lll:5.2:106"},{"kind":"speech","text":"Your absence only.","sourceLine":"5.2.231","speaker":"ROSALINE","id":"lll:5.2:107"},{"kind":"speech","text":"That can never be.","sourceLine":"5.2.232","speaker":"FERDINAND","id":"lll:5.2:108"},{"kind":"speech","text":"Then cannot we be bought: and so, adieu;\nTwice to your visor, and half once to you.","sourceLine":"5.2.233","speaker":"ROSALINE","id":"lll:5.2:109"},{"kind":"speech","text":"If you deny to dance, let's hold more chat.","sourceLine":"5.2.235","speaker":"FERDINAND","id":"lll:5.2:110"},{"kind":"speech","text":"In private, then.","sourceLine":"5.2.236","speaker":"ROSALINE","id":"lll:5.2:111"},{"kind":"speech","text":"I am best pleased with that.","sourceLine":"5.2.237","speaker":"FERDINAND","id":"lll:5.2:112"},{"kind":"stage","text":"They converse apart","id":"lll:5.2:113"},{"kind":"speech","text":"White-handed mistress, one sweet word with thee.","sourceLine":"5.2.238","speaker":"BIRON","id":"lll:5.2:114"},{"kind":"speech","text":"Honey, and milk, and sugar; there is three.","sourceLine":"5.2.239","speaker":"PRINCESS","id":"lll:5.2:115"},{"kind":"speech","text":"Nay then, two treys, and if you grow so nice,\nMetheglin, wort, and malmsey: well run, dice!\nThere's half-a-dozen sweets.","sourceLine":"5.2.240","speaker":"BIRON","id":"lll:5.2:116"},{"kind":"speech","text":"Seventh sweet, adieu:\nSince you can cog, I'll play no more with you.","sourceLine":"5.2.243","speaker":"PRINCESS","id":"lll:5.2:117"},{"kind":"speech","text":"One word in secret.","sourceLine":"5.2.245","speaker":"BIRON","id":"lll:5.2:118"},{"kind":"speech","text":"Let it not be sweet.","sourceLine":"5.2.246","speaker":"PRINCESS","id":"lll:5.2:119"},{"kind":"speech","text":"Thou grievest my gall.","sourceLine":"5.2.247","speaker":"BIRON","id":"lll:5.2:120"},{"kind":"speech","text":"Gall! bitter.","sourceLine":"5.2.248","speaker":"PRINCESS","id":"lll:5.2:121"},{"kind":"speech","text":"Therefore meet.","sourceLine":"5.2.249","speaker":"BIRON","id":"lll:5.2:122"},{"kind":"stage","text":"They converse apart","id":"lll:5.2:123"},{"kind":"speech","text":"Will you vouchsafe with me to change a word?","sourceLine":"5.2.250","speaker":"DUMAIN","id":"lll:5.2:124"},{"kind":"speech","text":"Name it.","sourceLine":"5.2.251","speaker":"MARIA","id":"lll:5.2:125"},{"kind":"speech","text":"Fair lady,--","sourceLine":"5.2.252","speaker":"DUMAIN","id":"lll:5.2:126"},{"kind":"speech","text":"Say you so? Fair lord,--\nTake that for your fair lady.","sourceLine":"5.2.253","speaker":"MARIA","id":"lll:5.2:127"},{"kind":"speech","text":"Please it you,\nAs much in private, and I'll bid adieu.","sourceLine":"5.2.255","speaker":"DUMAIN","id":"lll:5.2:128"},{"kind":"stage","text":"They converse apart","id":"lll:5.2:129"},{"kind":"speech","text":"What, was your vizard made without a tongue?","sourceLine":"5.2.257","speaker":"KATHARINE","id":"lll:5.2:130"},{"kind":"speech","text":"I know the reason, lady, why you ask.","sourceLine":"5.2.258","speaker":"LONGAVILLE","id":"lll:5.2:131"},{"kind":"speech","text":"O for your reason! quickly, sir; I long.","sourceLine":"5.2.259","speaker":"KATHARINE","id":"lll:5.2:132"},{"kind":"speech","text":"You have a double tongue within your mask,\nAnd would afford my speechless vizard half.","sourceLine":"5.2.260","speaker":"LONGAVILLE","id":"lll:5.2:133"},{"kind":"speech","text":"Veal, quoth the Dutchman. Is not 'veal' a calf?","sourceLine":"5.2.262","speaker":"KATHARINE","id":"lll:5.2:134"},{"kind":"speech","text":"A calf, fair lady!","sourceLine":"5.2.263","speaker":"LONGAVILLE","id":"lll:5.2:135"},{"kind":"speech","text":"No, a fair lord calf.","sourceLine":"5.2.264","speaker":"KATHARINE","id":"lll:5.2:136"},{"kind":"speech","text":"Let's part the word.","sourceLine":"5.2.265","speaker":"LONGAVILLE","id":"lll:5.2:137"},{"kind":"speech","text":"No, I'll not be your half\nTake all, and wean it; it may prove an ox.","sourceLine":"5.2.266","speaker":"KATHARINE","id":"lll:5.2:138"},{"kind":"speech","text":"Look, how you butt yourself in these sharp mocks!\nWill you give horns, chaste lady? do not so.","sourceLine":"5.2.268","speaker":"LONGAVILLE","id":"lll:5.2:139"},{"kind":"speech","text":"Then die a calf, before your horns do grow.","sourceLine":"5.2.270","speaker":"KATHARINE","id":"lll:5.2:140"},{"kind":"speech","text":"One word in private with you, ere I die.","sourceLine":"5.2.271","speaker":"LONGAVILLE","id":"lll:5.2:141"},{"kind":"speech","text":"Bleat softly then; the butcher hears you cry.","sourceLine":"5.2.272","speaker":"KATHARINE","id":"lll:5.2:142"},{"kind":"stage","text":"They converse apart","id":"lll:5.2:143"},{"kind":"speech","text":"The tongues of mocking wenches are as keen\nAs is the razor's edge invisible,\nCutting a smaller hair than may be seen,\nAbove the sense of sense; so sensible\nSeemeth their conference; their conceits have wings\nFleeter than arrows, bullets, wind, thought, swifter things.","sourceLine":"5.2.273","speaker":"BOYET","id":"lll:5.2:144"},{"kind":"speech","text":"Not one word more, my maids; break off, break off.","sourceLine":"5.2.279","speaker":"ROSALINE","id":"lll:5.2:145"},{"kind":"speech","text":"By heaven, all dry-beaten with pure scoff!","sourceLine":"5.2.280","speaker":"BIRON","id":"lll:5.2:146"},{"kind":"speech","text":"Farewell, mad wenches; you have simple wits.","sourceLine":"5.2.281","speaker":"FERDINAND","id":"lll:5.2:147"},{"kind":"speech","text":"Twenty adieus, my frozen Muscovits.","sourceLine":"5.2.282","speaker":"PRINCESS","id":"lll:5.2:148"},{"kind":"stage","text":"Exeunt FERDINAND, Lords, and Blackamoors","id":"lll:5.2:149"},{"kind":"speech","text":"Are these the breed of wits so wonder'd at?","sourceLine":"5.2.283","speaker":"PRINCESS","id":"lll:5.2:150"},{"kind":"speech","text":"Tapers they are, with your sweet breaths puff'd out.","sourceLine":"5.2.284","speaker":"BOYET","id":"lll:5.2:151"},{"kind":"speech","text":"Well-liking wits they have; gross, gross; fat, fat.","sourceLine":"5.2.285","speaker":"ROSALINE","id":"lll:5.2:152"},{"kind":"speech","text":"O poverty in wit, kingly-poor flout!\nWill they not, think you, hang themselves tonight?\nOr ever, but in vizards, show their faces?\nThis pert Biron was out of countenance quite.","sourceLine":"5.2.286","speaker":"PRINCESS","id":"lll:5.2:153"},{"kind":"speech","text":"O, they were all in lamentable cases!\nThe king was weeping-ripe for a good word.","sourceLine":"5.2.290","speaker":"ROSALINE","id":"lll:5.2:154"},{"kind":"speech","text":"Biron did swear himself out of all suit.","sourceLine":"5.2.292","speaker":"PRINCESS","id":"lll:5.2:155"},{"kind":"speech","text":"Dumain was at my service, and his sword:\nNo point, quoth I; my servant straight was mute.","sourceLine":"5.2.293","speaker":"MARIA","id":"lll:5.2:156"},{"kind":"speech","text":"Lord Longaville said, I came o'er his heart;\nAnd trow you what he called me?","sourceLine":"5.2.295","speaker":"KATHARINE","id":"lll:5.2:157"},{"kind":"speech","text":"Qualm, perhaps.","sourceLine":"5.2.297","speaker":"PRINCESS","id":"lll:5.2:158"},{"kind":"speech","text":"Yes, in good faith.","sourceLine":"5.2.298","speaker":"KATHARINE","id":"lll:5.2:159"},{"kind":"speech","text":"Go, sickness as thou art!","sourceLine":"5.2.299","speaker":"PRINCESS","id":"lll:5.2:160"},{"kind":"speech","text":"Well, better wits have worn plain statute-caps.\nBut will you hear? the king is my love sworn.","sourceLine":"5.2.300","speaker":"ROSALINE","id":"lll:5.2:161"},{"kind":"speech","text":"And quick Biron hath plighted faith to me.","sourceLine":"5.2.302","speaker":"PRINCESS","id":"lll:5.2:162"},{"kind":"speech","text":"And Longaville was for my service born.","sourceLine":"5.2.303","speaker":"KATHARINE","id":"lll:5.2:163"},{"kind":"speech","text":"Dumain is mine, as sure as bark on tree.","sourceLine":"5.2.304","speaker":"MARIA","id":"lll:5.2:164"},{"kind":"speech","text":"Madam, and pretty mistresses, give ear:\nImmediately they will again be here\nIn their own shapes; for it can never be\nThey will digest this harsh indignity.","sourceLine":"5.2.305","speaker":"BOYET","id":"lll:5.2:165"},{"kind":"speech","text":"Will they return?","sourceLine":"5.2.309","speaker":"PRINCESS","id":"lll:5.2:166"},{"kind":"speech","text":"They will, they will, God knows,\nAnd leap for joy, though they are lame with blows:\nTherefore change favours; and, when they repair,\nBlow like sweet roses in this summer air.","sourceLine":"5.2.310","speaker":"BOYET","id":"lll:5.2:167"},{"kind":"speech","text":"How blow? how blow? speak to be understood.","sourceLine":"5.2.314","speaker":"PRINCESS","id":"lll:5.2:168"},{"kind":"speech","text":"Fair ladies mask'd are roses in their bud;\nDismask'd, their damask sweet commixture shown,\nAre angels vailing clouds, or roses blown.","sourceLine":"5.2.315","speaker":"BOYET","id":"lll:5.2:169"},{"kind":"speech","text":"Avaunt, perplexity! What shall we do,\nIf they return in their own shapes to woo?","sourceLine":"5.2.318","speaker":"PRINCESS","id":"lll:5.2:170"},{"kind":"speech","text":"Good madam, if by me you'll be advised,\nLet's, mock them still, as well known as disguised:\nLet us complain to them what fools were here,\nDisguised like Muscovites, in shapeless gear;\nAnd wonder what they were and to what end\nTheir shallow shows and prologue vilely penn'd\nAnd their rough carriage so ridiculous,\nShould be presented at our tent to us.","sourceLine":"5.2.320","speaker":"ROSALINE","id":"lll:5.2:171"},{"kind":"speech","text":"Ladies, withdraw: the gallants are at hand.","sourceLine":"5.2.328","speaker":"BOYET","id":"lll:5.2:172"},{"kind":"speech","text":"Whip to our tents, as roes run o'er land.","sourceLine":"5.2.329","speaker":"PRINCESS","id":"lll:5.2:173"},{"kind":"stage","text":"Exeunt PRINCESS, ROSALINE, KATHARINE, and MARIA","id":"lll:5.2:174"},{"kind":"stage","text":"Re-enter FERDINAND, BIRON, LONGAVILLE, and DUMAIN, in their proper habits","id":"lll:5.2:175"},{"kind":"speech","text":"Fair sir, God save you! Where's the princess?","sourceLine":"5.2.330","speaker":"FERDINAND","id":"lll:5.2:176"},{"kind":"speech","text":"Gone to her tent. Please it your majesty\nCommand me any service to her thither?","sourceLine":"5.2.331","speaker":"BOYET","id":"lll:5.2:177"},{"kind":"speech","text":"That she vouchsafe me audience for one word.","sourceLine":"5.2.333","speaker":"FERDINAND","id":"lll:5.2:178"},{"kind":"speech","text":"I will; and so will she, I know, my lord.","sourceLine":"5.2.334","speaker":"BOYET","id":"lll:5.2:179"},{"kind":"stage","text":"Exit","id":"lll:5.2:180"},{"kind":"speech","text":"This fellow pecks up wit as pigeons pease,\nAnd utters it again when God doth please:\nHe is wit's pedler, and retails his wares\nAt wakes and wassails, meetings, markets, fairs;\nAnd we that sell by gross, the Lord doth know,\nHave not the grace to grace it with such show.\nThis gallant pins the wenches on his sleeve;\nHad he been Adam, he had tempted Eve;\nA' can carve too, and lisp: why, this is he\nThat kiss'd his hand away in courtesy;\nThis is the ape of form, monsieur the nice,\nThat, when he plays at tables, chides the dice\nIn honourable terms: nay, he can sing\nA mean most meanly; and in ushering\nMend him who can: the ladies call him sweet;\nThe stairs, as he treads on them, kiss his feet:\nThis is the flower that smiles on every one,\nTo show his teeth as white as whale's bone;\nAnd consciences, that will not die in debt,\nPay him the due of honey-tongued Boyet.","sourceLine":"5.2.335","speaker":"BIRON","id":"lll:5.2:181"},{"kind":"speech","text":"A blister on his sweet tongue, with my heart,\nThat put Armado's page out of his part!","sourceLine":"5.2.355","speaker":"FERDINAND","id":"lll:5.2:182"},{"kind":"speech","text":"See where it comes! Behavior, what wert thou\nTill this madman show'd thee? and what art thou now?","sourceLine":"5.2.357","speaker":"BIRON","id":"lll:5.2:183"},{"kind":"stage","text":"Re-enter the PRINCESS, ushered by BOYET, ROSALINE, MARIA, and KATHARINE","id":"lll:5.2:184"},{"kind":"speech","text":"All hail, sweet madam, and fair time of day!","sourceLine":"5.2.359","speaker":"FERDINAND","id":"lll:5.2:185"},{"kind":"speech","text":"'Fair' in 'all hail' is foul, as I conceive.","sourceLine":"5.2.360","speaker":"PRINCESS","id":"lll:5.2:186"},{"kind":"speech","text":"Construe my speeches better, if you may.","sourceLine":"5.2.361","speaker":"FERDINAND","id":"lll:5.2:187"},{"kind":"speech","text":"Then wish me better; I will give you leave.","sourceLine":"5.2.362","speaker":"PRINCESS","id":"lll:5.2:188"},{"kind":"speech","text":"We came to visit you, and purpose now\nTo lead you to our court; vouchsafe it then.","sourceLine":"5.2.363","speaker":"FERDINAND","id":"lll:5.2:189"},{"kind":"speech","text":"This field shall hold me; and so hold your vow:\nNor God, nor I, delights in perjured men.","sourceLine":"5.2.365","speaker":"PRINCESS","id":"lll:5.2:190"},{"kind":"speech","text":"Rebuke me not for that which you provoke:\nThe virtue of your eye must break my oath.","sourceLine":"5.2.367","speaker":"FERDINAND","id":"lll:5.2:191"},{"kind":"speech","text":"You nickname virtue; vice you should have spoke;\nFor virtue's office never breaks men's troth.\nNow by my maiden honour, yet as pure\nAs the unsullied lily, I protest,\nA world of torments though I should endure,\nI would not yield to be your house's guest;\nSo much I hate a breaking cause to be\nOf heavenly oaths, vow'd with integrity.","sourceLine":"5.2.369","speaker":"PRINCESS","id":"lll:5.2:192"},{"kind":"speech","text":"O, you have lived in desolation here,\nUnseen, unvisited, much to our shame.","sourceLine":"5.2.377","speaker":"FERDINAND","id":"lll:5.2:193"},{"kind":"speech","text":"Not so, my lord; it is not so, I swear;\nWe have had pastimes here and pleasant game:\nA mess of Russians left us but of late.","sourceLine":"5.2.379","speaker":"PRINCESS","id":"lll:5.2:194"},{"kind":"speech","text":"How, madam! Russians!","sourceLine":"5.2.382","speaker":"FERDINAND","id":"lll:5.2:195"},{"kind":"speech","text":"Ay, in truth, my lord;\nTrim gallants, full of courtship and of state.","sourceLine":"5.2.383","speaker":"PRINCESS","id":"lll:5.2:196"},{"kind":"speech","text":"Madam, speak true. It is not so, my lord:\nMy lady, to the manner of the days,\nIn courtesy gives undeserving praise.\nWe four indeed confronted were with four\nIn Russian habit: here they stay'd an hour,\nAnd talk'd apace; and in that hour, my lord,\nThey did not bless us with one happy word.\nI dare not call them fools; but this I think,\nWhen they are thirsty, fools would fain have drink.","sourceLine":"5.2.385","speaker":"ROSALINE","id":"lll:5.2:197"},{"kind":"speech","text":"This jest is dry to me. Fair gentle sweet,\nYour wit makes wise things foolish: when we greet,\nWith eyes best seeing, heaven's fiery eye,\nBy light we lose light: your capacity\nIs of that nature that to your huge store\nWise things seem foolish and rich things but poor.","sourceLine":"5.2.394","speaker":"BIRON","id":"lll:5.2:198"},{"kind":"speech","text":"This proves you wise and rich, for in my eye,--","sourceLine":"5.2.400","speaker":"ROSALINE","id":"lll:5.2:199"},{"kind":"speech","text":"I am a fool, and full of poverty.","sourceLine":"5.2.401","speaker":"BIRON","id":"lll:5.2:200"},{"kind":"speech","text":"But that you take what doth to you belong,\nIt were a fault to snatch words from my tongue.","sourceLine":"5.2.402","speaker":"ROSALINE","id":"lll:5.2:201"},{"kind":"speech","text":"O, I am yours, and all that I possess!","sourceLine":"5.2.404","speaker":"BIRON","id":"lll:5.2:202"},{"kind":"speech","text":"All the fool mine?","sourceLine":"5.2.405","speaker":"ROSALINE","id":"lll:5.2:203"},{"kind":"speech","text":"I cannot give you less.","sourceLine":"5.2.406","speaker":"BIRON","id":"lll:5.2:204"},{"kind":"speech","text":"Which of the vizards was it that you wore?","sourceLine":"5.2.407","speaker":"ROSALINE","id":"lll:5.2:205"},{"kind":"speech","text":"Where? when? what vizard? why demand you this?","sourceLine":"5.2.408","speaker":"BIRON","id":"lll:5.2:206"},{"kind":"speech","text":"There, then, that vizard; that superfluous case\nThat hid the worse and show'd the better face.","sourceLine":"5.2.409","speaker":"ROSALINE","id":"lll:5.2:207"},{"kind":"speech","text":"We are descried; they'll mock us now downright.","sourceLine":"5.2.411","speaker":"FERDINAND","id":"lll:5.2:208"},{"kind":"speech","text":"Let us confess and turn it to a jest.","sourceLine":"5.2.412","speaker":"DUMAIN","id":"lll:5.2:209"},{"kind":"speech","text":"Amazed, my lord? why looks your highness sad?","sourceLine":"5.2.413","speaker":"PRINCESS","id":"lll:5.2:210"},{"kind":"speech","text":"Help, hold his brows! he'll swoon! Why look you pale?\nSea-sick, I think, coming from Muscovy.","sourceLine":"5.2.414","speaker":"ROSALINE","id":"lll:5.2:211"},{"kind":"speech","text":"Thus pour the stars down plagues for perjury.\nCan any face of brass hold longer out?","sourceLine":"5.2.416","speaker":"BIRON","id":"lll:5.2:212"},{"kind":"speech","text":"Here stand I lady, dart thy skill at me;\nBruise me with scorn, confound me with a flout;\nThrust thy sharp wit quite through my ignorance;\nCut me to pieces with thy keen conceit;\nAnd I will wish thee never more to dance,\nNor never more in Russian habit wait.\nO, never will I trust to speeches penn'd,\nNor to the motion of a schoolboy's tongue,\nNor never come in vizard to my friend,\nNor woo in rhyme, like a blind harper's song!\nTaffeta phrases, silken terms precise,\nThree-piled hyperboles, spruce affectation,\nFigures pedantical; these summer-flies\nHave blown me full of maggot ostentation:\nI do forswear them; and I here protest,\nBy this white glove;--how white the hand, God knows!--\nHenceforth my wooing mind shall be express'd\nIn russet yeas and honest kersey noes:\nAnd, to begin, wench,--so God help me, la!--\nMy love to thee is sound, sans crack or flaw.","sourceLine":"5.2.418","speaker":"BIRON","sourceMarkupCorrection":{"workId":"lll","kind":"speaker_label_is_spoken_prefix","sectionId":"5.2","speechAnchor":"speech193","sourceLine":"5.2.418","originalSpeakerMarkup":"<A NAME=speech193><b>Here stand I</b></a>","rawLabelText":"Here stand I","rawNumberedLineText":"lady, dart thy skill at me;","speaker":"BIRON","preservation":"Move the exact existing source label words into the following speech, joined by one space. Preserve block IDs and all numbered-line text; do not import punctuation or wording from the corroborating edition.","evidence":{"url":"https://www.folger.edu/explore/shakespeares-works/loves-labors-lost/read/5/2/","edition":"Folger Shakespeare Library, Love’s Labor’s Lost, Act 5 Scene 2","support":"The passage belongs to Berowne (BIRON in the MIT spelling); Here stand I is dialogue, not a role label.","checked":"2026-10-12"}},"id":"lll:5.2:213"},{"kind":"speech","text":"Sans sans, I pray you.","sourceLine":"5.2.438","speaker":"ROSALINE","id":"lll:5.2:214"},{"kind":"speech","text":"Yet I have a trick\nOf the old rage: bear with me, I am sick;\nI'll leave it by degrees. Soft, let us see:\nWrite, 'Lord have mercy on us' on those three;\nThey are infected; in their hearts it lies;\nThey have the plague, and caught it of your eyes;\nThese lords are visited; you are not free,\nFor the Lord's tokens on you do I see.","sourceLine":"5.2.439","speaker":"BIRON","id":"lll:5.2:215"},{"kind":"speech","text":"No, they are free that gave these tokens to us.","sourceLine":"5.2.447","speaker":"PRINCESS","id":"lll:5.2:216"},{"kind":"speech","text":"Our states are forfeit: seek not to undo us.","sourceLine":"5.2.448","speaker":"BIRON","id":"lll:5.2:217"},{"kind":"speech","text":"It is not so; for how can this be true,\nThat you stand forfeit, being those that sue?","sourceLine":"5.2.449","speaker":"ROSALINE","id":"lll:5.2:218"},{"kind":"speech","text":"Peace! for I will not have to do with you.","sourceLine":"5.2.451","speaker":"BIRON","id":"lll:5.2:219"},{"kind":"speech","text":"Nor shall not, if I do as I intend.","sourceLine":"5.2.452","speaker":"ROSALINE","id":"lll:5.2:220"},{"kind":"speech","text":"Speak for yourselves; my wit is at an end.","sourceLine":"5.2.453","speaker":"BIRON","id":"lll:5.2:221"},{"kind":"speech","text":"Teach us, sweet madam, for our rude transgression\nSome fair excuse.","sourceLine":"5.2.454","speaker":"FERDINAND","id":"lll:5.2:222"},{"kind":"speech","text":"The fairest is confession.\nWere not you here but even now disguised?","sourceLine":"5.2.456","speaker":"PRINCESS","id":"lll:5.2:223"},{"kind":"speech","text":"Madam, I was.","sourceLine":"5.2.458","speaker":"FERDINAND","id":"lll:5.2:224"},{"kind":"speech","text":"And were you well advised?","sourceLine":"5.2.459","speaker":"PRINCESS","id":"lll:5.2:225"},{"kind":"speech","text":"I was, fair madam.","sourceLine":"5.2.460","speaker":"FERDINAND","id":"lll:5.2:226"},{"kind":"speech","text":"When you then were here,\nWhat did you whisper in your lady's ear?","sourceLine":"5.2.461","speaker":"PRINCESS","id":"lll:5.2:227"},{"kind":"speech","text":"That more than all the world I did respect her.","sourceLine":"5.2.463","speaker":"FERDINAND","id":"lll:5.2:228"},{"kind":"speech","text":"When she shall challenge this, you will reject her.","sourceLine":"5.2.464","speaker":"PRINCESS","id":"lll:5.2:229"},{"kind":"speech","text":"Upon mine honour, no.","sourceLine":"5.2.465","speaker":"FERDINAND","id":"lll:5.2:230"},{"kind":"speech","text":"Peace, peace! forbear:\nYour oath once broke, you force not to forswear.","sourceLine":"5.2.466","speaker":"PRINCESS","id":"lll:5.2:231"},{"kind":"speech","text":"Despise me, when I break this oath of mine.","sourceLine":"5.2.468","speaker":"FERDINAND","id":"lll:5.2:232"},{"kind":"speech","text":"I will: and therefore keep it. Rosaline,\nWhat did the Russian whisper in your ear?","sourceLine":"5.2.469","speaker":"PRINCESS","id":"lll:5.2:233"},{"kind":"speech","text":"Madam, he swore that he did hold me dear\nAs precious eyesight, and did value me\nAbove this world; adding thereto moreover\nThat he would wed me, or else die my lover.","sourceLine":"5.2.471","speaker":"ROSALINE","id":"lll:5.2:234"},{"kind":"speech","text":"God give thee joy of him! the noble lord\nMost honourably doth unhold his word.","sourceLine":"5.2.475","speaker":"PRINCESS","id":"lll:5.2:235"},{"kind":"speech","text":"What mean you, madam? by my life, my troth,\nI never swore this lady such an oath.","sourceLine":"5.2.477","speaker":"FERDINAND","id":"lll:5.2:236"},{"kind":"speech","text":"By heaven, you did; and to confirm it plain,\nYou gave me this: but take it, sir, again.","sourceLine":"5.2.479","speaker":"ROSALINE","id":"lll:5.2:237"},{"kind":"speech","text":"My faith and this the princess I did give:\nI knew her by this jewel on her sleeve.","sourceLine":"5.2.481","speaker":"FERDINAND","id":"lll:5.2:238"},{"kind":"speech","text":"Pardon me, sir, this jewel did she wear;\nAnd Lord Biron, I thank him, is my dear.\nWhat, will you have me, or your pearl again?","sourceLine":"5.2.483","speaker":"PRINCESS","id":"lll:5.2:239"},{"kind":"speech","text":"Neither of either; I remit both twain.\nI see the trick on't: here was a consent,\nKnowing aforehand of our merriment,\nTo dash it like a Christmas comedy:\nSome carry-tale, some please-man, some slight zany,\nSome mumble-news, some trencher-knight, some Dick,\nThat smiles his cheek in years and knows the trick\nTo make my lady laugh when she's disposed,\nTold our intents before; which once disclosed,\nThe ladies did change favours: and then we,\nFollowing the signs, woo'd but the sign of she.\nNow, to our perjury to add more terror,\nWe are again forsworn, in will and error.\nMuch upon this it is: and might not you","sourceLine":"5.2.486","speaker":"BIRON","id":"lll:5.2:240"},{"kind":"stage","text":"To BOYET","id":"lll:5.2:241"},{"kind":"speech","text":"Forestall our sport, to make us thus untrue?\nDo not you know my lady's foot by the squier,\nAnd laugh upon the apple of her eye?\nAnd stand between her back, sir, and the fire,\nHolding a trencher, jesting merrily?\nYou put our page out: go, you are allow'd;\nDie when you will, a smock shall be your shroud.\nYou leer upon me, do you? there's an eye\nWounds like a leaden sword.","sourceLine":"5.2.500","speaker":"BIRON","id":"lll:5.2:242"},{"kind":"speech","text":"Full merrily\nHath this brave manage, this career, been run.","sourceLine":"5.2.509","speaker":"BOYET","id":"lll:5.2:243"},{"kind":"speech","text":"Lo, he is tilting straight! Peace! I have done.","sourceLine":"5.2.511","speaker":"BIRON","id":"lll:5.2:244"},{"kind":"stage","text":"Enter COSTARD","id":"lll:5.2:245"},{"kind":"speech","text":"Welcome, pure wit! thou partest a fair fray.","sourceLine":"5.2.512","speaker":"BIRON","id":"lll:5.2:246"},{"kind":"speech","text":"O Lord, sir, they would know\nWhether the three Worthies shall come in or no.","sourceLine":"5.2.513","speaker":"COSTARD","id":"lll:5.2:247"},{"kind":"speech","text":"What, are there but three?","sourceLine":"5.2.515","speaker":"BIRON","id":"lll:5.2:248"},{"kind":"speech","text":"No, sir; but it is vara fine,\nFor every one pursents three.","sourceLine":"5.2.516","speaker":"COSTARD","id":"lll:5.2:249"},{"kind":"speech","text":"And three times thrice is nine.","sourceLine":"5.2.518","speaker":"BIRON","id":"lll:5.2:250"},{"kind":"speech","text":"Not so, sir; under correction, sir; I hope it is not so.\nYou cannot beg us, sir, I can assure you, sir we know\nwhat we know:\nI hope, sir, three times thrice, sir,--","sourceLine":"5.2.519","speaker":"COSTARD","id":"lll:5.2:251"},{"kind":"speech","text":"Is not nine.","sourceLine":"5.2.523","speaker":"BIRON","id":"lll:5.2:252"},{"kind":"speech","text":"Under correction, sir, we know whereuntil it doth amount.","sourceLine":"5.2.524","speaker":"COSTARD","id":"lll:5.2:253"},{"kind":"speech","text":"By Jove, I always took three threes for nine.","sourceLine":"5.2.525","speaker":"BIRON","id":"lll:5.2:254"},{"kind":"speech","text":"O Lord, sir, it were pity you should get your living\nby reckoning, sir.","sourceLine":"5.2.526","speaker":"COSTARD","id":"lll:5.2:255"},{"kind":"speech","text":"How much is it?","sourceLine":"5.2.528","speaker":"BIRON","id":"lll:5.2:256"},{"kind":"speech","text":"O Lord, sir, the parties themselves, the actors,\nsir, will show whereuntil it doth amount: for mine\nown part, I am, as they say, but to parfect one man\nin one poor man, Pompion the Great, sir.","sourceLine":"5.2.529","speaker":"COSTARD","id":"lll:5.2:257"},{"kind":"speech","text":"Art thou one of the Worthies?","sourceLine":"5.2.533","speaker":"BIRON","id":"lll:5.2:258"},{"kind":"speech","text":"It pleased them to think me worthy of Pompion the\nGreat: for mine own part, I know not the degree of\nthe Worthy, but I am to stand for him.","sourceLine":"5.2.534","speaker":"COSTARD","id":"lll:5.2:259"},{"kind":"speech","text":"Go, bid them prepare.","sourceLine":"5.2.537","speaker":"BIRON","id":"lll:5.2:260"},{"kind":"speech","text":"We will turn it finely off, sir; we will take\nsome care.","sourceLine":"5.2.538","speaker":"COSTARD","id":"lll:5.2:261"},{"kind":"stage","text":"Exit","id":"lll:5.2:262"},{"kind":"speech","text":"Biron, they will shame us: let them not approach.","sourceLine":"5.2.540","speaker":"FERDINAND","id":"lll:5.2:263"},{"kind":"speech","text":"We are shame-proof, my lord: and tis some policy\nTo have one show worse than the king's and his company.","sourceLine":"5.2.541","speaker":"BIRON","id":"lll:5.2:264"},{"kind":"speech","text":"I say they shall not come.","sourceLine":"5.2.543","speaker":"FERDINAND","id":"lll:5.2:265"},{"kind":"speech","text":"Nay, my good lord, let me o'errule you now:\nThat sport best pleases that doth least know how:\nWhere zeal strives to content, and the contents\nDies in the zeal of that which it presents:\nTheir form confounded makes most form in mirth,\nWhen great things labouring perish in their birth.","sourceLine":"5.2.544","speaker":"PRINCESS","id":"lll:5.2:266"},{"kind":"speech","text":"A right description of our sport, my lord.","sourceLine":"5.2.550","speaker":"BIRON","id":"lll:5.2:267"},{"kind":"stage","text":"Enter DON ADRIANO DE ARMADO","id":"lll:5.2:268"},{"kind":"speech","text":"Anointed, I implore so much expense of thy royal\nsweet breath as will utter a brace of words.","sourceLine":"5.2.552","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.551","rawPrefix":"DON","followingSpeechAnchor":"speech243","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6127,"originalHtml":"<A NAME=5.2.551>DON</A><br>\n</blockquote>\n\n<A NAME=speech243><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:269"},{"kind":"stage","text":"Converses apart with FERDINAND, and delivers him a paper","id":"lll:5.2:270"},{"kind":"speech","text":"Doth this man serve God?","sourceLine":"5.2.554","speaker":"PRINCESS","id":"lll:5.2:271"},{"kind":"speech","text":"Why ask you?","sourceLine":"5.2.555","speaker":"BIRON","id":"lll:5.2:272"},{"kind":"speech","text":"He speaks not like a man of God's making.","sourceLine":"5.2.556","speaker":"PRINCESS","id":"lll:5.2:273"},{"kind":"speech","text":"That is all one, my fair, sweet, honey monarch; for,\nI protest, the schoolmaster is exceeding\nfantastical; too, too vain, too too vain: but we\nwill put it, as they say, to fortuna de la guerra.\nI wish you the peace of mind, most royal couplement!","sourceLine":"5.2.558","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.557","rawPrefix":"DON","followingSpeechAnchor":"speech247","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6150,"originalHtml":"<A NAME=5.2.557>DON</A><br>\n</blockquote>\n\n<A NAME=speech247><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:274"},{"kind":"stage","text":"Exit","id":"lll:5.2:275"},{"kind":"speech","text":"Here is like to be a good presence of Worthies. He\npresents Hector of Troy; the swain, Pompey the\nGreat; the parish curate, Alexander; Armado's page,\nHercules; the pedant, Judas Maccabaeus: And if\nthese four Worthies in their first show thrive,\nThese four will change habits, and present the other five.","sourceLine":"5.2.563","speaker":"FERDINAND","id":"lll:5.2:276"},{"kind":"speech","text":"There is five in the first show.","sourceLine":"5.2.569","speaker":"BIRON","id":"lll:5.2:277"},{"kind":"speech","text":"You are deceived; 'tis not so.","sourceLine":"5.2.570","speaker":"FERDINAND","id":"lll:5.2:278"},{"kind":"speech","text":"The pedant, the braggart, the hedge-priest, the fool\nand the boy:--\nAbate throw at novum, and the whole world again\nCannot pick out five such, take each one in his vein.","sourceLine":"5.2.571","speaker":"BIRON","id":"lll:5.2:279"},{"kind":"speech","text":"The ship is under sail, and here she comes amain.","sourceLine":"5.2.575","speaker":"FERDINAND","id":"lll:5.2:280"},{"kind":"stage","text":"Enter COSTARD, for Pompey","id":"lll:5.2:281"},{"kind":"speech","text":"I Pompey am,--","sourceLine":"5.2.576","speaker":"COSTARD","id":"lll:5.2:282"},{"kind":"speech","text":"You lie, you are not he.","sourceLine":"5.2.577","speaker":"BOYET","id":"lll:5.2:283"},{"kind":"speech","text":"I Pompey am,--","sourceLine":"5.2.578","speaker":"COSTARD","id":"lll:5.2:284"},{"kind":"speech","text":"With libbard's head on knee.","sourceLine":"5.2.579","speaker":"BOYET","id":"lll:5.2:285"},{"kind":"speech","text":"Well said, old mocker: I must needs be friends\nwith thee.","sourceLine":"5.2.580","speaker":"BIRON","id":"lll:5.2:286"},{"kind":"speech","text":"I Pompey am, Pompey surnamed the Big--","sourceLine":"5.2.582","speaker":"COSTARD","id":"lll:5.2:287"},{"kind":"speech","text":"The Great.","sourceLine":"5.2.583","speaker":"DUMAIN","id":"lll:5.2:288"},{"kind":"speech","text":"It is, 'Great,' sir:--\nPompey surnamed the Great;\nThat oft in field, with targe and shield, did make\nmy foe to sweat:\nAnd travelling along this coast, I here am come by chance,\nAnd lay my arms before the legs of this sweet lass of France,\nIf your ladyship would say, 'Thanks, Pompey,' I had done.","sourceLine":"5.2.584","speaker":"COSTARD","id":"lll:5.2:289"},{"kind":"speech","text":"Great thanks, great Pompey.","sourceLine":"5.2.591","speaker":"PRINCESS","id":"lll:5.2:290"},{"kind":"speech","text":"'Tis not so much worth; but I hope I was perfect: I\nmade a little fault in 'Great.'","sourceLine":"5.2.592","speaker":"COSTARD","id":"lll:5.2:291"},{"kind":"speech","text":"My hat to a halfpenny, Pompey proves the best Worthy.","sourceLine":"5.2.594","speaker":"BIRON","id":"lll:5.2:292"},{"kind":"stage","text":"Enter SIR NATHANIEL, for Alexander","id":"lll:5.2:293"},{"kind":"speech","text":"When in the world I lived, I was the world's\ncommander;\nBy east, west, north, and south, I spread my\nconquering might:\nMy scutcheon plain declares that I am Alisander,--","sourceLine":"5.2.595","speaker":"SIR NATHANIEL","id":"lll:5.2:294"},{"kind":"speech","text":"Your nose says, no, you are not for it stands too right.","sourceLine":"5.2.600","speaker":"BOYET","id":"lll:5.2:295"},{"kind":"speech","text":"Your nose smells 'no' in this, most tender-smelling knight.","sourceLine":"5.2.601","speaker":"BIRON","id":"lll:5.2:296"},{"kind":"speech","text":"The conqueror is dismay'd. Proceed, good Alexander.","sourceLine":"5.2.602","speaker":"PRINCESS","id":"lll:5.2:297"},{"kind":"speech","text":"When in the world I lived, I was the world's\ncommander,--","sourceLine":"5.2.603","speaker":"SIR NATHANIEL","id":"lll:5.2:298"},{"kind":"speech","text":"Most true, 'tis right; you were so, Alisander.","sourceLine":"5.2.605","speaker":"BOYET","id":"lll:5.2:299"},{"kind":"speech","text":"Pompey the Great,--","sourceLine":"5.2.606","speaker":"BIRON","id":"lll:5.2:300"},{"kind":"speech","text":"Your servant, and Costard.","sourceLine":"5.2.607","speaker":"COSTARD","id":"lll:5.2:301"},{"kind":"speech","text":"Take away the conqueror, take away Alisander.","sourceLine":"5.2.608","speaker":"BIRON","id":"lll:5.2:302"},{"kind":"speech","text":"[To SIR NATHANIEL] O, sir, you have overthrown\nAlisander the conqueror! You will be scraped out of\nthe painted cloth for this: your lion, that holds\nhis poll-axe sitting on a close-stool, will be given\nto Ajax: he will be the ninth Worthy. A conqueror,\nand afeard to speak! run away for shame, Alisander.","sourceLine":"5.2.609","speaker":"COSTARD","id":"lll:5.2:303"},{"kind":"stage","text":"SIR NATHANIEL retires","id":"lll:5.2:304"},{"kind":"speech","text":"There, an't shall please you; a foolish mild man; an\nhonest man, look you, and soon dashed. He is a\nmarvellous good neighbour, faith, and a very good\nbowler: but, for Alisander,--alas, you see how\n'tis,--a little o'erparted. But there are Worthies\na-coming will speak their mind in some other sort.","sourceLine":"5.2.615","speaker":"COSTARD","id":"lll:5.2:305"},{"kind":"stage","text":"Enter HOLOFERNES, for Judas; and MOTH, for Hercules","id":"lll:5.2:306"},{"kind":"speech","text":"Great Hercules is presented by this imp,\nWhose club kill'd Cerberus, that three-headed canis;\nAnd when he was a babe, a child, a shrimp,\nThus did he strangle serpents in his manus.\nQuoniam he seemeth in minority,\nErgo I come with this apology.\nKeep some state in thy exit, and vanish.","sourceLine":"5.2.621","speaker":"HOLOFERNES","id":"lll:5.2:307"},{"kind":"stage","text":"MOTH retires","id":"lll:5.2:308"},{"kind":"speech","text":"Judas I am,--","sourceLine":"5.2.628","speaker":"HOLOFERNES","id":"lll:5.2:309"},{"kind":"speech","text":"A Judas!","sourceLine":"5.2.629","speaker":"DUMAIN","id":"lll:5.2:310"},{"kind":"speech","text":"Not Iscariot, sir.\nJudas I am, ycliped Maccabaeus.","sourceLine":"5.2.630","speaker":"HOLOFERNES","id":"lll:5.2:311"},{"kind":"speech","text":"Judas Maccabaeus clipt is plain Judas.","sourceLine":"5.2.632","speaker":"DUMAIN","id":"lll:5.2:312"},{"kind":"speech","text":"A kissing traitor. How art thou proved Judas?","sourceLine":"5.2.633","speaker":"BIRON","id":"lll:5.2:313"},{"kind":"speech","text":"Judas I am,--","sourceLine":"5.2.634","speaker":"HOLOFERNES","id":"lll:5.2:314"},{"kind":"speech","text":"The more shame for you, Judas.","sourceLine":"5.2.635","speaker":"DUMAIN","id":"lll:5.2:315"},{"kind":"speech","text":"What mean you, sir?","sourceLine":"5.2.636","speaker":"HOLOFERNES","id":"lll:5.2:316"},{"kind":"speech","text":"To make Judas hang himself.","sourceLine":"5.2.637","speaker":"BOYET","id":"lll:5.2:317"},{"kind":"speech","text":"Begin, sir; you are my elder.","sourceLine":"5.2.638","speaker":"HOLOFERNES","id":"lll:5.2:318"},{"kind":"speech","text":"Well followed: Judas was hanged on an elder.","sourceLine":"5.2.639","speaker":"BIRON","id":"lll:5.2:319"},{"kind":"speech","text":"I will not be put out of countenance.","sourceLine":"5.2.640","speaker":"HOLOFERNES","id":"lll:5.2:320"},{"kind":"speech","text":"Because thou hast no face.","sourceLine":"5.2.641","speaker":"BIRON","id":"lll:5.2:321"},{"kind":"speech","text":"What is this?","sourceLine":"5.2.642","speaker":"HOLOFERNES","id":"lll:5.2:322"},{"kind":"speech","text":"A cittern-head.","sourceLine":"5.2.643","speaker":"BOYET","id":"lll:5.2:323"},{"kind":"speech","text":"The head of a bodkin.","sourceLine":"5.2.644","speaker":"DUMAIN","id":"lll:5.2:324"},{"kind":"speech","text":"A Death's face in a ring.","sourceLine":"5.2.645","speaker":"BIRON","id":"lll:5.2:325"},{"kind":"speech","text":"The face of an old Roman coin, scarce seen.","sourceLine":"5.2.646","speaker":"LONGAVILLE","id":"lll:5.2:326"},{"kind":"speech","text":"The pommel of Caesar's falchion.","sourceLine":"5.2.647","speaker":"BOYET","id":"lll:5.2:327"},{"kind":"speech","text":"The carved-bone face on a flask.","sourceLine":"5.2.648","speaker":"DUMAIN","id":"lll:5.2:328"},{"kind":"speech","text":"Saint George's half-cheek in a brooch.","sourceLine":"5.2.649","speaker":"BIRON","id":"lll:5.2:329"},{"kind":"speech","text":"Ay, and in a brooch of lead.","sourceLine":"5.2.650","speaker":"DUMAIN","id":"lll:5.2:330"},{"kind":"speech","text":"Ay, and worn in the cap of a tooth-drawer.\nAnd now forward; for we have put thee in countenance.","sourceLine":"5.2.651","speaker":"BIRON","id":"lll:5.2:331"},{"kind":"speech","text":"You have put me out of countenance.","sourceLine":"5.2.653","speaker":"HOLOFERNES","id":"lll:5.2:332"},{"kind":"speech","text":"False; we have given thee faces.","sourceLine":"5.2.654","speaker":"BIRON","id":"lll:5.2:333"},{"kind":"speech","text":"But you have out-faced them all.","sourceLine":"5.2.655","speaker":"HOLOFERNES","id":"lll:5.2:334"},{"kind":"speech","text":"An thou wert a lion, we would do so.","sourceLine":"5.2.656","speaker":"BIRON","id":"lll:5.2:335"},{"kind":"speech","text":"Therefore, as he is an ass, let him go.\nAnd so adieu, sweet Jude! nay, why dost thou stay?","sourceLine":"5.2.657","speaker":"BOYET","id":"lll:5.2:336"},{"kind":"speech","text":"For the latter end of his name.","sourceLine":"5.2.659","speaker":"DUMAIN","id":"lll:5.2:337"},{"kind":"speech","text":"For the ass to the Jude; give it him:--Jud-as, away!","sourceLine":"5.2.660","speaker":"BIRON","id":"lll:5.2:338"},{"kind":"speech","text":"This is not generous, not gentle, not humble.","sourceLine":"5.2.661","speaker":"HOLOFERNES","id":"lll:5.2:339"},{"kind":"speech","text":"A light for Monsieur Judas! it grows dark, he may stumble.","sourceLine":"5.2.662","speaker":"BOYET","id":"lll:5.2:340"},{"kind":"stage","text":"HOLOFERNES retires","id":"lll:5.2:341"},{"kind":"speech","text":"Alas, poor Maccabaeus, how hath he been baited!","sourceLine":"5.2.663","speaker":"PRINCESS","id":"lll:5.2:342"},{"kind":"stage","text":"Enter DON ADRIANO DE ARMADO, for Hector","id":"lll:5.2:343"},{"kind":"speech","text":"Hide thy head, Achilles: here comes Hector in arms.","sourceLine":"5.2.664","speaker":"BIRON","id":"lll:5.2:344"},{"kind":"speech","text":"Though my mocks come home by me, I will now be merry.","sourceLine":"5.2.665","speaker":"DUMAIN","id":"lll:5.2:345"},{"kind":"speech","text":"Hector was but a Troyan in respect of this.","sourceLine":"5.2.666","speaker":"FERDINAND","id":"lll:5.2:346"},{"kind":"speech","text":"But is this Hector?","sourceLine":"5.2.667","speaker":"BOYET","id":"lll:5.2:347"},{"kind":"speech","text":"I think Hector was not so clean-timbered.","sourceLine":"5.2.668","speaker":"FERDINAND","id":"lll:5.2:348"},{"kind":"speech","text":"His leg is too big for Hector's.","sourceLine":"5.2.669","speaker":"LONGAVILLE","id":"lll:5.2:349"},{"kind":"speech","text":"More calf, certain.","sourceLine":"5.2.670","speaker":"DUMAIN","id":"lll:5.2:350"},{"kind":"speech","text":"No; he is best endued in the small.","sourceLine":"5.2.671","speaker":"BOYET","id":"lll:5.2:351"},{"kind":"speech","text":"This cannot be Hector.","sourceLine":"5.2.672","speaker":"BIRON","id":"lll:5.2:352"},{"kind":"speech","text":"He's a god or a painter; for he makes faces.","sourceLine":"5.2.673","speaker":"DUMAIN","id":"lll:5.2:353"},{"kind":"speech","text":"The armipotent Mars, of lances the almighty,\nGave Hector a gift,--","sourceLine":"5.2.675","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.674","rawPrefix":"DON","followingSpeechAnchor":"speech317","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6555,"originalHtml":"<A NAME=5.2.674>DON</A><br>\n</blockquote>\n\n<A NAME=speech317><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:354"},{"kind":"speech","text":"A gilt nutmeg.","sourceLine":"5.2.677","speaker":"DUMAIN","id":"lll:5.2:355"},{"kind":"speech","text":"A lemon.","sourceLine":"5.2.678","speaker":"BIRON","id":"lll:5.2:356"},{"kind":"speech","text":"Stuck with cloves.","sourceLine":"5.2.679","speaker":"LONGAVILLE","id":"lll:5.2:357"},{"kind":"speech","text":"No, cloven.","sourceLine":"5.2.680","speaker":"DUMAIN","id":"lll:5.2:358"},{"kind":"speech","text":"Peace!--\nThe armipotent Mars, of lances the almighty\nGave Hector a gift, the heir of Ilion;\nA man so breathed, that certain he would fight; yea\nFrom morn till night, out of his pavilion.\nI am that flower,--","sourceLine":"5.2.682","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.681","rawPrefix":"DON","followingSpeechAnchor":"speech322","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6582,"originalHtml":"<A NAME=5.2.681>DON</A><br>\n</blockquote>\n\n<A NAME=speech322><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:359"},{"kind":"speech","text":"That mint.","sourceLine":"5.2.688","speaker":"DUMAIN","id":"lll:5.2:360"},{"kind":"speech","text":"That columbine.","sourceLine":"5.2.689","speaker":"LONGAVILLE","id":"lll:5.2:361"},{"kind":"speech","text":"Sweet Lord Longaville, rein thy tongue.","sourceLine":"5.2.691","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.690","rawPrefix":"DON","followingSpeechAnchor":"speech325","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6603,"originalHtml":"<A NAME=5.2.690>DON</A><br>\n</blockquote>\n\n<A NAME=speech325><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:362"},{"kind":"speech","text":"I must rather give it the rein, for it runs against Hector.","sourceLine":"5.2.692","speaker":"LONGAVILLE","id":"lll:5.2:363"},{"kind":"speech","text":"Ay, and Hector's a greyhound.","sourceLine":"5.2.693","speaker":"DUMAIN","id":"lll:5.2:364"},{"kind":"speech","text":"The sweet war-man is dead and rotten; sweet chucks,\nbeat not the bones of the buried: when he breathed,\nhe was a man. But I will forward with my device.","sourceLine":"5.2.695","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.694","rawPrefix":"DON","followingSpeechAnchor":"speech328","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6619,"originalHtml":"<A NAME=5.2.694>DON</A><br>\n</blockquote>\n\n<A NAME=speech328><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:365"},{"kind":"stage","text":"To the PRINCESS","id":"lll:5.2:366"},{"kind":"speech","text":"Sweet royalty, bestow on me the sense of hearing.","sourceLine":"5.2.698","speaker":"DON ADRIANO DE ARMADO","id":"lll:5.2:367"},{"kind":"speech","text":"Speak, brave Hector: we are much delighted.","sourceLine":"5.2.699","speaker":"PRINCESS","id":"lll:5.2:368"},{"kind":"speech","text":"I do adore thy sweet grace's slipper.","sourceLine":"5.2.701","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.700","rawPrefix":"DON","followingSpeechAnchor":"speech330","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6634,"originalHtml":"<A NAME=5.2.700>DON</A><br>\n</blockquote>\n\n<A NAME=speech330><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:369"},{"kind":"speech","text":"[Aside to DUMAIN] Loves her by the foot,--","sourceLine":"5.2.702","speaker":"BOYET","id":"lll:5.2:370"},{"kind":"speech","text":"[Aside to BOYET] He may not by the yard.","sourceLine":"5.2.703","speaker":"DUMAIN","id":"lll:5.2:371"},{"kind":"speech","text":"This Hector far surmounted Hannibal,--","sourceLine":"5.2.705","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.704","rawPrefix":"DON","followingSpeechAnchor":"speech333","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6650,"originalHtml":"<A NAME=5.2.704>DON</A><br>\n</blockquote>\n\n<A NAME=speech333><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:372"},{"kind":"speech","text":"The party is gone, fellow Hector, she is gone; she\nis two months on her way.","sourceLine":"5.2.706","speaker":"COSTARD","id":"lll:5.2:373"},{"kind":"speech","text":"What meanest thou?","sourceLine":"5.2.709","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.708","rawPrefix":"DON","followingSpeechAnchor":"speech335","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6662,"originalHtml":"<A NAME=5.2.708>DON</A><br>\n</blockquote>\n\n<A NAME=speech335><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:374"},{"kind":"speech","text":"Faith, unless you play the honest Troyan, the poor\nwench is cast away: she's quick; the child brags in\nher belly already: tis yours.","sourceLine":"5.2.710","speaker":"COSTARD","id":"lll:5.2:375"},{"kind":"speech","text":"Dost thou infamonize me among potentates? thou shalt\ndie.","sourceLine":"5.2.714","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.713","rawPrefix":"DON","followingSpeechAnchor":"speech337","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6675,"originalHtml":"<A NAME=5.2.713>DON</A><br>\n</blockquote>\n\n<A NAME=speech337><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:376"},{"kind":"speech","text":"Then shall Hector be whipped for Jaquenetta that is\nquick by him and hanged for Pompey that is dead by\nhim.","sourceLine":"5.2.716","speaker":"COSTARD","id":"lll:5.2:377"},{"kind":"speech","text":"Most rare Pompey!","sourceLine":"5.2.719","speaker":"DUMAIN","id":"lll:5.2:378"},{"kind":"speech","text":"Renowned Pompey!","sourceLine":"5.2.720","speaker":"BOYET","id":"lll:5.2:379"},{"kind":"speech","text":"Greater than great, great, great, great Pompey!\nPompey the Huge!","sourceLine":"5.2.721","speaker":"BIRON","id":"lll:5.2:380"},{"kind":"speech","text":"Hector trembles.","sourceLine":"5.2.723","speaker":"DUMAIN","id":"lll:5.2:381"},{"kind":"speech","text":"Pompey is moved. More Ates, more Ates! stir them\non! stir them on!","sourceLine":"5.2.724","speaker":"BIRON","id":"lll:5.2:382"},{"kind":"speech","text":"Hector will challenge him.","sourceLine":"5.2.726","speaker":"DUMAIN","id":"lll:5.2:383"},{"kind":"speech","text":"Ay, if a' have no man's blood in's belly than will\nsup a flea.","sourceLine":"5.2.727","speaker":"BIRON","id":"lll:5.2:384"},{"kind":"speech","text":"By the north pole, I do challenge thee.","sourceLine":"5.2.730","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.729","rawPrefix":"DON","followingSpeechAnchor":"speech346","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6727,"originalHtml":"<A NAME=5.2.729>DON</A><br>\n</blockquote>\n\n<A NAME=speech346><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:385"},{"kind":"speech","text":"I will not fight with a pole, like a northern man:\nI'll slash; I'll do it by the sword. I bepray you,\nlet me borrow my arms again.","sourceLine":"5.2.731","speaker":"COSTARD","id":"lll:5.2:386"},{"kind":"speech","text":"Room for the incensed Worthies!","sourceLine":"5.2.734","speaker":"DUMAIN","id":"lll:5.2:387"},{"kind":"speech","text":"I'll do it in my shirt.","sourceLine":"5.2.735","speaker":"COSTARD","id":"lll:5.2:388"},{"kind":"speech","text":"Most resolute Pompey!","sourceLine":"5.2.736","speaker":"DUMAIN","id":"lll:5.2:389"},{"kind":"speech","text":"Master, let me take you a buttonhole lower. Do you\nnot see Pompey is uncasing for the combat? What mean\nyou? You will lose your reputation.","sourceLine":"5.2.737","speaker":"MOTH","id":"lll:5.2:390"},{"kind":"speech","text":"Gentlemen and soldiers, pardon me; I will not combat\nin my shirt.","sourceLine":"5.2.741","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.740","rawPrefix":"DON","followingSpeechAnchor":"speech352","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6762,"originalHtml":"<A NAME=5.2.740>DON</A><br>\n</blockquote>\n\n<A NAME=speech352><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:391"},{"kind":"speech","text":"You may not deny it: Pompey hath made the challenge.","sourceLine":"5.2.743","speaker":"DUMAIN","id":"lll:5.2:392"},{"kind":"speech","text":"Sweet bloods, I both may and will.","sourceLine":"5.2.745","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.744","rawPrefix":"DON","followingSpeechAnchor":"speech354","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6774,"originalHtml":"<A NAME=5.2.744>DON</A><br>\n</blockquote>\n\n<A NAME=speech354><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:393"},{"kind":"speech","text":"What reason have you for't?","sourceLine":"5.2.746","speaker":"BIRON","id":"lll:5.2:394"},{"kind":"speech","text":"The naked truth of it is, I have no shirt; I go\nwoolward for penance.","sourceLine":"5.2.748","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.747","rawPrefix":"DON","followingSpeechAnchor":"speech356","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6785,"originalHtml":"<A NAME=5.2.747>DON</A><br>\n</blockquote>\n\n<A NAME=speech356><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:395"},{"kind":"speech","text":"True, and it was enjoined him in Rome for want of\nlinen: since when, I'll be sworn, he wore none but\na dishclout of Jaquenetta's, and that a' wears next\nhis heart for a favour.","sourceLine":"5.2.750","speaker":"BOYET","id":"lll:5.2:396"},{"kind":"stage","text":"Enter MERCADE","id":"lll:5.2:397"},{"kind":"speech","text":"God save you, madam!","sourceLine":"5.2.754","speaker":"MERCADE","id":"lll:5.2:398"},{"kind":"speech","text":"Welcome, Mercade;\nBut that thou interrupt'st our merriment.","sourceLine":"5.2.755","speaker":"PRINCESS","id":"lll:5.2:399"},{"kind":"speech","text":"I am sorry, madam; for the news I bring\nIs heavy in my tongue. The king your father--","sourceLine":"5.2.757","speaker":"MERCADE","id":"lll:5.2:400"},{"kind":"speech","text":"Dead, for my life!","sourceLine":"5.2.759","speaker":"PRINCESS","id":"lll:5.2:401"},{"kind":"speech","text":"Even so; my tale is told.","sourceLine":"5.2.760","speaker":"MERCADE","id":"lll:5.2:402"},{"kind":"speech","text":"Worthies, away! the scene begins to cloud.","sourceLine":"5.2.761","speaker":"BIRON","id":"lll:5.2:403"},{"kind":"speech","text":"For mine own part, I breathe free breath. I have\nseen the day of wrong through the little hole of\ndiscretion, and I will right myself like a soldier.","sourceLine":"5.2.763","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.762","rawPrefix":"DON","followingSpeechAnchor":"speech364","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":6833,"originalHtml":"<A NAME=5.2.762>DON</A><br>\n</blockquote>\n\n<A NAME=speech364><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:404"},{"kind":"stage","text":"Exeunt Worthies","id":"lll:5.2:405"},{"kind":"speech","text":"How fares your majesty?","sourceLine":"5.2.766","speaker":"FERDINAND","id":"lll:5.2:406"},{"kind":"speech","text":"Boyet, prepare; I will away tonight.","sourceLine":"5.2.767","speaker":"PRINCESS","id":"lll:5.2:407"},{"kind":"speech","text":"Madam, not so; I do beseech you, stay.","sourceLine":"5.2.768","speaker":"FERDINAND","id":"lll:5.2:408"},{"kind":"speech","text":"Prepare, I say. I thank you, gracious lords,\nFor all your fair endeavors; and entreat,\nOut of a new-sad soul, that you vouchsafe\nIn your rich wisdom to excuse or hide\nThe liberal opposition of our spirits,\nIf over-boldly we have borne ourselves\nIn the converse of breath: your gentleness\nWas guilty of it. Farewell worthy lord!\nA heavy heart bears not a nimble tongue:\nExcuse me so, coming too short of thanks\nFor my great suit so easily obtain'd.","sourceLine":"5.2.769","speaker":"PRINCESS","id":"lll:5.2:409"},{"kind":"speech","text":"The extreme parts of time extremely forms\nAll causes to the purpose of his speed,\nAnd often at his very loose decides\nThat which long process could not arbitrate:\nAnd though the mourning brow of progeny\nForbid the smiling courtesy of love\nThe holy suit which fain it would convince,\nYet, since love's argument was first on foot,\nLet not the cloud of sorrow justle it\nFrom what it purposed; since, to wail friends lost\nIs not by much so wholesome-profitable\nAs to rejoice at friends but newly found.","sourceLine":"5.2.780","speaker":"FERDINAND","id":"lll:5.2:410"},{"kind":"speech","text":"I understand you not: my griefs are double.","sourceLine":"5.2.792","speaker":"PRINCESS","id":"lll:5.2:411"},{"kind":"speech","text":"Honest plain words best pierce the ear of grief;\nAnd by these badges understand the king.\nFor your fair sakes have we neglected time,\nPlay'd foul play with our oaths: your beauty, ladies,\nHath much deform'd us, fashioning our humours\nEven to the opposed end of our intents:\nAnd what in us hath seem'd ridiculous,--\nAs love is full of unbefitting strains,\nAll wanton as a child, skipping and vain,\nForm'd by the eye and therefore, like the eye,\nFull of strange shapes, of habits and of forms,\nVarying in subjects as the eye doth roll\nTo every varied object in his glance:\nWhich parti-coated presence of loose love\nPut on by us, if, in your heavenly eyes,\nHave misbecomed our oaths and gravities,\nThose heavenly eyes, that look into these faults,\nSuggested us to make. Therefore, ladies,\nOur love being yours, the error that love makes\nIs likewise yours: we to ourselves prove false,\nBy being once false for ever to be true\nTo those that make us both,--fair ladies, you:\nAnd even that falsehood, in itself a sin,\nThus purifies itself and turns to grace.","sourceLine":"5.2.793","speaker":"BIRON","id":"lll:5.2:412"},{"kind":"speech","text":"We have received your letters full of love;\nYour favours, the ambassadors of love;\nAnd, in our maiden council, rated them\nAt courtship, pleasant jest and courtesy,\nAs bombast and as lining to the time:\nBut more devout than this in our respects\nHave we not been; and therefore met your loves\nIn their own fashion, like a merriment.","sourceLine":"5.2.817","speaker":"PRINCESS","id":"lll:5.2:413"},{"kind":"speech","text":"Our letters, madam, show'd much more than jest.","sourceLine":"5.2.825","speaker":"DUMAIN","id":"lll:5.2:414"},{"kind":"speech","text":"So did our looks.","sourceLine":"5.2.826","speaker":"LONGAVILLE","id":"lll:5.2:415"},{"kind":"speech","text":"We did not quote them so.","sourceLine":"5.2.827","speaker":"ROSALINE","id":"lll:5.2:416"},{"kind":"speech","text":"Now, at the latest minute of the hour,\nGrant us your loves.","sourceLine":"5.2.828","speaker":"FERDINAND","id":"lll:5.2:417"},{"kind":"speech","text":"A time, methinks, too short\nTo make a world-without-end bargain in.\nNo, no, my lord, your grace is perjured much,\nFull of dear guiltiness; and therefore this:\nIf for my love, as there is no such cause,\nYou will do aught, this shall you do for me:\nYour oath I will not trust; but go with speed\nTo some forlorn and naked hermitage,\nRemote from all the pleasures of the world;\nThere stay until the twelve celestial signs\nHave brought about the annual reckoning.\nIf this austere insociable life\nChange not your offer made in heat of blood;\nIf frosts and fasts, hard lodging and thin weeds\nNip not the gaudy blossoms of your love,\nBut that it bear this trial and last love;\nThen, at the expiration of the year,\nCome challenge me, challenge me by these deserts,\nAnd, by this virgin palm now kissing thine\nI will be thine; and till that instant shut\nMy woeful self up in a mourning house,\nRaining the tears of lamentation\nFor the remembrance of my father's death.\nIf this thou do deny, let our hands part,\nNeither entitled in the other's heart.","sourceLine":"5.2.830","speaker":"PRINCESS","id":"lll:5.2:418"},{"kind":"speech","text":"If this, or more than this, I would deny,\nTo flatter up these powers of mine with rest,\nThe sudden hand of death close up mine eye!\nHence ever then my heart is in thy breast.","sourceLine":"5.2.855","speaker":"FERDINAND","id":"lll:5.2:419"},{"kind":"speech","text":"But what to me, my love? but what to me? A wife?","sourceLine":"5.2.859","speaker":"DUMAIN","id":"lll:5.2:420"},{"kind":"speech","text":"A beard, fair health, and honesty;\nWith three-fold love I wish you all these three.","sourceLine":"5.2.860","speaker":"KATHARINE","id":"lll:5.2:421"},{"kind":"speech","text":"O, shall I say, I thank you, gentle wife?","sourceLine":"5.2.862","speaker":"DUMAIN","id":"lll:5.2:422"},{"kind":"speech","text":"Not so, my lord; a twelvemonth and a day\nI'll mark no words that smooth-faced wooers say:\nCome when the king doth to my lady come;\nThen, if I have much love, I'll give you some.","sourceLine":"5.2.863","speaker":"KATHARINE","id":"lll:5.2:423"},{"kind":"speech","text":"I'll serve thee true and faithfully till then.","sourceLine":"5.2.867","speaker":"DUMAIN","id":"lll:5.2:424"},{"kind":"speech","text":"Yet swear not, lest ye be forsworn again.","sourceLine":"5.2.868","speaker":"KATHARINE","id":"lll:5.2:425"},{"kind":"speech","text":"What says Maria?","sourceLine":"5.2.869","speaker":"LONGAVILLE","id":"lll:5.2:426"},{"kind":"speech","text":"At the twelvemonth's end\nI'll change my black gown for a faithful friend.","sourceLine":"5.2.870","speaker":"MARIA","id":"lll:5.2:427"},{"kind":"speech","text":"I'll stay with patience; but the time is long.","sourceLine":"5.2.872","speaker":"LONGAVILLE","id":"lll:5.2:428"},{"kind":"speech","text":"The liker you; few taller are so young.","sourceLine":"5.2.873","speaker":"MARIA","id":"lll:5.2:429"},{"kind":"speech","text":"Studies my lady? mistress, look on me;\nBehold the window of my heart, mine eye,\nWhat humble suit attends thy answer there:\nImpose some service on me for thy love.","sourceLine":"5.2.874","speaker":"BIRON","id":"lll:5.2:430"},{"kind":"speech","text":"Oft have I heard of you, my Lord Biron,\nBefore I saw you; and the world's large tongue\nProclaims you for a man replete with mocks,\nFull of comparisons and wounding flouts,\nWhich you on all estates will execute\nThat lie within the mercy of your wit.\nTo weed this wormwood from your fruitful brain,\nAnd therewithal to win me, if you please,\nWithout the which I am not to be won,\nYou shall this twelvemonth term from day to day\nVisit the speechless sick and still converse\nWith groaning wretches; and your task shall be,\nWith all the fierce endeavor of your wit\nTo enforce the pained impotent to smile.","sourceLine":"5.2.878","speaker":"ROSALINE","id":"lll:5.2:431"},{"kind":"speech","text":"To move wild laughter in the throat of death?\nIt cannot be; it is impossible:\nMirth cannot move a soul in agony.","sourceLine":"5.2.892","speaker":"BIRON","id":"lll:5.2:432"},{"kind":"speech","text":"Why, that's the way to choke a gibing spirit,\nWhose influence is begot of that loose grace\nWhich shallow laughing hearers give to fools:\nA jest's prosperity lies in the ear\nOf him that hears it, never in the tongue\nOf him that makes it: then, if sickly ears,\nDeaf'd with the clamours of their own dear groans,\nWill hear your idle scorns, continue then,\nAnd I will have you and that fault withal;\nBut if they will not, throw away that spirit,\nAnd I shall find you empty of that fault,\nRight joyful of your reformation.","sourceLine":"5.2.895","speaker":"ROSALINE","id":"lll:5.2:433"},{"kind":"speech","text":"A twelvemonth! well; befall what will befall,\nI'll jest a twelvemonth in an hospital.","sourceLine":"5.2.907","speaker":"BIRON","id":"lll:5.2:434"},{"kind":"speech","text":"[To FERDINAND] Ay, sweet my lord; and so I take my leave.","sourceLine":"5.2.909","speaker":"PRINCESS","id":"lll:5.2:435"},{"kind":"speech","text":"No, madam; we will bring you on your way.","sourceLine":"5.2.910","speaker":"FERDINAND","id":"lll:5.2:436"},{"kind":"speech","text":"Our wooing doth not end like an old play;\nJack hath not Jill: these ladies' courtesy\nMight well have made our sport a comedy.","sourceLine":"5.2.911","speaker":"BIRON","id":"lll:5.2:437"},{"kind":"speech","text":"Come, sir, it wants a twelvemonth and a day,\nAnd then 'twill end.","sourceLine":"5.2.914","speaker":"FERDINAND","id":"lll:5.2:438"},{"kind":"speech","text":"That's too long for a play.","sourceLine":"5.2.916","speaker":"BIRON","id":"lll:5.2:439"},{"kind":"stage","text":"Re-enter DON ADRIANO DE ARMADO","id":"lll:5.2:440"},{"kind":"speech","text":"Sweet majesty, vouchsafe me,--","sourceLine":"5.2.918","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.917","rawPrefix":"DON","followingSpeechAnchor":"speech399","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":7130,"originalHtml":"<A NAME=5.2.917>DON</A><br>\n</blockquote>\n\n<A NAME=speech399><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:441"},{"kind":"speech","text":"Was not that Hector?","sourceLine":"5.2.919","speaker":"PRINCESS","id":"lll:5.2:442"},{"kind":"speech","text":"The worthy knight of Troy.","sourceLine":"5.2.920","speaker":"DUMAIN","id":"lll:5.2:443"},{"kind":"speech","text":"I will kiss thy royal finger, and take leave. I am\na votary; I have vowed to Jaquenetta to hold the\nplough for her sweet love three years. But, most\nesteemed greatness, will you hear the dialogue that\nthe two learned men have compiled in praise of the\nowl and the cuckoo? It should have followed in the\nend of our show.","sourceLine":"5.2.922","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.921","rawPrefix":"DON","followingSpeechAnchor":"speech402","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":7146,"originalHtml":"<A NAME=5.2.921>DON</A><br>\n</blockquote>\n\n<A NAME=speech402><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:444"},{"kind":"speech","text":"Call them forth quickly; we will do so.","sourceLine":"5.2.929","speaker":"FERDINAND","id":"lll:5.2:445"},{"kind":"speech","text":"Holla! approach.","sourceLine":"5.2.931","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.930","rawPrefix":"DON","followingSpeechAnchor":"speech404","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":7163,"originalHtml":"<A NAME=5.2.930>DON</A><br>\n</blockquote>\n\n<A NAME=speech404><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:446"},{"kind":"stage","text":"Re-enter HOLOFERNES, SIR NATHANIEL, MOTH, COSTARD, and others","id":"lll:5.2:447"},{"kind":"speech","text":"This side is Hiems, Winter, this Ver, the Spring;\nthe one maintained by the owl, the other by the\ncuckoo. Ver, begin.","sourceLine":"5.2.932","speaker":"DON ADRIANO DE ARMADO","id":"lll:5.2:448"},{"kind":"stage","text":"THE SONG","id":"lll:5.2:449"},{"kind":"speech","text":"SPRING.\nWhen daisies pied and violets blue\nAnd lady-smocks all silver-white\nAnd cuckoo-buds of yellow hue\nDo paint the meadows with delight,\nThe cuckoo then, on every tree,\nMocks married men; for thus sings he, Cuckoo;\nCuckoo, cuckoo: O word of fear,\nUnpleasing to a married ear!\nWhen shepherds pipe on oaten straws\nAnd merry larks are ploughmen's clocks,\nWhen turtles tread, and rooks, and daws,\nAnd maidens bleach their summer smocks\nThe cuckoo then, on every tree,\nMocks married men; for thus sings he, Cuckoo;\nCuckoo, cuckoo: O word of fear,\nUnpleasing to a married ear!\nWINTER.\nWhen icicles hang by the wall\nAnd Dick the shepherd blows his nail\nAnd Tom bears logs into the hall\nAnd milk comes frozen home in pail,\nWhen blood is nipp'd and ways be foul,\nThen nightly sings the staring owl, Tu-whit;\nTu-who, a merry note,\nWhile greasy Joan doth keel the pot.\nWhen all aloud the wind doth blow\nAnd coughing drowns the parson's saw\nAnd birds sit brooding in the snow\nAnd Marian's nose looks red and raw,\nWhen roasted crabs hiss in the bowl,\nThen nightly sings the staring owl, Tu-whit;\nTu-who, a merry note,\nWhile greasy Joan doth keel the pot.","sourceLine":"5.2.935","speaker":"DON ADRIANO DE ARMADO","id":"lll:5.2:450"},{"kind":"speech","text":"The words of Mercury are harsh after the songs of\nApollo. You that way: we this way.","sourceLine":"5.2.970","speaker":"DON ADRIANO DE ARMADO","sourceRolePrefix":{"archiveEntry":"lll/full.html","sourceAnchor":"5.2.969","rawPrefix":"DON","followingSpeechAnchor":"speech405","followingBoldLabel":"ADRIANO DE ARMADO","joinedLabel":"DON ADRIANO DE ARMADO","htmlLine":7208,"originalHtml":"<A NAME=5.2.969>DON</A><br>\n</blockquote>\n\n<A NAME=speech405><b>ADRIANO DE ARMADO</b>"},"id":"lll:5.2:451"},{"kind":"stage","text":"Exeunt","id":"lll:5.2:452"}],"scene":2}],"sourceLineCount":2864,"sourceExtractionRevision":"source-markup-corrections-v2","sourceMarkupCorrectionCount":1,"sourceSplitRoleExtractionRevision":"mit-split-role-prefixes-v1","sourceSplitRoleCount":101,"sourceLabel":"MIT Shakespeare","sectionCount":9,"blockCount":1189,"wordCount":21394};
